async fn enforce_task_grant_for_tool_invocation(
    state: &AppState,
    tool_name: &str,
    input: &ExecuteTool,
) -> Result<Option<TaskGrant>, AppError> {
    let workflow_run = workflow_run_for_session(state, input.session_id).await?;

    let Some(task_grant_id) = input.task_grant_id else {
        if let Some(run) = workflow_run {
            let reason = "task grant is required for workflow tool execution";
            record_task_grant_denied(
                state,
                input.session_id,
                None,
                Some(run.id),
                tool_name,
                reason,
            )
            .await?;
            return Err(AppError::forbidden(reason));
        }
        return Ok(None);
    };

    let grant = state.get_task_grant(task_grant_id).await?;
    let run = state.get_workflow_run(grant.workflow_run_id).await?;
    if workflow_run
        .as_ref()
        .is_some_and(|workflow_run| workflow_run.id != run.id)
        || !task_grant_session_matches(&grant, &run, input.session_id)
    {
        let reason = "task grant is not valid for this session";
        record_task_grant_denied(
            state,
            input.session_id,
            Some(&grant),
            Some(run.id),
            tool_name,
            reason,
        )
        .await?;
        return Err(AppError::forbidden(reason));
    }
    let session = state.get_session(input.session_id).await?;
    if grant
        .grantee_agent_id
        .is_some_and(|agent_id| agent_id != session.agent_id)
    {
        let reason = "task grant grantee agent does not match this session";
        record_task_grant_denied(
            state,
            input.session_id,
            Some(&grant),
            Some(run.id),
            tool_name,
            reason,
        )
        .await?;
        return Err(AppError::forbidden(reason));
    }
    if let Some(agent_class) = grant.agent_class.as_deref() {
        let agent = state.get_agent(session.agent_id).await?;
        if !task_grant_agent_class_matches(&agent, agent_class) {
            let reason = "task grant agent class does not match this session";
            record_task_grant_denied(
                state,
                input.session_id,
                Some(&grant),
                Some(run.id),
                tool_name,
                reason,
            )
            .await?;
            return Err(AppError::forbidden(reason));
        }
    }
    if grant.status != "active" {
        let reason = "task grant is not active";
        record_task_grant_denied(
            state,
            input.session_id,
            Some(&grant),
            Some(run.id),
            tool_name,
            reason,
        )
        .await?;
        return Err(AppError::forbidden(reason));
    }
    if grant
        .expires_at
        .is_some_and(|expires_at| expires_at <= Utc::now())
    {
        let reason = "task grant is expired";
        record_task_grant_denied(
            state,
            input.session_id,
            Some(&grant),
            Some(run.id),
            tool_name,
            reason,
        )
        .await?;
        return Err(AppError::forbidden(reason));
    }
    if !task_grant_allows_tool(&grant, tool_name) {
        let reason = "task grant tool scope does not allow tool";
        record_task_grant_denied(
            state,
            input.session_id,
            Some(&grant),
            Some(run.id),
            tool_name,
            reason,
        )
        .await?;
        return Err(AppError::forbidden(reason));
    }
    if let Some(reason) = task_grant_connector_invocation_denial(&grant, tool_name, &input.args)? {
        record_task_grant_denied(
            state,
            input.session_id,
            Some(&grant),
            Some(run.id),
            tool_name,
            &reason,
        )
        .await?;
        return Err(AppError::forbidden(reason));
    }

    record_task_grant_checked(state, &grant, input.session_id, tool_name).await?;
    Ok(Some(grant))
}

fn task_grant_session_matches(grant: &TaskGrant, run: &WorkflowRun, session_id: Uuid) -> bool {
    run.primary_session_id == session_id
        || grant.session_id == Some(session_id)
        || grant.grantee_session_id == Some(session_id)
}

fn task_grant_agent_class_matches(agent: &Agent, agent_class: &str) -> bool {
    let expected = agent_class.trim();
    expected.is_empty() || agent.kind == expected || agent.agent_role == expected
}

async fn workflow_run_for_session(
    state: &AppState,
    session_id: Uuid,
) -> Result<Option<WorkflowRun>, AppError> {
    let runs = state.list_workflow_runs().await?;
    if let Some(run) = runs
        .iter()
        .find(|run| run.primary_session_id == session_id)
        .cloned()
    {
        return Ok(Some(run));
    }
    for run in runs {
        if state
            .list_workflow_step_runs(run.id)
            .await?
            .into_iter()
            .any(|step| step.session_id == Some(session_id))
        {
            return Ok(Some(run));
        }
        if state
            .list_task_grants_for_workflow_run(run.id)
            .await?
            .into_iter()
            .any(|grant| task_grant_session_matches(&grant, &run, session_id))
        {
            return Ok(Some(run));
        }
    }
    Ok(None)
}

async fn active_task_grant_for_session(
    state: &AppState,
    session_id: Uuid,
) -> Result<Option<(WorkflowRun, TaskGrant)>, AppError> {
    let Some(run) = workflow_run_for_session(state, session_id).await? else {
        return Ok(None);
    };
    if run.primary_session_id == session_id {
        let root_task_grant_id = run
            .root_task_grant_id
            .ok_or_else(|| AppError::forbidden("task grant is required for workflow session"))?;
        let grant = state.get_task_grant(root_task_grant_id).await?;
        return Ok(Some((run, grant)));
    }
    let mut grants = state
        .list_task_grants_for_workflow_run(run.id)
        .await?
        .into_iter()
        .filter(|grant| grant.status == "active")
        .filter(|grant| task_grant_session_matches(grant, &run, session_id))
        .collect::<Vec<_>>();
    grants.sort_by_key(|grant| grant.created_at);
    let Some(grant) = grants.pop() else {
        return Err(AppError::forbidden(
            "task grant is required for workflow session",
        ));
    };
    Ok(Some((run, grant)))
}

fn task_grant_allows_tool(grant: &TaskGrant, tool_name: &str) -> bool {
    ["read", "write", "external_write"]
        .iter()
        .any(|key| json_string_array_contains(grant.tool_scope.get(*key), tool_name))
}

fn task_grant_connector_invocation_denial(
    grant: &TaskGrant,
    tool_name: &str,
    args: &Value,
) -> Result<Option<String>, AppError> {
    if tool_name == "mcp.call" {
        return task_grant_mcp_call_denial(grant, args);
    }
    if !native_connector_invocation_requested(tool_name, args) {
        return Ok(None);
    }
    let target = native_connector_call_target(args)?;
    let mode = grant
        .connector_scope
        .get("mode")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if mode != "commit_write" {
        return Ok(Some(
            "native connector side effects require commit_write connector scope".to_string(),
        ));
    }
    if !json_string_array_contains(
        grant.connector_scope.get("allowed_connector_ids"),
        &target.connector_id,
    ) {
        return Ok(Some(
            "task grant connector scope does not allow native connector id".to_string(),
        ));
    }
    if !json_string_array_contains(
        grant.connector_scope.get("allowed_tool_names"),
        &target.operation,
    ) && !json_string_array_contains(grant.connector_scope.get("allowed_tool_names"), tool_name)
    {
        return Ok(Some(
            "task grant connector scope does not allow native connector operation".to_string(),
        ));
    }
    if !task_grant_allows_side_effect_class(grant, &target.side_effect_class) {
        return Ok(Some(format!(
            "task grant side effect class {} is not allowed",
            target.side_effect_class
        )));
    }
    Ok(None)
}

fn task_grant_mcp_call_denial(grant: &TaskGrant, args: &Value) -> Result<Option<String>, AppError> {
    let request: McpCallRequest = serde_json::from_value(args.clone())?;
    let server = request.server.trim();
    let tool = request.tool.trim();
    if server.is_empty() || tool.is_empty() {
        return Ok(Some(
            "task grant connector scope requires MCP server and tool".to_string(),
        ));
    }
    let mode = grant
        .connector_scope
        .get("mode")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if !matches!(mode, "read_only" | "draft_write" | "commit_write") {
        return Ok(Some(
            "task grant connector scope does not allow MCP call mode".to_string(),
        ));
    }
    if !json_string_array_contains(grant.connector_scope.get("allowed_connector_ids"), server) {
        return Ok(Some(
            "task grant connector scope does not allow MCP server".to_string(),
        ));
    }
    if !json_string_array_contains(grant.connector_scope.get("allowed_tool_names"), tool) {
        return Ok(Some(
            "task grant connector scope does not allow MCP tool".to_string(),
        ));
    }
    if let Some(side_effect_class) = request
        .args
        .get("side_effect_class")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        if !task_grant_allows_side_effect_class(grant, side_effect_class) {
            return Ok(Some(format!(
                "task grant side effect class {} is not allowed",
                side_effect_class
            )));
        }
    }
    Ok(None)
}

fn task_grant_allows_side_effect_class(grant: &TaskGrant, side_effect_class: &str) -> bool {
    json_string_array_contains(
        grant.connector_scope.get("side_effect_classes"),
        side_effect_class,
    ) && grant
        .external_effects
        .get(side_effect_class)
        .and_then(Value::as_bool)
        == Some(true)
}

fn native_connector_invocation_requested(tool_name: &str, args: &Value) -> bool {
    tool_name == "native.connector.call"
        || args.get("connector_id").is_some()
        || args.get("connector").is_some()
}

#[derive(Debug, Clone)]
struct NativeConnectorCallTarget {
    connector_id: String,
    operation: String,
    side_effect_class: String,
}

fn native_connector_call_target(args: &Value) -> Result<NativeConnectorCallTarget, AppError> {
    let object = args
        .as_object()
        .ok_or_else(|| AppError::bad_request("native connector args must be a JSON object"))?;
    let connector_id = object
        .get("connector_id")
        .or_else(|| object.get("connector"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| AppError::bad_request("native connector call requires connector_id"))?
        .to_string();
    let operation = object
        .get("operation")
        .or_else(|| object.get("tool"))
        .or_else(|| object.get("action"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| AppError::bad_request("native connector call requires operation"))?
        .to_string();
    let side_effect_class = object
        .get("side_effect_class")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| AppError::bad_request("native connector call requires side_effect_class"))?
        .to_string();
    Ok(NativeConnectorCallTarget {
        connector_id,
        operation,
        side_effect_class,
    })
}

fn workflow_transition_filter_from_query(
    query: WorkflowTransitionQuery,
) -> Result<WorkflowTransitionFilter, AppError> {
    let limit = match query.limit {
        Some(limit) if limit == 0 || limit > 500 => {
            return Err(AppError::bad_request(
                "workflow transition filter limit must be between 1 and 500",
            ));
        }
        other => other,
    };
    Ok(WorkflowTransitionFilter {
        transition_type: normalize_optional_filter(query.transition_type),
        status: normalize_optional_filter(query.status),
        from_step_key: normalize_optional_filter(query.from_step_key),
        to_step_key: normalize_optional_filter(query.to_step_key),
        limit,
    })
}

fn normalize_optional_filter(value: Option<String>) -> Option<String> {
    value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

async fn build_task_board_snapshot(state: &AppState) -> Result<TaskBoardSnapshot, AppError> {
    let generated_at = Utc::now();
    let work_items = state
        .list_work_items()
        .await?
        .into_iter()
        .map(|item| (item.id, item))
        .collect::<HashMap<_, _>>();
    let runs = state.list_workflow_runs().await?;
    let mut items = Vec::new();
    let mut status_counts = BTreeMap::new();
    let mut workflow_step_count = 0usize;
    let mut claimable_count = 0usize;
    for run in &runs {
        let work_item = run
            .source_work_item_id
            .and_then(|work_item_id| work_items.get(&work_item_id));
        for step in state.list_workflow_step_runs(run.id).await? {
            workflow_step_count += 1;
            *status_counts.entry(step.status.clone()).or_insert(0) += 1;
            let blockers = workflow_step_claim_blockers(&step, step.agent_id, generated_at);
            let claimable = blockers.is_empty();
            if claimable {
                claimable_count += 1;
            }
            items.push(TaskBoardItem {
                work_item_id: run.source_work_item_id,
                work_item_title: work_item.map(|item| item.title.clone()),
                work_item_priority: work_item.map(|item| item.priority.clone()),
                workflow_run_id: run.id,
                workflow_definition_id: run.workflow_definition_id,
                workflow_step_run_id: step.id,
                step_key: step.step_key,
                step_type: step.step_type,
                agent_id: step.agent_id,
                task_grant_id: step.task_grant_id,
                context_packet_id: step.context_packet_id,
                status: step.status,
                claimable,
                blockers,
                claimed_by_worker: step.claimed_by_worker,
                lease_expires_at: step.lease_expires_at,
                updated_at: step.updated_at,
            });
        }
    }
    items.sort_by_key(|item| item.updated_at);
    items.reverse();
    Ok(TaskBoardSnapshot {
        generated_at,
        work_item_count: work_items.len(),
        workflow_run_count: runs.len(),
        workflow_step_count,
        claimable_count,
        status_counts,
        items,
    })
}

async fn build_agent_inbox_snapshot(
    state: &AppState,
    agent_id: Uuid,
) -> Result<AgentInboxSnapshot, AppError> {
    let generated_at = Utc::now();
    let work_items = state
        .list_work_items()
        .await?
        .into_iter()
        .map(|item| (item.id, item))
        .collect::<HashMap<_, _>>();
    let mut entries = Vec::new();
    for run in state.list_workflow_runs().await? {
        let work_item = run
            .source_work_item_id
            .and_then(|work_item_id| work_items.get(&work_item_id))
            .cloned();
        for step in state.list_workflow_step_runs(run.id).await? {
            if step.agent_id != Some(agent_id) || workflow_step_status_terminal(&step.status) {
                continue;
            }
            let blockers = workflow_step_claim_blockers(&step, Some(agent_id), generated_at);
            entries.push(AgentInboxEntry {
                workflow_run_id: run.id,
                workflow_definition_id: run.workflow_definition_id,
                workflow_step_run_id: step.id,
                step_key: step.step_key.clone(),
                step_type: step.step_type.clone(),
                status: step.status.clone(),
                task_grant_id: step.task_grant_id,
                context_packet_id: step.context_packet_id,
                work_item: work_item.clone(),
                claimable: blockers.is_empty(),
                blockers,
                claimed_by_worker: step.claimed_by_worker.clone(),
                lease_expires_at: step.lease_expires_at,
                input_summary: workflow_graph_console_summary(&step.input_payload),
                updated_at: step.updated_at,
            });
        }
    }
    entries.sort_by_key(|entry| entry.updated_at);
    entries.reverse();
    let claimable_count = entries.iter().filter(|entry| entry.claimable).count();
    Ok(AgentInboxSnapshot {
        agent_id,
        generated_at,
        entry_count: entries.len(),
        claimable_count,
        entries,
    })
}

fn workflow_step_claim_blockers(
    step: &WorkflowStepRun,
    expected_agent_id: Option<Uuid>,
    now: DateTime<Utc>,
) -> Vec<String> {
    let mut blockers = Vec::new();
    if workflow_step_status_terminal(&step.status) {
        blockers.push("terminal_status".to_string());
    }
    if step.status == "scheduled" {
        match step.scheduled_at {
            Some(scheduled_at) if scheduled_at > now => {
                blockers.push("scheduled_for_future".to_string())
            }
            Some(_) => blockers.push("scheduled_until_scheduler_activation".to_string()),
            None => blockers.push("scheduled_without_due_time".to_string()),
        }
    } else if step.status != "queued" {
        if step.status == "running" {
            if !step
                .lease_expires_at
                .is_some_and(|lease_expires_at| lease_expires_at <= now)
            {
                blockers.push("already_claimed".to_string());
            }
        } else {
            blockers.push(format!("status_{}", step.status));
        }
    }
    match (step.agent_id, expected_agent_id) {
        (None, _) => blockers.push("missing_agent_binding".to_string()),
        (Some(actual), Some(expected)) if actual != expected => {
            blockers.push("agent_mismatch".to_string())
        }
        _ => {}
    }
    if step.task_grant_id.is_none() {
        blockers.push("missing_task_grant".to_string());
    }
    blockers
}

async fn build_workflow_run_graph_console(
    state: &AppState,
    run: &WorkflowRun,
) -> Result<WorkflowRunGraphConsole, AppError> {
    let generated_at = Utc::now();
    let definition = state
        .get_workflow_definition(run.workflow_definition_id)
        .await?;
    let steps = state.list_workflow_step_runs(run.id).await?;
    let transitions = state.list_workflow_transitions(run.id).await?;
    let mut status_counts = BTreeMap::new();
    let due_scheduled_count = steps
        .iter()
        .filter(|step| {
            step.status == "scheduled"
                && step
                    .scheduled_at
                    .is_some_and(|scheduled_at| scheduled_at <= generated_at)
        })
        .count();
    let materialized_step_keys = steps
        .iter()
        .map(|step| step.step_key.clone())
        .collect::<BTreeSet<_>>();
    let mut nodes = steps
        .iter()
        .map(|step| -> Result<WorkflowGraphConsoleNode, AppError> {
            *status_counts.entry(step.status.clone()).or_insert(0) += 1;
            let graph_step = workflow_graph_step_by_key(&definition.step_graph, &step.step_key)?;
            let dependencies = graph_step
                .map(workflow_graph_step_dependencies)
                .transpose()?
                .unwrap_or_default();
            let definition_summary = graph_step
                .map(workflow_graph_console_summary)
                .unwrap_or_else(empty_json_object);
            Ok(WorkflowGraphConsoleNode {
                id: step.id,
                step_run_id: Some(step.id),
                step_key: step.step_key.clone(),
                step_type: step.step_type.clone(),
                status: step.status.clone(),
                declared: false,
                dependencies,
                agent_id: step.agent_id,
                task_grant_id: step.task_grant_id,
                context_packet_id: step.context_packet_id,
                claimed_by_worker: step.claimed_by_worker.clone(),
                lease_expires_at: step.lease_expires_at,
                scheduled_at: step.scheduled_at,
                due: step.status == "scheduled"
                    && step
                        .scheduled_at
                        .is_some_and(|scheduled_at| scheduled_at <= generated_at),
                started_at: step.started_at,
                completed_at: step.completed_at,
                definition_summary,
                input_summary: workflow_graph_console_summary(&step.input_payload),
                output_summary: workflow_graph_console_summary(&step.output_payload),
            })
        })
        .collect::<Result<Vec<_>, AppError>>()?;
    if let Some(graph_steps) = definition.step_graph.get("steps").and_then(Value::as_array) {
        for graph_step in graph_steps {
            let step_key = workflow_graph_step_key(graph_step)?;
            if materialized_step_keys.contains(&step_key) {
                continue;
            }
            let status = "declared".to_string();
            *status_counts.entry(status.clone()).or_insert(0) += 1;
            nodes.push(WorkflowGraphConsoleNode {
                id: workflow_graph_declared_node_id(run.id, &step_key),
                step_run_id: None,
                step_key: step_key.clone(),
                step_type: workflow_graph_step_type(graph_step),
                status,
                declared: true,
                dependencies: workflow_graph_step_dependencies(graph_step)?,
                agent_id: workflow_graph_step_agent_id(&definition, graph_step)?,
                task_grant_id: None,
                context_packet_id: None,
                claimed_by_worker: None,
                lease_expires_at: None,
                scheduled_at: None,
                due: false,
                started_at: None,
                completed_at: None,
                definition_summary: workflow_graph_console_summary(graph_step),
                input_summary: json!({
                    "source": "workflow_definition",
                    "graph_step": workflow_graph_console_summary(graph_step)
                }),
                output_summary: empty_json_object(),
            });
        }
    }
    let mut edges = transitions
        .iter()
        .map(|transition| WorkflowGraphConsoleEdge {
            id: transition.id,
            from_step_key: transition.from_step_key.clone(),
            to_step_key: transition.to_step_key.clone(),
            transition_type: transition.transition_type.clone(),
            status: transition.status.clone(),
            declared: false,
            condition_summary: workflow_graph_console_summary(&transition.condition_payload),
            result_summary: workflow_graph_console_summary(&transition.result_payload),
            created_at: transition.created_at,
        })
        .collect::<Vec<_>>();
    if let Some(graph_steps) = definition.step_graph.get("steps").and_then(Value::as_array) {
        for graph_step in graph_steps {
            let to_step_key = workflow_graph_step_key(graph_step)?;
            if materialized_step_keys.contains(&to_step_key) {
                continue;
            }
            for from_step_key in workflow_graph_step_dependencies(graph_step)? {
                edges.push(WorkflowGraphConsoleEdge {
                    id: workflow_graph_declared_edge_id(run.id, &from_step_key, &to_step_key),
                    from_step_key: Some(from_step_key),
                    to_step_key: Some(to_step_key.clone()),
                    transition_type: "declared_dependency".to_string(),
                    status: "declared".to_string(),
                    declared: true,
                    condition_summary: workflow_graph_console_summary(graph_step),
                    result_summary: empty_json_object(),
                    created_at: generated_at,
                });
            }
        }
    }
    Ok(WorkflowRunGraphConsole {
        workflow_run_id: run.id,
        workflow_definition_id: run.workflow_definition_id,
        pack_installation_id: run.pack_installation_id,
        generated_at,
        status: run.status.clone(),
        node_count: nodes.len(),
        edge_count: edges.len(),
        due_scheduled_count,
        status_counts,
        nodes,
        edges,
    })
}

fn workflow_graph_declared_node_id(run_id: Uuid, step_key: &str) -> Uuid {
    workflow_graph_deterministic_uuid(run_id, "declared-node", &[step_key])
}

fn workflow_graph_declared_edge_id(run_id: Uuid, from_step_key: &str, to_step_key: &str) -> Uuid {
    workflow_graph_deterministic_uuid(run_id, "declared-edge", &[from_step_key, to_step_key])
}

fn workflow_graph_deterministic_uuid(run_id: Uuid, kind: &str, parts: &[&str]) -> Uuid {
    let mut hasher = Sha256::new();
    hasher.update(b"mandoforge-workflow-graph-console");
    hasher.update(run_id.as_bytes());
    hasher.update(kind.as_bytes());
    for part in parts {
        hasher.update([0]);
        hasher.update(part.as_bytes());
    }
    let digest = hasher.finalize();
    let mut bytes = [0_u8; 16];
    bytes.copy_from_slice(&digest[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    Uuid::from_bytes(bytes)
}

fn workflow_graph_console_summary(value: &Value) -> Value {
    match value {
        Value::Object(object) => {
            let mut summary = serde_json::Map::new();
            summary.insert("field_count".to_string(), json!(object.len()));
            let keys = object.keys().take(8).cloned().collect::<Vec<_>>();
            summary.insert("keys".to_string(), json!(keys));
            for key in [
                "source",
                "retry",
                "fan_in",
                "fan_out",
                "branch",
                "skip_reason",
                "error",
                "result",
            ] {
                if let Some(item) = object.get(key) {
                    summary.insert(key.to_string(), item.clone());
                }
            }
            Value::Object(summary)
        }
        Value::Array(items) => json!({"array_length": items.len()}),
        other => other.clone(),
    }
}

async fn claim_workflow_step_run(
    state: &AppState,
    headers: &HeaderMap,
    current: WorkflowStepRun,
    run: WorkflowRun,
    input: ClaimWorkflowStepRun,
) -> Result<ClaimWorkflowStepRunResponse, AppError> {
    authorize_request(
        state,
        headers,
        Permission::SessionsRun,
        "session",
        Some(run.primary_session_id),
    )
    .await?;
    let principal = principal_from_request(state, headers).await?;
    let agent = state.get_agent(input.agent_id).await?;
    if current.agent_id != Some(agent.id) {
        return Err(AppError::forbidden(
            "workflow step is not assigned to the claiming agent",
        ));
    }
    let now = Utc::now();
    let blockers = workflow_step_claim_blockers(&current, Some(agent.id), now);
    if !blockers.is_empty() {
        return Err(AppError::bad_request(format!(
            "workflow step is not claimable: {}",
            blockers.join(", ")
        )));
    }
    let task_grant_id = current
        .task_grant_id
        .ok_or_else(|| AppError::bad_request("workflow step claim requires task grant"))?;
    let grant = state.get_task_grant(task_grant_id).await?;
    if grant.workflow_run_id != run.id {
        return Err(AppError::bad_request(
            "workflow step task grant must belong to workflow run",
        ));
    }
    if grant.status != "active" {
        return Err(AppError::forbidden(
            "workflow step task grant is not active",
        ));
    }
    if grant
        .grantee_agent_id
        .is_some_and(|grantee_agent_id| grantee_agent_id != agent.id)
    {
        return Err(AppError::forbidden(
            "workflow step task grant is not issued to the claiming agent",
        ));
    }
    if grant.expires_at.is_some_and(|expires_at| expires_at <= now) {
        return Err(AppError::forbidden("workflow step task grant is expired"));
    }
    let session_id = current.session_id.unwrap_or(run.primary_session_id);
    if !task_grant_session_matches(&grant, &run, session_id) {
        return Err(AppError::forbidden(
            "workflow step task grant is not valid for the step session",
        ));
    }
    let lease_seconds = input.lease_seconds.unwrap_or(300);
    if !(1..=86_400).contains(&lease_seconds) {
        return Err(AppError::bad_request(
            "workflow step claim lease_seconds must be between 1 and 86400",
        ));
    }
    let worker_id = input
        .worker_id
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| format!("agent:{}", agent.id));

    let context_packet = generate_and_persist_context_packet(state, session_id).await?;
    let task_grant = state
        .update_task_grant_context_packet(grant.id, context_packet.id)
        .await?;
    record_task_grant_checked(state, &task_grant, session_id, "agent_inbox.claim").await?;

    let mut next = current;
    next.status = "running".to_string();
    next.claimed_by_worker = Some(worker_id.clone());
    next.lease_expires_at = Some(now + ChronoDuration::seconds(lease_seconds));
    next.context_packet_id = Some(context_packet.id);
    next.started_at = next.started_at.or(Some(now));
    next.updated_at = now;
    let step = state.update_workflow_step_run(next).await?;
    record_agent_inbox_claimed(
        state,
        &run,
        &step,
        &task_grant,
        &context_packet,
        &principal.subject_id,
        &worker_id,
    )
    .await?;
    if let Some(work_item_id) = run.source_work_item_id {
        state
            .append_work_item_activity_entry(
                work_item_id,
                "agent_inbox.claimed",
                Some(principal.subject_id),
                Some("workflow_step_run"),
                Some(step.id),
                format!(
                    "Agent {} claimed workflow step {}",
                    agent.name, step.step_key
                ),
                json!({
                    "workflow_run_id": run.id,
                    "workflow_step_run_id": step.id,
                    "task_grant_id": task_grant.id,
                    "context_packet_id": context_packet.id,
                    "agent_id": agent.id,
                    "worker_id": worker_id,
                    "lease_expires_at": step.lease_expires_at
                }),
            )
            .await?;
    }
    Ok(ClaimWorkflowStepRunResponse {
        step,
        task_grant,
        context_packet,
    })
}

async fn run_workflow_delegated_runtime_step(
    state: &AppState,
    headers: &HeaderMap,
    current: WorkflowStepRun,
    run: WorkflowRun,
    input: RunWorkflowStepRun,
) -> Result<Json<RunWorkflowStepRunResponse>, AppError> {
    let agent_id = input
        .agent_id
        .or(current.agent_id)
        .ok_or_else(|| AppError::bad_request("delegated runtime step requires agent_id"))?;
    let worker_id = input
        .worker_id
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| {
            headers
                .get("x-mandoforge-worker-id")
                .and_then(|value| value.to_str().ok())
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string)
                .unwrap_or_else(|| format!("agent:{agent_id}"))
        });
    let claim = claim_workflow_step_run(
        state,
        headers,
        current,
        run.clone(),
        ClaimWorkflowStepRun {
            agent_id,
            worker_id: Some(worker_id.clone()),
            lease_seconds: input.lease_seconds,
        },
    )
    .await?;
    let session_id = claim.step.session_id.unwrap_or(run.primary_session_id);
    record_workflow_step_worker_started(
        state,
        &run,
        &claim.step,
        &worker_id,
        claim.context_packet.id,
    )
    .await?;
    let dispatch_event = state
        .append_event(
            "worker",
            Some(claim.step.id),
            session_id,
            "workflow.delegated_runtime.dispatch_requested",
            json!({
                "workflow_run_id": run.id,
                "workflow_step_run_id": claim.step.id,
                "worker_id": worker_id,
                "runtime_adapter": run.runtime_adapter,
                "runtime_mode": run.runtime_mode,
                "delegation_status": run.delegation_status,
                "runtime_envelope": run.runtime_envelope
            }),
        )
        .await?;
    let queued = enqueue_session_loop(
        state,
        session_id,
        Some(dispatch_event.id),
        "workflow.delegated_runtime.run",
    )
    .await?;
    let running_job = state.start_session_loop_job(queued.id, &worker_id).await?;
    state
        .append_event(
            "worker",
            Some(running_job.id),
            running_job.session_id,
            "session.loop.started",
            json!({
                "session_loop_job_id": running_job.id,
                "environment_id": running_job.environment_id,
                "worker_id": worker_id,
                "attempt_count": running_job.attempt_count,
                "workflow_step_run_id": claim.step.id,
                "delegated_runtime": true
            }),
        )
        .await?;

    let adapter = run.runtime_adapter.as_deref().unwrap_or("unconfigured");
    let execution = match adapter {
        "codex_app_server" => {
            run_codex_app_server_delegated_runtime(state, &run, &claim.step, &worker_id).await
        }
        "codex_cli" | "claude_code" => {
            run_agent_cli_delegated_runtime(state, &run, &claim.step, session_id, adapter).await
        }
        _ => Err(AppError::bad_request(format!(
            "delegated runtime adapter {adapter} requires an external worker adapter"
        ))),
    };

    match execution {
        Ok(output_payload) => {
            let delegated_status = delegated_runtime_output_status(&output_payload);
            if delegated_runtime_status_is_nonterminal(&delegated_status) {
                let completed_job = state
                    .complete_session_loop_job(running_job.id, &worker_id)
                    .await?;
                let session = set_managed_session_status(
                    state,
                    session_id,
                    SessionStatus::Running,
                    "delegated runtime is still running",
                )
                .await?;
                let previous_status = claim.step.status.clone();
                let now = Utc::now();
                let mut pending_step = claim.step.clone();
                pending_step.status = "running".to_string();
                pending_step.output_payload = json!({
                    "delegated_runtime": output_payload,
                    "worker_id": worker_id,
                    "session_loop_job_id": completed_job.id,
                    "context_packet_id": pending_step.context_packet_id,
                    "poll_status": delegated_status.clone()
                });
                pending_step.lease_expires_at = Some(now);
                pending_step.updated_at = now;
                let pending_step = state.update_workflow_step_run(pending_step).await?;
                record_workflow_step_run_updated(state, &run, &pending_step, &previous_status)
                    .await?;
                record_workflow_step_worker_completed(
                    state,
                    &run,
                    &pending_step,
                    &worker_id,
                    &completed_job,
                )
                .await?;
                state
                    .append_event(
                        "worker",
                        Some(pending_step.id),
                        session_id,
                        "workflow.delegated_runtime.poll_pending",
                        json!({
                            "workflow_run_id": run.id,
                            "workflow_step_run_id": pending_step.id,
                            "worker_id": worker_id,
                            "runtime_adapter": adapter,
                            "status": delegated_status.clone(),
                            "output": pending_step.output_payload
                        }),
                    )
                    .await?;
                return Ok(Json(RunWorkflowStepRunResponse {
                    step: pending_step,
                    task_grant: claim.task_grant,
                    context_packet: claim.context_packet,
                    session,
                    session_loop_job: completed_job,
                }));
            }
            if !delegated_runtime_status_is_terminal_success(&delegated_status) {
                return complete_delegated_runtime_requires_action(
                    state,
                    &run,
                    &claim.step,
                    claim.task_grant,
                    claim.context_packet,
                    running_job,
                    &worker_id,
                    session_id,
                    adapter,
                    format!(
                        "delegated runtime returned non-success terminal status {delegated_status}"
                    ),
                    Some(output_payload),
                )
                .await;
            }
            let artifact = create_delegated_runtime_artifact(
                state,
                session_id,
                "delegated-runtime-result.json",
                output_payload.clone(),
            )
            .await?;
            let completed_job = state
                .complete_session_loop_job(running_job.id, &worker_id)
                .await?;
            let session = set_managed_session_status(
                state,
                session_id,
                SessionStatus::Terminated,
                "delegated runtime completed",
            )
            .await?;
            let previous_status = claim.step.status.clone();
            let now = Utc::now();
            let mut completed_step = claim.step.clone();
            completed_step.status = "completed".to_string();
            completed_step.artifact_ids = vec![artifact.id];
            completed_step.output_payload = json!({
                "delegated_runtime": output_payload,
                "artifact_ids": completed_step.artifact_ids,
                "worker_id": worker_id,
                "session_loop_job_id": completed_job.id,
                "context_packet_id": completed_step.context_packet_id
            });
            completed_step.completed_at = Some(now);
            completed_step.updated_at = now;
            let completed_step = state.update_workflow_step_run(completed_step).await?;
            record_workflow_step_run_updated(state, &run, &completed_step, &previous_status)
                .await?;
            record_workflow_step_worker_completed(
                state,
                &run,
                &completed_step,
                &worker_id,
                &completed_job,
            )
            .await?;
            state
                .append_event(
                    "worker",
                    Some(completed_step.id),
                    session_id,
                    "workflow.delegated_runtime.completed",
                    json!({
                        "workflow_run_id": run.id,
                        "workflow_step_run_id": completed_step.id,
                        "worker_id": worker_id,
                        "runtime_adapter": adapter,
                        "artifact_id": artifact.id,
                        "output": completed_step.output_payload
                    }),
                )
                .await?;
            advance_workflow_graph_after_step_update(state, &run, &completed_step).await?;
            Ok(Json(RunWorkflowStepRunResponse {
                step: completed_step,
                task_grant: claim.task_grant,
                context_packet: claim.context_packet,
                session,
                session_loop_job: completed_job,
            }))
        }
        Err(error) => {
            complete_delegated_runtime_requires_action(
                state,
                &run,
                &claim.step,
                claim.task_grant,
                claim.context_packet,
                running_job,
                &worker_id,
                session_id,
                adapter,
                error.message,
                None,
            )
            .await
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn complete_delegated_runtime_requires_action(
    state: &AppState,
    run: &WorkflowRun,
    step: &WorkflowStepRun,
    task_grant: TaskGrant,
    context_packet: ContextPacket,
    running_job: SessionLoopJob,
    worker_id: &str,
    session_id: Uuid,
    adapter: &str,
    reason: String,
    output_payload: Option<Value>,
) -> Result<Json<RunWorkflowStepRunResponse>, AppError> {
    let completed_job = state
        .complete_session_loop_job(running_job.id, worker_id)
        .await?;
    let session = set_managed_session_status(
        state,
        session_id,
        SessionStatus::RequiresAction,
        "delegated runtime requires action",
    )
    .await?;
    let previous_status = step.status.clone();
    let mut blocked_step = step.clone();
    blocked_step.status = "requires_action".to_string();
    blocked_step.output_payload = json!({
        "delegated_runtime": {
            "status": "requires_action",
            "reason": reason,
            "runtime_adapter": adapter,
            "runtime_mode": run.runtime_mode,
            "runtime_envelope": run.runtime_envelope,
            "output": output_payload
        },
        "worker_id": worker_id,
        "session_loop_job_id": completed_job.id,
        "context_packet_id": blocked_step.context_packet_id
    });
    blocked_step.updated_at = Utc::now();
    let blocked_step = state.update_workflow_step_run(blocked_step).await?;
    record_workflow_step_run_updated(state, run, &blocked_step, &previous_status).await?;
    record_workflow_step_worker_completed(state, run, &blocked_step, worker_id, &completed_job)
        .await?;
    state
        .append_event(
            "worker",
            Some(blocked_step.id),
            session_id,
            "workflow.delegated_runtime.requires_action",
            json!({
                "workflow_run_id": run.id,
                "workflow_step_run_id": blocked_step.id,
                "worker_id": worker_id,
                "runtime_adapter": adapter,
                "reason": reason
            }),
        )
        .await?;
    Ok(Json(RunWorkflowStepRunResponse {
        step: blocked_step,
        task_grant,
        context_packet,
        session,
        session_loop_job: completed_job,
    }))
}

fn delegated_runtime_output_status(output_payload: &Value) -> String {
    output_payload
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown")
        .to_string()
}

fn delegated_runtime_status_is_nonterminal(status: &str) -> bool {
    matches!(
        status,
        "created" | "queued" | "pending" | "submitted" | "running" | "in_progress"
    )
}

fn delegated_runtime_status_is_terminal_success(status: &str) -> bool {
    matches!(status, "completed" | "complete" | "succeeded" | "success")
}

async fn run_codex_app_server_delegated_runtime(
    state: &AppState,
    run: &WorkflowRun,
    step: &WorkflowStepRun,
    worker_id: &str,
) -> Result<Value, AppError> {
    let config = codex_app_server_config(state)?;
    let metadata = json!({
        "source": "mandoforge_delegated_runtime",
        "workflow_run_id": run.id,
        "workflow_step_run_id": step.id,
        "runtime_mode": run.runtime_mode,
        "worker_id": worker_id,
        "runtime_envelope": run.runtime_envelope
    });
    let thread_request = CodexThreadRequest {
        metadata: metadata.clone(),
    };
    let thread = state
        .codex_app_server_client
        .create_thread(config, thread_request.clone())
        .await?;
    state
        .record_codex_app_server_run(
            "delegated_runtime.thread.create",
            Some(thread.thread_id.clone()),
            None,
            None,
            serde_json::to_value(&thread_request)?,
            serde_json::to_value(&thread)?,
        )
        .await?;

    let turn_request = CodexTurnRequest {
        message: delegated_runtime_turn_message(run, step),
        metadata,
    };
    let turn = state
        .codex_app_server_client
        .create_turn(config, &thread.thread_id, turn_request.clone())
        .await?;
    state
        .record_codex_app_server_run(
            "delegated_runtime.turn.create",
            Some(thread.thread_id.clone()),
            Some(turn.turn_id.clone()),
            None,
            serde_json::to_value(&turn_request)?,
            serde_json::to_value(&turn)?,
        )
        .await?;
    let polled = state
        .codex_app_server_client
        .get_turn_status(config, &turn.turn_id)
        .await?;
    state
        .record_codex_app_server_run(
            "delegated_runtime.turn.poll",
            Some(thread.thread_id.clone()),
            Some(polled.turn_id.clone()),
            None,
            json!({"turn_id": turn.turn_id}),
            serde_json::to_value(&polled)?,
        )
        .await?;
    let status = polled.status.as_deref().unwrap_or("unknown");
    if matches!(status, "failed" | "canceled" | "error") {
        return Err(AppError::bad_request(format!(
            "Codex App Server delegated runtime returned {status}"
        )));
    }
    Ok(json!({
        "status": status,
        "runtime_adapter": "codex_app_server",
        "runtime_mode": run.runtime_mode,
        "thread": thread,
        "turn": turn,
        "poll": polled
    }))
}

async fn run_agent_cli_delegated_runtime(
    state: &AppState,
    run: &WorkflowRun,
    step: &WorkflowStepRun,
    session_id: Uuid,
    adapter: &str,
) -> Result<Value, AppError> {
    let result = run_agent_cli(
        state,
        session_id,
        AgentCliRequest {
            profile: adapter.to_string(),
            task: delegated_runtime_turn_message(run, step),
            args: Vec::new(),
            timeout_seconds: run
                .runtime_envelope
                .get("runtime_capability_contract")
                .and_then(|contract| contract.get("timeout_seconds"))
                .and_then(Value::as_u64),
        },
    )
    .await?;
    Ok(json!({
        "status": "completed",
        "runtime_adapter": adapter,
        "runtime_mode": run.runtime_mode,
        "agent_cli": result
    }))
}

fn delegated_runtime_turn_message(run: &WorkflowRun, step: &WorkflowStepRun) -> String {
    let objective = step
        .input_payload
        .get("graph_step")
        .and_then(|graph_step| graph_step.get("input"))
        .and_then(|input| input.get("objective"))
        .and_then(Value::as_str)
        .or_else(|| run.input_payload.get("objective").and_then(Value::as_str))
        .unwrap_or("Execute the delegated runtime workflow.");
    format!(
        "Run delegated workflow for MandoForge workflow run {}.\nObjective: {}\nRuntime envelope: {}",
        run.id,
        objective,
        workflow_graph_console_summary(&run.runtime_envelope)
    )
}

async fn create_delegated_runtime_artifact(
    state: &AppState,
    session_id: Uuid,
    name: &str,
    content: Value,
) -> Result<Artifact, AppError> {
    let artifact = Artifact {
        id: Uuid::new_v4(),
        session_id,
        artifact_type: "json".to_string(),
        name: name.to_string(),
        path: Some(format!("delegated-runtime/{session_id}/{name}")),
        content,
        created_at: Utc::now(),
    };
    let artifact = state.insert_artifact(artifact).await?;
    state
        .append_event(
            "system",
            Some(artifact.id),
            session_id,
            "artifact.created",
            json!({
                "artifact_id": artifact.id,
                "artifact_type": artifact.artifact_type,
                "name": artifact.name,
                "path": artifact.path,
                "source": "delegated_runtime"
            }),
        )
        .await?;
    state
        .append_audit_log(new_audit_log(
            Some(session_id),
            "system",
            None,
            "artifact.created",
            "artifact",
            Some(artifact.id),
            json!({
                "name": artifact.name,
                "artifact_type": artifact.artifact_type,
                "path": artifact.path,
                "source": "delegated_runtime"
            }),
        ))
        .await?;
    Ok(artifact)
}

fn workflow_step_is_adapter_owned_compensation(step: &WorkflowStepRun) -> bool {
    step.input_payload
        .get("graph_step")
        .is_some_and(workflow_graph_step_is_adapter_owned_compensation)
}

fn workflow_compensation_adapter_kind(step: &WorkflowStepRun) -> String {
    step.input_payload
        .get("graph_step")
        .and_then(|graph_step| graph_step.get("adapter"))
        .and_then(|adapter| {
            adapter
                .get("kind")
                .or_else(|| adapter.get("type"))
                .and_then(Value::as_str)
                .or_else(|| adapter.as_str())
        })
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(step.step_type.as_str())
        .to_string()
}

fn workflow_compensation_adapter_blockers(
    step: &WorkflowStepRun,
    now: DateTime<Utc>,
) -> Vec<String> {
    let mut blockers = Vec::new();
    if workflow_step_status_terminal(&step.status) {
        blockers.push("terminal_status".to_string());
    }
    if step.status == "scheduled" {
        match step.scheduled_at {
            Some(scheduled_at) if scheduled_at > now => {
                blockers.push("scheduled_for_future".to_string())
            }
            Some(_) => blockers.push("scheduled_until_scheduler_activation".to_string()),
            None => blockers.push("scheduled_without_due_time".to_string()),
        }
    } else if step.status != "queued" {
        if step.status == "running" {
            if !step
                .lease_expires_at
                .is_some_and(|lease_expires_at| lease_expires_at <= now)
            {
                blockers.push("already_claimed".to_string());
            }
        } else {
            blockers.push(format!("status_{}", step.status));
        }
    }
    if step.task_grant_id.is_none() {
        blockers.push("missing_task_grant".to_string());
    }
    blockers
}

async fn run_workflow_compensation_adapter_step(
    state: &AppState,
    headers: &HeaderMap,
    current: WorkflowStepRun,
    run: WorkflowRun,
    input: RunWorkflowStepRun,
) -> Result<Json<RunWorkflowStepRunResponse>, AppError> {
    authorize_request(
        state,
        headers,
        Permission::SessionsRun,
        "session",
        Some(run.primary_session_id),
    )
    .await?;
    let session_id = current.session_id.unwrap_or(run.primary_session_id);
    let session = state.get_session(session_id).await?;
    let now = Utc::now();
    let blockers = workflow_compensation_adapter_blockers(&current, now);
    if !blockers.is_empty() {
        return Err(AppError::bad_request(format!(
            "workflow compensation adapter step is not runnable: {}",
            blockers.join(", ")
        )));
    }
    let task_grant_id = current.task_grant_id.ok_or_else(|| {
        AppError::bad_request("workflow compensation adapter requires task grant")
    })?;
    let grant = state.get_task_grant(task_grant_id).await?;
    if grant.workflow_run_id != run.id {
        return Err(AppError::bad_request(
            "workflow compensation adapter task grant must belong to workflow run",
        ));
    }
    if grant.status != "active" {
        return Err(AppError::forbidden(
            "workflow compensation adapter task grant is not active",
        ));
    }
    if grant.expires_at.is_some_and(|expires_at| expires_at <= now) {
        return Err(AppError::forbidden(
            "workflow compensation adapter task grant is expired",
        ));
    }

    let worker_id = input
        .worker_id
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| {
            headers
                .get("x-mandoforge-worker-id")
                .and_then(|value| value.to_str().ok())
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string)
                .unwrap_or_else(|| format!("rollback-adapter:{}", current.id))
        });
    let lease_seconds = input.lease_seconds.unwrap_or(300);
    if !(1..=86_400).contains(&lease_seconds) {
        return Err(AppError::bad_request(
            "workflow step claim lease_seconds must be between 1 and 86400",
        ));
    }
    let context_packet = generate_and_persist_context_packet(state, session_id).await?;
    let task_grant = state
        .update_task_grant_context_packet(grant.id, context_packet.id)
        .await?;
    record_task_grant_checked(
        state,
        &task_grant,
        session_id,
        "workflow.compensation_adapter",
    )
    .await?;

    let mut running_step = current.clone();
    let previous_status = running_step.status.clone();
    running_step.status = "running".to_string();
    running_step.claimed_by_worker = Some(worker_id.clone());
    running_step.lease_expires_at = Some(now + ChronoDuration::seconds(lease_seconds));
    running_step.context_packet_id = Some(context_packet.id);
    running_step.started_at = running_step.started_at.or(Some(now));
    running_step.updated_at = now;
    let running_step = state.update_workflow_step_run(running_step).await?;
    record_workflow_step_run_updated(state, &run, &running_step, &previous_status).await?;
    record_workflow_step_worker_started(state, &run, &running_step, &worker_id, context_packet.id)
        .await?;
    record_workflow_transition(
        state,
        &run,
        Some(&running_step),
        Some(&running_step),
        "compensation",
        "running",
        json!({
            "source": "workflow_compensation_adapter",
            "adapter_kind": workflow_compensation_adapter_kind(&running_step),
            "failure_trigger": running_step.input_payload.get("failure_trigger").cloned().unwrap_or(Value::Null),
            "graph_step": running_step.input_payload.get("graph_step").cloned().unwrap_or(Value::Null)
        }),
        json!({
            "workflow_step_run_id": running_step.id,
            "worker_id": worker_id
        }),
    )
    .await?;

    let queued =
        enqueue_session_loop(state, session_id, None, "workflow.compensation_adapter").await?;
    let loop_running = state.start_session_loop_job(queued.id, &worker_id).await?;
    state
        .append_event(
            "worker",
            Some(loop_running.id),
            loop_running.session_id,
            "session.loop.started",
            json!({
                "session_loop_job_id": loop_running.id,
                "environment_id": loop_running.environment_id,
                "worker_id": worker_id,
                "attempt_count": loop_running.attempt_count,
                "workflow_step_run_id": running_step.id,
                "adapter_owned": true
            }),
        )
        .await?;
    let completed_job = state
        .complete_session_loop_job(loop_running.id, &worker_id)
        .await?;
    state
        .append_event(
            "worker",
            Some(completed_job.id),
            completed_job.session_id,
            "session.loop.completed",
            json!({
                "session_loop_job_id": completed_job.id,
                "status": completed_job.status,
                "session_status": session.status,
                "worker_id": worker_id,
                "workflow_step_run_id": running_step.id,
                "adapter_owned": true
            }),
        )
        .await?;

    let mut completed_step = running_step.clone();
    let previous_status = completed_step.status.clone();
    let completed_at = Utc::now();
    completed_step.status = "completed".to_string();
    completed_step.output_payload = json!({
        "rollback_adapter": {
            "status": "completed",
            "adapter_kind": workflow_compensation_adapter_kind(&running_step),
            "worker_id": worker_id,
            "session_id": session_id,
            "context_packet_id": context_packet.id,
            "session_loop_job_id": completed_job.id,
            "failure_trigger": running_step.input_payload.get("failure_trigger").cloned().unwrap_or(Value::Null),
            "graph_step": workflow_graph_console_summary(
                running_step
                    .input_payload
                    .get("graph_step")
                    .unwrap_or(&Value::Null)
            )
        }
    });
    completed_step.completed_at = Some(completed_at);
    completed_step.lease_expires_at = None;
    completed_step.updated_at = completed_at;
    let completed_step = state.update_workflow_step_run(completed_step).await?;
    record_workflow_step_run_updated(state, &run, &completed_step, &previous_status).await?;
    record_workflow_step_worker_completed(state, &run, &completed_step, &worker_id, &completed_job)
        .await?;
    record_workflow_transition(
        state,
        &run,
        Some(&completed_step),
        Some(&completed_step),
        "compensation",
        "completed",
        json!({
            "source": "workflow_compensation_adapter",
            "adapter_kind": workflow_compensation_adapter_kind(&completed_step),
            "failure_trigger": completed_step.output_payload["rollback_adapter"]["failure_trigger"].clone()
        }),
        json!({
            "workflow_step_run_id": completed_step.id,
            "worker_id": worker_id,
            "session_loop_job_id": completed_job.id,
            "adapter_owned": true
        }),
    )
    .await?;
    advance_workflow_graph_after_step_update(state, &run, &completed_step).await?;

    Ok(Json(RunWorkflowStepRunResponse {
        step: completed_step,
        task_grant,
        context_packet,
        session,
        session_loop_job: completed_job,
    }))
}

