pub(crate) async fn execute_usage_finance_operations(
    state: &AppState,
    subject: Option<&str>,
) -> Result<UsageFinanceOperationsRun, AppError> {
    execute_usage_finance_operations_with_lookup(state, subject, |key| std::env::var(key).ok())
        .await
}

async fn execute_usage_finance_operations_with_lookup<F>(
    state: &AppState,
    subject: Option<&str>,
    lookup: F,
) -> Result<UsageFinanceOperationsRun, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let ran_at = Utc::now();
    let before = build_usage_finance_operations_summary(state).await?;
    let mut actions = Vec::new();
    let mut rollup_created = None;
    let mut cost_alert_delivery = None;
    let mut finance_export_delivery = None;
    let close_controller_configured = usage_finance_close_controller_configured(&lookup);
    let reconciliation_controller_configured =
        usage_finance_reconciliation_controller_configured(&lookup);

    if before.rollup_status != "fresh" {
        let period_end = ran_at;
        let period_start = period_end - chrono::Duration::hours(24);
        let summary = serde_json::to_value(build_usage_summary(state).await?)?;
        let rollup = state
            .create_usage_rollup(period_start, period_end, summary)
            .await?;
        actions.push("usage_rollup_created".to_string());
        rollup_created = Some(rollup);
    }

    if before.open_alert_count > 0
        && before.active_alert_route_count > 0
        && before.alert_delivery_status != "delivered"
    {
        let delivery = execute_cost_alert_delivery(state, ran_at).await?;
        actions.push("cost_alert_delivery_processed".to_string());
        cost_alert_delivery = Some(delivery);
    }

    if before.export_status != "target_missing"
        && before
            .last_finance_export
            .as_ref()
            .is_none_or(|audit| (ran_at - audit.created_at).num_hours() >= 20)
    {
        let delivery = execute_usage_finance_export_delivery(state, false, "user", subject).await?;
        actions.push("usage_finance_export_processed".to_string());
        finance_export_delivery = Some(delivery);
    }

    let after = build_usage_finance_operations_summary(state).await?;
    let mut close_controller_execution = json!({
        "attempted": false,
        "status": "skipped",
        "reason": if close_controller_configured {
            "production_close_gate_not_ready"
        } else {
            "close_controller_not_configured"
        }
    });
    if close_controller_configured
        && finance_close_controller_prerequisites_ready(&after.production_close)
    {
        match execute_usage_finance_close_controller(
            &lookup,
            subject,
            ran_at,
            &before,
            &after,
            rollup_created.is_some(),
            cost_alert_delivery.as_ref(),
            finance_export_delivery.as_ref(),
        )
        .await
        {
            Ok(execution) => {
                let execution_status = execution
                    .get("status")
                    .and_then(Value::as_str)
                    .unwrap_or("failed")
                    .to_string();
                close_controller_execution = execution;
                actions.push("usage_finance_close_controller_executed".to_string());
                if execution_status != "closed" {
                    actions.push("usage_finance_close_controller_attention".to_string());
                }
            }
            Err(error) => {
                close_controller_execution = json!({
                    "attempted": true,
                    "status": "failed",
                    "error": error.message
                });
                actions.push("usage_finance_close_controller_failed".to_string());
            }
        }
    }
    let reconciliation_controller_execution = json!({
        "attempted": false,
        "status": "skipped",
        "reason": if reconciliation_controller_configured {
            "use_reconcile_endpoint_for_accounting_system_validation"
        } else {
            "reconciliation_controller_not_configured"
        }
    });
    let run = UsageFinanceOperationsRun {
        status: if actions.is_empty() {
            "no_action".to_string()
        } else if close_controller_execution
            .get("status")
            .and_then(Value::as_str)
            == Some("failed")
        {
            "attention".to_string()
        } else {
            "completed".to_string()
        },
        ran_at,
        actions,
        before,
        after,
        rollup_created,
        cost_alert_delivery,
        finance_export_delivery,
        close_controller_configured,
        close_controller_execution,
        reconciliation_controller_configured,
        reconciliation_controller_execution,
    };
    state
        .append_audit_log(new_audit_log(
            None,
            "user",
            None,
            "usage.finance_operations_run",
            "usage_finance_operations",
            None,
            json!({
                "subject": subject,
                "status": run.status,
                "actions": run.actions,
                "rollup_created": run.rollup_created.is_some(),
                "cost_alert_delivery_status": run.cost_alert_delivery.as_ref().map(|delivery| delivery.status.clone()),
                "finance_export_delivery_status": run.finance_export_delivery.as_ref().map(|delivery| delivery.status.clone()),
                "close_controller_configured": run.close_controller_configured,
                "close_controller_execution": run.close_controller_execution,
                "reconciliation_controller_configured": run.reconciliation_controller_configured,
                "reconciliation_controller_execution": run.reconciliation_controller_execution,
                "before_status": run.before.status,
                "after_status": run.after.status,
                "ran_at": run.ran_at,
            }),
        ))
        .await?;
    Ok(run)
}

fn finance_close_controller_prerequisites_ready(
    production_close: &UsageFinanceProductionCloseReadiness,
) -> bool {
    if !production_close.production_blocked {
        return true;
    }
    let allowed_bootstrap_reasons = [
        "finance close controller has no recent closed evidence",
        "finance close controller evidence is stale",
        "finance reconciliation controller has no recent reconciled evidence",
        "finance reconciliation controller evidence is stale",
    ];
    !production_close.blocking_reasons.is_empty()
        && production_close.blocking_reasons.iter().all(|reason| {
            allowed_bootstrap_reasons
                .iter()
                .any(|allowed| reason == allowed)
        })
}

fn usage_finance_close_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_FINANCE_CLOSE_CONTROLLER_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

fn usage_finance_close_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_FINANCE_CLOSE_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        })
        .unwrap_or(false)
}

fn usage_finance_reconciliation_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_FINANCE_RECONCILIATION_CONTROLLER_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

fn usage_finance_reconciliation_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_FINANCE_RECONCILIATION_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        })
        .unwrap_or(false)
}

async fn execute_usage_finance_close_controller<F>(
    lookup: &F,
    subject: Option<&str>,
    ran_at: DateTime<Utc>,
    before: &UsageFinanceOperationsSummary,
    after: &UsageFinanceOperationsSummary,
    rollup_created: bool,
    cost_alert_delivery: Option<&CostAlertDelivery>,
    finance_export_delivery: Option<&UsageFinanceExportDelivery>,
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_FINANCE_CLOSE_CONTROLLER_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request("MANDOFORGE_FINANCE_CLOSE_CONTROLLER_URL is required")
        })?;
    let timeout_seconds = lookup("MANDOFORGE_FINANCE_CLOSE_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_FINANCE_CLOSE_CONTROLLER_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let payload = json!({
        "type": "mandoforge.finance_close",
        "subject": subject,
        "ran_at": ran_at,
        "before": {
            "status": before.status,
            "readiness_score": before.readiness_score,
            "production_close": before.production_close,
        },
        "after": {
            "status": after.status,
            "readiness_score": after.readiness_score,
            "production_close": after.production_close,
        },
        "rollup_created": rollup_created,
        "cost_alert_delivery_status": cost_alert_delivery.map(|delivery| delivery.status.clone()),
        "finance_export_delivery_status": finance_export_delivery.map(|delivery| delivery.status.clone()),
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "finance close controller failed with status {http_status}"
        )));
    }
    let controller_status = body
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("closed");
    let closed = matches!(controller_status, "closed" | "success" | "ok" | "validated");
    Ok(json!({
        "attempted": true,
        "status": if closed { "closed" } else { "failed" },
        "http_status": http_status.as_u16(),
        "provider_status": controller_status,
        "close_id": body.get("close_id").and_then(Value::as_str),
        "message": body.get("message").and_then(Value::as_str),
        "steps": body.get("steps").cloned().unwrap_or_else(|| json!([])),
    }))
}

pub(crate) async fn execute_usage_finance_reconciliation_controller<F>(
    lookup: &F,
    subject: Option<&str>,
    ran_at: DateTime<Utc>,
    summary: &UsageFinanceOperationsSummary,
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_FINANCE_RECONCILIATION_CONTROLLER_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request("MANDOFORGE_FINANCE_RECONCILIATION_CONTROLLER_URL is required")
        })?;
    let timeout_seconds = lookup("MANDOFORGE_FINANCE_RECONCILIATION_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_FINANCE_RECONCILIATION_CONTROLLER_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let payload = json!({
        "type": "mandoforge.finance_reconciliation",
        "subject": subject,
        "ran_at": ran_at,
        "summary": {
            "status": summary.status,
            "readiness_score": summary.readiness_score,
            "open_alert_count": summary.open_alert_count,
            "unacknowledged_alert_count": summary.unacknowledged_alert_count,
            "rollup_status": summary.rollup_status,
            "export_status": summary.export_status,
            "alert_delivery_status": summary.alert_delivery_status,
            "last_finance_export": summary.last_finance_export,
            "last_alert_delivery": summary.last_alert_delivery,
            "last_alert_acknowledgement": summary.last_alert_acknowledgement,
            "production_close": summary.production_close,
        },
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "finance reconciliation controller failed with status {http_status}"
        )));
    }
    let controller_status = body
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("reconciled");
    let reconciled = matches!(
        controller_status,
        "reconciled" | "success" | "ok" | "validated"
    );
    Ok(json!({
        "attempted": true,
        "status": if reconciled { "reconciled" } else { "failed" },
        "http_status": http_status.as_u16(),
        "provider_status": controller_status,
        "reconciliation_id": body.get("reconciliation_id").and_then(Value::as_str),
        "message": body.get("message").and_then(Value::as_str),
        "checks": body.get("checks").cloned().unwrap_or_else(|| json!([])),
    }))
}

fn build_usage_finance_dashboard_summary_from_parts(
    trend: UsageTrendSummary,
    rollups: &[UsageRollup],
    alert_routes: &[CostAlertRoute],
    alerts: &[CostAlert],
    finance_export_target_configured: bool,
    finance_export_schedule_enabled: bool,
    generated_at: DateTime<Utc>,
) -> UsageFinanceDashboardSummary {
    let latest_rollup_at = rollups
        .iter()
        .map(|rollup| rollup.period_end)
        .max()
        .or_else(|| rollups.iter().map(|rollup| rollup.created_at).max());
    let latest_rollup_age_hours =
        latest_rollup_at.map(|latest| (generated_at - latest).num_hours().max(0));
    let active_alert_route_count = alert_routes
        .iter()
        .filter(|route| route.status == "active")
        .count();
    let critical_alert_count = alerts
        .iter()
        .filter(|alert| alert.severity == "critical")
        .count();
    let warning_alert_count = alerts
        .iter()
        .filter(|alert| alert.severity == "warning")
        .count();
    let forecast_7d_cost_cents = trend
        .forecast
        .horizons
        .iter()
        .find(|horizon| horizon.days == 7)
        .map(|horizon| horizon.projected_cost_cents);
    let forecast_30d_cost_cents = trend
        .forecast
        .horizons
        .iter()
        .find(|horizon| horizon.days == 30)
        .map(|horizon| horizon.projected_cost_cents);
    let mut attention_items = Vec::new();

    for alert in alerts {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "budget_alert".to_string(),
            severity: alert.severity.clone(),
            message: alert.message.clone(),
            provider_name: Some(alert.provider_name.clone()),
        });
    }
    if alerts.is_empty() && trend.budget_pressure.pressure_count > 0 {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "budget_pressure_unrouted".to_string(),
            severity: trend.budget_pressure.highest_status.clone(),
            message: "budget pressure exists but no matching cost alert was generated".to_string(),
            provider_name: None,
        });
    }
    if !alerts.is_empty() && active_alert_route_count == 0 {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "missing_alert_route".to_string(),
            severity: "critical".to_string(),
            message: "cost alerts exist but no active alert route is configured".to_string(),
            provider_name: None,
        });
    }
    if rollups.is_empty() {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "missing_usage_rollup".to_string(),
            severity: "warning".to_string(),
            message: "no persisted usage rollup exists for finance comparison".to_string(),
            provider_name: None,
        });
    } else if latest_rollup_age_hours.is_some_and(|hours| hours >= 30) {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "stale_usage_rollup".to_string(),
            severity: "warning".to_string(),
            message: "latest usage rollup is older than 30 hours".to_string(),
            provider_name: None,
        });
    }
    if !finance_export_target_configured {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "finance_export_target_missing".to_string(),
            severity: "warning".to_string(),
            message: "finance export webhook target is not configured".to_string(),
            provider_name: None,
        });
    }
    if trend
        .cost_delta_percent
        .is_some_and(|cost_delta_percent| cost_delta_percent >= 25.0)
    {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "cost_growth".to_string(),
            severity: "warning".to_string(),
            message: "provider cost increased by at least 25 percent versus comparison period"
                .to_string(),
            provider_name: trend
                .top_provider_by_cost
                .as_ref()
                .map(|provider| provider.provider_name.clone()),
        });
    }

    UsageFinanceDashboardSummary {
        generated_at,
        current_cost_cents: trend.current_cost_cents,
        current_total_tokens: trend.current_total_tokens,
        current_tool_calls: trend.current_tool_calls,
        comparison_basis: trend.comparison_basis,
        budget_pressure_status: trend.budget_pressure.highest_status,
        budget_pressure_count: trend.budget_pressure.pressure_count,
        critical_budget_count: trend.budget_pressure.critical_count,
        warning_budget_count: trend.budget_pressure.warning_count,
        alert_count: alerts.len(),
        critical_alert_count,
        warning_alert_count,
        alert_route_count: alert_routes.len(),
        active_alert_route_count,
        rollup_count: rollups.len(),
        latest_rollup_at,
        latest_rollup_age_hours,
        finance_export_target_configured,
        finance_export_schedule_enabled,
        forecast_7d_cost_cents,
        forecast_30d_cost_cents,
        top_provider_by_cost: trend.top_provider_by_cost,
        recommendations: trend.recommendations,
        attention_items,
    }
}

fn build_usage_finance_operations_summary_from_parts(
    dashboard: UsageFinanceDashboardSummary,
    alerts: &[CostAlert],
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
) -> UsageFinanceOperationsSummary {
    let acknowledgement_cutoff = generated_at - chrono::Duration::hours(24);
    let acknowledged_alert_count = alerts
        .iter()
        .filter(|alert| {
            audit_logs.iter().any(|log| {
                log.action == "usage.alert_acknowledged"
                    && log.created_at >= acknowledgement_cutoff
                    && log.details.get("provider_name").and_then(Value::as_str)
                        == Some(alert.provider_name.as_str())
                    && log.details.get("severity").and_then(Value::as_str)
                        == Some(alert.severity.as_str())
            })
        })
        .count();
    let unacknowledged_alert_count = alerts.len().saturating_sub(acknowledged_alert_count);
    let last_finance_export =
        latest_usage_finance_audit(audit_logs, "usage.finance_export_delivered");
    let last_alert_delivery = latest_usage_finance_audit(audit_logs, "usage.cost_alerts_delivered");
    let last_alert_acknowledgement =
        latest_usage_finance_audit(audit_logs, "usage.alert_acknowledged");
    let last_accounting_reconciliation =
        latest_usage_finance_audit(audit_logs, "usage.finance_reconciliation_run");
    let mut attention_items = dashboard.attention_items.clone();
    let mut runbook_actions = dashboard.recommendations.clone();

    if unacknowledged_alert_count > 0 {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "cost_alert_acknowledgement_missing".to_string(),
            severity: "warning".to_string(),
            message: format!(
                "{unacknowledged_alert_count} current budget alert(s) have no recent acknowledgement"
            ),
            provider_name: None,
        });
        runbook_actions.push("acknowledge_or_escalate_cost_alerts".to_string());
    }
    if dashboard.finance_export_schedule_enabled && !dashboard.finance_export_target_configured {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "scheduled_finance_export_blocked".to_string(),
            severity: "critical".to_string(),
            message: "scheduled finance export is enabled but no delivery target is configured"
                .to_string(),
            provider_name: None,
        });
        runbook_actions.push("configure_finance_export_webhook".to_string());
    }
    if dashboard.finance_export_schedule_enabled
        && last_finance_export
            .as_ref()
            .is_none_or(|audit| (generated_at - audit.created_at).num_hours() >= 30)
    {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "finance_export_not_recent".to_string(),
            severity: "warning".to_string(),
            message: "scheduled finance export has no delivery audit in the last 30 hours"
                .to_string(),
            provider_name: None,
        });
        runbook_actions.push("run_or_debug_scheduled_finance_export".to_string());
    }
    if !alerts.is_empty() && last_alert_delivery.is_none() {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "cost_alert_delivery_missing".to_string(),
            severity: "warning".to_string(),
            message: "current budget alerts have not been delivered through an alert route"
                .to_string(),
            provider_name: None,
        });
        runbook_actions.push("deliver_cost_alerts".to_string());
    }
    if dashboard.rollup_count == 0 {
        runbook_actions.push("create_daily_usage_rollup".to_string());
    }

    let rollup_status = if dashboard.rollup_count == 0 {
        "missing"
    } else if dashboard
        .latest_rollup_age_hours
        .is_some_and(|hours| hours >= 30)
    {
        "stale"
    } else {
        "fresh"
    }
    .to_string();
    let export_status = if !dashboard.finance_export_target_configured {
        "target_missing"
    } else if dashboard.finance_export_schedule_enabled {
        "scheduled"
    } else {
        "manual_ready"
    }
    .to_string();
    let alert_delivery_status = if alerts.is_empty() {
        "no_alerts"
    } else if dashboard.active_alert_route_count == 0 {
        "route_missing"
    } else if last_alert_delivery.is_none() {
        "pending_delivery"
    } else {
        "delivered"
    }
    .to_string();
    let production_close = build_usage_finance_production_close_readiness(
        &dashboard,
        alerts,
        audit_logs,
        &rollup_status,
        &alert_delivery_status,
        last_finance_export.as_ref(),
        last_alert_delivery.as_ref(),
        generated_at,
        usage_finance_close_controller_required(&|key| std::env::var(key).ok()),
        usage_finance_close_controller_configured(&|key| std::env::var(key).ok()),
        usage_finance_reconciliation_controller_required(&|key| std::env::var(key).ok()),
        usage_finance_reconciliation_controller_configured(&|key| std::env::var(key).ok()),
    );
    if production_close.production_blocked {
        attention_items.push(UsageFinanceAttentionItem {
            kind: "finance_production_close_blocked".to_string(),
            severity: "critical".to_string(),
            message: production_close.message.clone(),
            provider_name: None,
        });
        runbook_actions.push("resolve_finance_production_close_gate".to_string());
    }
    dedupe_strings(&mut runbook_actions);
    let critical_attention_count = attention_items
        .iter()
        .filter(|item| item.severity == "critical")
        .count();
    let warning_attention_count = attention_items
        .iter()
        .filter(|item| item.severity == "warning")
        .count();
    let status = if critical_attention_count > 0 {
        "critical"
    } else if warning_attention_count > 0 {
        "attention"
    } else {
        "ready"
    }
    .to_string();
    let readiness_score = (100_i64
        - (critical_attention_count as i64 * 25)
        - (warning_attention_count as i64 * 10)
        - (unacknowledged_alert_count as i64 * 5))
        .clamp(0, 100);

    UsageFinanceOperationsSummary {
        generated_at,
        status,
        readiness_score,
        open_alert_count: alerts.len(),
        acknowledged_alert_count,
        unacknowledged_alert_count,
        active_alert_route_count: dashboard.active_alert_route_count,
        rollup_status,
        export_status,
        alert_delivery_status,
        last_finance_export,
        last_alert_delivery,
        last_alert_acknowledgement,
        last_accounting_reconciliation,
        production_close,
        runbook_actions,
        attention_items,
    }
}

fn build_usage_finance_production_close_readiness(
    dashboard: &UsageFinanceDashboardSummary,
    alerts: &[CostAlert],
    audit_logs: &[AuditLog],
    rollup_status: &str,
    alert_delivery_status: &str,
    last_finance_export: Option<&UsageFinanceOperationAudit>,
    last_alert_delivery: Option<&UsageFinanceOperationAudit>,
    generated_at: DateTime<Utc>,
    close_controller_required: bool,
    close_controller_configured: bool,
    reconciliation_controller_required: bool,
    reconciliation_controller_configured: bool,
) -> UsageFinanceProductionCloseReadiness {
    let acknowledgement_cutoff = generated_at - chrono::Duration::hours(24);
    let critical_alerts_acknowledged = alerts
        .iter()
        .filter(|alert| alert.severity == "critical")
        .all(|alert| {
            audit_logs.iter().any(|log| {
                log.action == "usage.alert_acknowledged"
                    && log.created_at >= acknowledgement_cutoff
                    && log.details.get("provider_name").and_then(Value::as_str)
                        == Some(alert.provider_name.as_str())
                    && log.details.get("severity").and_then(Value::as_str)
                        == Some(alert.severity.as_str())
            })
        });
    let export_recent = last_finance_export.as_ref().is_some_and(|audit| {
        audit.status == "delivered" && (generated_at - audit.created_at).num_hours() < 30
    });
    let alert_delivery_ready = alerts.is_empty()
        || (alert_delivery_status == "delivered"
            && last_alert_delivery
                .as_ref()
                .is_some_and(|audit| audit.status != "failed"));
    let failed_delivery_evidence = last_finance_export
        .as_ref()
        .is_some_and(|audit| audit.status == "failed")
        || last_alert_delivery
            .as_ref()
            .is_some_and(|audit| audit.status == "failed");
    let latest_close_controller_log = audit_logs
        .iter()
        .filter(|log| log.action == "usage.finance_operations_run")
        .max_by_key(|log| log.created_at);
    let latest_close_controller_status = latest_close_controller_log
        .and_then(|log| log.details["close_controller_execution"]["status"].as_str())
        .map(str::to_string);
    let latest_close_controller_age_hours = latest_close_controller_log
        .filter(|_| latest_close_controller_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let close_controller_evidence_fresh =
        latest_close_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_close_controller_closed = latest_close_controller_status
        .as_deref()
        .map(|status| status == "closed")
        .unwrap_or(false);
    let latest_reconciliation_log = audit_logs
        .iter()
        .filter(|log| log.action == "usage.finance_reconciliation_run")
        .max_by_key(|log| log.created_at);
    let latest_reconciliation_status = latest_reconciliation_log
        .and_then(|log| {
            log.details["reconciliation_controller_execution"]["status"]
                .as_str()
                .or_else(|| log.details["status"].as_str())
        })
        .map(str::to_string);
    let latest_reconciliation_age_hours = latest_reconciliation_log
        .filter(|_| latest_reconciliation_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let reconciliation_evidence_fresh =
        latest_reconciliation_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_reconciliation_reconciled = latest_reconciliation_status
        .as_deref()
        .map(|status| status == "reconciled")
        .unwrap_or(false);
    let rollup_fresh = rollup_status == "fresh";
    let mut blocking_reasons = Vec::new();

    if !rollup_fresh {
        blocking_reasons.push("usage rollup is missing or stale".to_string());
    }
    if !dashboard.finance_export_target_configured {
        blocking_reasons.push("finance export target is not configured".to_string());
    }
    if !export_recent {
        blocking_reasons.push("finance export has no recent delivered audit evidence".to_string());
    }
    if !alert_delivery_ready {
        blocking_reasons.push("current cost alerts have not been delivered".to_string());
    }
    if !critical_alerts_acknowledged {
        blocking_reasons.push("critical cost alerts have not been acknowledged".to_string());
    }
    if failed_delivery_evidence {
        blocking_reasons.push("failed finance or alert delivery evidence is present".to_string());
    }
    if close_controller_required && !close_controller_configured {
        blocking_reasons
            .push("finance close controller is required but not configured".to_string());
    }
    if close_controller_required && !latest_close_controller_closed {
        blocking_reasons.push("finance close controller has no recent closed evidence".to_string());
    }
    if close_controller_required
        && latest_close_controller_closed
        && !close_controller_evidence_fresh
    {
        blocking_reasons.push("finance close controller evidence is stale".to_string());
    }
    if reconciliation_controller_required && !reconciliation_controller_configured {
        blocking_reasons
            .push("finance reconciliation controller is required but not configured".to_string());
    }
    if reconciliation_controller_required && !latest_reconciliation_reconciled {
        blocking_reasons.push(
            "finance reconciliation controller has no recent reconciled evidence".to_string(),
        );
    }
    if reconciliation_controller_required
        && latest_reconciliation_reconciled
        && !reconciliation_evidence_fresh
    {
        blocking_reasons.push("finance reconciliation controller evidence is stale".to_string());
    }

    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Finance production close is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "Finance production close has fresh rollup, recent export evidence, delivered alerts, acknowledged critical alerts, and required reconciliation evidence".to_string()
    };

    UsageFinanceProductionCloseReadiness {
        status,
        production_blocked,
        rollup_fresh,
        export_target_configured: dashboard.finance_export_target_configured,
        export_recent,
        alert_delivery_ready,
        critical_alerts_acknowledged,
        failed_delivery_evidence,
        close_controller_required,
        close_controller_configured,
        latest_close_controller_status,
        latest_close_controller_age_hours,
        close_controller_evidence_fresh,
        latest_close_controller_closed,
        reconciliation_controller_required,
        reconciliation_controller_configured,
        latest_reconciliation_status,
        latest_reconciliation_age_hours,
        reconciliation_evidence_fresh,
        latest_reconciliation_reconciled,
        blocking_reasons,
        message,
    }
}

fn latest_usage_finance_audit(
    audit_logs: &[AuditLog],
    action: &str,
) -> Option<UsageFinanceOperationAudit> {
    audit_logs
        .iter()
        .filter(|log| log.action == action)
        .max_by_key(|log| log.created_at)
        .map(|log| UsageFinanceOperationAudit {
            action: log.action.clone(),
            status: log
                .details
                .get("status")
                .and_then(Value::as_str)
                .unwrap_or("recorded")
                .to_string(),
            subject: log
                .details
                .get("subject")
                .and_then(Value::as_str)
                .or_else(|| log.details.get("acknowledged_by").and_then(Value::as_str))
                .map(ToString::to_string),
            created_at: log.created_at,
        })
}

pub(crate) fn dedupe_strings(values: &mut Vec<String>) {
    let mut seen = HashSet::new();
    values.retain(|value| seen.insert(value.clone()));
}

pub(crate) async fn execute_usage_finance_export_delivery(
    state: &AppState,
    scheduled: bool,
    actor_type: &str,
    subject: Option<&str>,
) -> Result<UsageFinanceExportDelivery, AppError> {
    let delivered_at = Utc::now();
    let delivery_id = Uuid::new_v4();
    let file_name = "mandoforge-usage-export.csv".to_string();
    if scheduled && !usage_finance_export_schedule_enabled() {
        return Ok(UsageFinanceExportDelivery {
            status: "disabled".to_string(),
            delivered: false,
            channel: "webhook".to_string(),
            scheduled,
            target_configured: usage_finance_export_webhook_url().is_some(),
            delivery_id,
            file_name,
            bytes: 0,
            export_bytes: 0,
            record_count: 0,
            provider_count: 0,
            budget_pressure_count: 0,
            rollup_count: 0,
            delivered_at,
        });
    }

    let summary = build_usage_summary(state).await?;
    let trend = build_usage_trend_summary(state).await?;
    let csv = build_usage_finance_csv(&summary, &trend);
    let webhook_url = usage_finance_export_webhook_url();
    let mut delivery = UsageFinanceExportDelivery {
        status: if webhook_url.is_some() {
            "pending".to_string()
        } else {
            "reserved".to_string()
        },
        delivered: false,
        channel: "webhook".to_string(),
        scheduled,
        target_configured: webhook_url.is_some(),
        delivery_id,
        file_name: file_name.clone(),
        bytes: csv.len(),
        export_bytes: csv.len(),
        record_count: summary.by_provider.len() + trend.rollup_count,
        provider_count: summary.by_provider.len(),
        budget_pressure_count: trend.budget_pressure.pressure_count,
        rollup_count: trend.rollup_count,
        delivered_at,
    };

    if let Some(webhook_url) = webhook_url {
        let response = tokio::time::timeout(
            Duration::from_secs(10),
            reqwest::Client::new()
                .post(&webhook_url)
                .json(&json!({
                    "type": "mandoforge.usage_finance_export",
                    "delivery_id": delivery.delivery_id,
                    "filename": delivery.file_name,
                    "file_name": delivery.file_name,
                    "export_bytes": delivery.export_bytes,
                    "byte_count": delivery.export_bytes,
                    "record_count": delivery.record_count,
                    "csv": csv,
                    "scheduled": scheduled,
                    "provider_count": summary.by_provider.len(),
                    "budget_pressure_count": trend.budget_pressure.pressure_count,
                    "rollup_count": trend.rollup_count,
                    "delivered_at": delivered_at,
                }))
                .send(),
        )
        .await??;
        if !response.status().is_success() {
            return Err(AppError::bad_request(format!(
                "usage finance export webhook returned status {}",
                response.status()
            )));
        }
        delivery.status = "delivered".to_string();
        delivery.delivered = true;
    }

    state
        .append_audit_log(new_audit_log(
            None,
            actor_type,
            None,
            "usage.finance_export_delivered",
            "usage_export",
            None,
            json!({
                "subject": subject,
                "status": delivery.status,
                "delivered": delivery.delivered,
                "scheduled": scheduled,
                "target_configured": delivery.target_configured,
                "delivery_id": delivery.delivery_id,
                "file_name": delivery.file_name,
                "bytes": delivery.bytes,
                "export_bytes": delivery.export_bytes,
                "record_count": delivery.record_count,
                "provider_count": delivery.provider_count,
                "budget_pressure_count": delivery.budget_pressure_count,
                "rollup_count": delivery.rollup_count,
                "delivered_at": delivery.delivered_at,
            }),
        ))
        .await?;
    Ok(delivery)
}

fn usage_finance_export_schedule_enabled() -> bool {
    std::env::var("MANDOFORGE_USAGE_EXPORT_SCHEDULE")
        .ok()
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "enabled"
            )
        })
        .unwrap_or(false)
}

fn usage_finance_export_webhook_url() -> Option<String> {
    std::env::var("MANDOFORGE_USAGE_EXPORT_WEBHOOK_URL")
        .ok()
        .and_then(|value| {
            let trimmed = value.trim();
            (!trimmed.is_empty()).then(|| trimmed.to_string())
        })
}

pub(crate) async fn build_scheduler_orchestration_summary(
    state: &AppState,
) -> Result<SchedulerOrchestrationSummary, AppError> {
    let generated_at = Utc::now();
    let plan = build_scheduler_due_plan(state).await?;
    let audit_logs = state.list_audit_logs(None).await?;
    let deployment_readiness =
        scheduler_deployment_readiness_from_manifests(&audit_logs, generated_at, &|key| {
            std::env::var(key).ok()
        });
    let mut recent_runs: Vec<_> = audit_logs
        .into_iter()
        .filter(|log| log.action == "scheduler.run_due")
        .filter_map(scheduler_run_history_item)
        .collect();
    recent_runs.sort_by(|left, right| right.created_at.cmp(&left.created_at));
    recent_runs.truncate(10);
    let last_run = recent_runs.first();
    let mut attention_items = Vec::new();
    if plan.status == "blocked" {
        attention_items.push(SchedulerAttentionItem {
            severity: "warning".to_string(),
            kind: "blocked_plan".to_string(),
            message: "scheduler has a blocked due-plan item that needs configuration".to_string(),
        });
    }
    if plan.actionable_count > 0 {
        attention_items.push(SchedulerAttentionItem {
            severity: "warning".to_string(),
            kind: "due_actions".to_string(),
            message: format!(
                "{} scheduler item(s) are ready for due-run execution",
                plan.actionable_count
            ),
        });
    }
    if let Some(run) = last_run
        && run.status != "completed"
        && run.status != "noop"
    {
        attention_items.push(SchedulerAttentionItem {
            severity: "critical".to_string(),
            kind: "last_run_unhealthy".to_string(),
            message: format!("last scheduler due-run ended with status {}", run.status),
        });
    }
    if deployment_readiness.production_blocked {
        attention_items.push(SchedulerAttentionItem {
            severity: "critical".to_string(),
            kind: "scheduler_deployment_blocked".to_string(),
            message: deployment_readiness.message.clone(),
        });
    }
    let status = if attention_items
        .iter()
        .any(|item| item.severity == "critical")
    {
        "critical"
    } else if !attention_items.is_empty() {
        "attention"
    } else {
        "ok"
    }
    .to_string();
    Ok(SchedulerOrchestrationSummary {
        generated_at,
        status,
        plan,
        deployment_readiness,
        recent_run_count: recent_runs.len(),
        last_run_at: last_run.map(|run| run.created_at),
        last_run_status: last_run.map(|run| run.status.clone()),
        last_run_action_count: last_run.map(|run| run.action_count).unwrap_or(0),
        recent_runs,
        attention_items,
    })
}

fn validate_scheduler_shared_token(headers: &HeaderMap) -> Result<(), AppError> {
    let Some(expected_token) = scheduler_shared_token_from_env() else {
        return Ok(());
    };
    let provided_token = header_value(headers, "x-mandoforge-scheduler-token")
        .map(str::trim)
        .unwrap_or_default();
    if provided_token != expected_token {
        return Err(AppError::forbidden("scheduler token is invalid"));
    }
    Ok(())
}

fn scheduler_shared_token_from_env() -> Option<String> {
    std::env::var("MANDOFORGE_SCHEDULER_TOKEN")
        .ok()
        .and_then(|value| {
            let trimmed = value.trim();
            (!trimmed.is_empty()).then(|| trimmed.to_string())
        })
}

fn scheduler_deployment_readiness_from_manifests<F>(
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
    lookup: &F,
) -> SchedulerDeploymentReadiness
where
    F: Fn(&str) -> Option<String>,
{
    let scheduler_manifest_path = "deploy/k8s/scheduler.yaml";
    let service_account_manifest_path = "deploy/k8s/scheduler-serviceaccount.yaml";
    let secret_manifest_path = "deploy/k8s/secret.example.yaml";
    let scheduler_manifest =
        read_yaml_manifest_value(scheduler_manifest_path).and_then(|manifest| {
            (manifest.get("kind").and_then(Value::as_str) == Some("CronJob")).then_some(manifest)
        });
    let scheduler_manifest_present = scheduler_manifest.is_some();
    let service_account_name = scheduler_manifest
        .as_ref()
        .and_then(|manifest| {
            manifest.pointer("/spec/jobTemplate/spec/template/spec/serviceAccountName")
        })
        .and_then(Value::as_str)
        .map(ToString::to_string);
    let service_account_manifest_present = service_account_name.as_deref().is_some_and(|name| {
        manifest_has_kind_name(service_account_manifest_path, "ServiceAccount", name)
    });
    let automount_service_account_token_disabled = scheduler_manifest
        .as_ref()
        .and_then(|manifest| {
            manifest.pointer("/spec/jobTemplate/spec/template/spec/automountServiceAccountToken")
        })
        .and_then(Value::as_bool)
        == Some(false);
    let scheduler_container = scheduler_manifest
        .as_ref()
        .and_then(|manifest| manifest.pointer("/spec/jobTemplate/spec/template/spec/containers"))
        .and_then(Value::as_array)
        .and_then(|containers| {
            containers.iter().find(|container| {
                container.get("name").and_then(Value::as_str) == Some("scheduler")
            })
        });
    let subject_from_secret =
        scheduler_container_env_uses_secret(
            scheduler_container,
            "MANDOFORGE_SCHEDULER_SUBJECT",
            "MANDOFORGE_SCHEDULER_SUBJECT",
        ) && secret_manifest_defines_key(secret_manifest_path, "MANDOFORGE_SCHEDULER_SUBJECT");
    let roles_from_secret =
        scheduler_container_env_uses_secret(
            scheduler_container,
            "MANDOFORGE_SCHEDULER_ROLES",
            "MANDOFORGE_SCHEDULER_ROLES",
        ) && secret_manifest_defines_key(secret_manifest_path, "MANDOFORGE_SCHEDULER_ROLES");
    let token_from_secret =
        scheduler_container_env_uses_secret(
            scheduler_container,
            "MANDOFORGE_SCHEDULER_TOKEN",
            "MANDOFORGE_SCHEDULER_TOKEN",
        ) && secret_manifest_defines_key(secret_manifest_path, "MANDOFORGE_SCHEDULER_TOKEN");
    let args_text = scheduler_container
        .and_then(|container| container.get("args"))
        .and_then(Value::as_array)
        .map(|args| {
            args.iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>()
                .join("\n")
        })
        .unwrap_or_default();
    let token_header_present = args_text.contains("x-mandoforge-scheduler-token")
        && args_text.contains("MANDOFORGE_SCHEDULER_TOKEN");
    let hardcoded_admin_headers_absent = !args_text.contains("x-mandoforge-roles: admin")
        && !args_text.contains("x-mandoforge-subject: scheduler");
    let shared_token_runtime_configured = lookup("MANDOFORGE_SCHEDULER_TOKEN")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false);
    let controller_required = scheduler_deployment_controller_required(lookup);
    let controller_configured = scheduler_deployment_controller_configured(lookup);
    let latest_controller_log = audit_logs
        .iter()
        .filter(|log| log.action == "scheduler.deployment_validation_run")
        .max_by_key(|log| log.created_at);
    let latest_controller_status = latest_controller_log
        .and_then(|log| {
            log.details["controller_execution"]["status"]
                .as_str()
                .or_else(|| log.details["status"].as_str())
        })
        .map(str::to_string);
    let latest_controller_age_hours = latest_controller_log
        .filter(|_| latest_controller_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_controller_validated = latest_controller_status.as_deref() == Some("validated");
    let mut blocking_reasons = Vec::new();

    if !scheduler_manifest_present {
        blocking_reasons.push("scheduler CronJob manifest is missing".to_string());
    }
    if !service_account_manifest_present {
        blocking_reasons.push("scheduler ServiceAccount manifest is missing".to_string());
    }
    if !automount_service_account_token_disabled {
        blocking_reasons
            .push("scheduler ServiceAccount token automount is not disabled".to_string());
    }
    if !subject_from_secret {
        blocking_reasons.push("scheduler subject is not sourced from Secret".to_string());
    }
    if !roles_from_secret {
        blocking_reasons.push("scheduler roles are not sourced from Secret".to_string());
    }
    if !token_from_secret {
        blocking_reasons.push("scheduler shared token is not sourced from Secret".to_string());
    }
    if !token_header_present {
        blocking_reasons.push("scheduler token header is not sent by the CronJob".to_string());
    }
    if !hardcoded_admin_headers_absent {
        blocking_reasons
            .push("scheduler CronJob still contains hardcoded demo admin headers".to_string());
    }
    if !shared_token_runtime_configured {
        blocking_reasons
            .push("MANDOFORGE_SCHEDULER_TOKEN is not configured in the API runtime".to_string());
    }
    if controller_required && !controller_configured {
        blocking_reasons
            .push("scheduler deployment controller is required but not configured".to_string());
    }
    if controller_required && controller_configured && !latest_controller_validated {
        blocking_reasons
            .push("scheduler deployment controller has no recent validated evidence".to_string());
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons.push("scheduler deployment controller evidence is stale".to_string());
    }

    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Scheduler deployment is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "Scheduler deployment uses Secret-backed identity and shared-token auth".to_string()
    };

    SchedulerDeploymentReadiness {
        status,
        production_blocked,
        scheduler_manifest_present,
        service_account_manifest_present,
        service_account_name,
        automount_service_account_token_disabled,
        subject_from_secret,
        roles_from_secret,
        token_from_secret,
        token_header_present,
        hardcoded_admin_headers_absent,
        shared_token_runtime_configured,
        controller_required,
        controller_configured,
        latest_controller_status,
        latest_controller_age_hours,
        controller_evidence_fresh,
        latest_controller_validated,
        blocking_reasons,
        message,
    }
}

fn scheduler_deployment_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_SCHEDULER_DEPLOYMENT_CONTROLLER_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

fn scheduler_deployment_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_SCHEDULER_DEPLOYMENT_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        })
        .unwrap_or(false)
}

async fn execute_scheduler_deployment_controller<F>(
    lookup: &F,
    subject: Option<&str>,
    checked_at: DateTime<Utc>,
    readiness: &SchedulerDeploymentReadiness,
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_SCHEDULER_DEPLOYMENT_CONTROLLER_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request("MANDOFORGE_SCHEDULER_DEPLOYMENT_CONTROLLER_URL is required")
        })?;
    let timeout_seconds = lookup("MANDOFORGE_SCHEDULER_DEPLOYMENT_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_SCHEDULER_DEPLOYMENT_CONTROLLER_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let payload = json!({
        "type": "mandoforge.scheduler_deployment_validation",
        "subject": subject,
        "checked_at": checked_at,
        "readiness": readiness,
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "scheduler deployment controller failed with status {http_status}"
        )));
    }
    Ok(json!({
        "attempted": true,
        "status": body
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("validated"),
        "controller_response": body,
    }))
}

fn scheduler_container_env_uses_secret(
    container: Option<&Value>,
    name: &str,
    secret_key: &str,
) -> bool {
    container
        .and_then(|container| container.get("env"))
        .and_then(Value::as_array)
        .and_then(|env| {
            env.iter()
                .find(|entry| entry.get("name").and_then(Value::as_str) == Some(name))
        })
        .and_then(|entry| entry.pointer("/valueFrom/secretKeyRef/key"))
        .and_then(Value::as_str)
        == Some(secret_key)
}

fn secret_manifest_defines_key(relative_path: &str, key: &str) -> bool {
    read_yaml_manifest_value(relative_path)
        .and_then(|manifest| manifest.pointer("/stringData").cloned())
        .and_then(|string_data| string_data.as_object().cloned())
        .is_some_and(|string_data| string_data.contains_key(key))
}

fn scheduler_run_history_item(log: AuditLog) -> Option<SchedulerRunHistoryItem> {
    let run_id = log
        .details
        .get("run_id")
        .and_then(Value::as_str)
        .and_then(|value| Uuid::parse_str(value).ok());
    let idempotency_key = log
        .details
        .get("idempotency_key")
        .and_then(Value::as_str)
        .map(str::to_string);
    let owner = log
        .details
        .get("owner")
        .and_then(Value::as_str)
        .map(str::to_string);
    let status = log
        .details
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown")
        .to_string();
    let team_count = log
        .details
        .get("team_count")
        .and_then(Value::as_u64)
        .unwrap_or(0) as usize;
    let actions: Vec<String> = log
        .details
        .get("actions")
        .and_then(Value::as_array)
        .map(|actions| {
            actions
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default();
    Some(SchedulerRunHistoryItem {
        audit_log_id: log.id,
        run_id,
        idempotency_key,
        owner,
        status,
        team_count,
        action_count: actions.len(),
        actions,
        created_at: log.created_at,
    })
}

pub(crate) async fn build_scheduler_due_plan(
    state: &AppState,
) -> Result<SchedulerDuePlan, AppError> {
    let generated_at = Utc::now();
    let mut actions = Vec::new();
    let policy_revisions = state.list_policy_revisions().await?;
    let policy_due_count = policy_revisions
        .iter()
        .filter(|revision| policy_revision_is_due_for_scheduled_activation(revision, generated_at))
        .count();
    actions.push(scheduler_due_plan_item(
        "policy",
        "policy_rollout_activation",
        "auto",
        policy_due_count,
        policy_revisions.len().saturating_sub(policy_due_count),
        policy_revisions.len(),
        if policy_due_count > 0 {
            "activate earliest due passed policy revision"
        } else {
            "no passed draft policy revision is inside its activation window"
        },
    ));

    let providers = state.list_providers().await?;
    let audit_logs = state.list_audit_logs(None).await?;
    let provider_gate_due = provider_policy_gate_is_due(&providers, &audit_logs, generated_at);
    actions.push(scheduler_due_plan_item(
        "providers",
        "provider_policy_gate",
        "auto",
        usize::from(provider_gate_due),
        providers
            .len()
            .saturating_sub(usize::from(provider_gate_due)),
        providers.len(),
        if provider_gate_due {
            "run provider policy gate because no fresh gate run covers configured providers"
        } else if providers.is_empty() {
            "no providers are configured for policy gate evaluation"
        } else {
            "provider policy gate has fresh run history"
        },
    ));

    let approvals = state.list_approvals().await?;
    let approval_rules = state.list_approval_escalation_rules().await?;
    let pending_approvals: Vec<_> = approvals
        .iter()
        .filter(|approval| approval.status == "pending")
        .collect();
    let expired_approval_count = pending_approvals
        .iter()
        .filter(|approval| approval_is_expired_at(approval, generated_at))
        .count();
    let escalation_due_count = pending_approvals
        .iter()
        .filter(|approval| {
            !approval_is_expired_at(approval, generated_at)
                && next_due_escalation_rule(approval, &approval_rules, generated_at).is_some()
        })
        .count();
    let approval_due_count = expired_approval_count + escalation_due_count;
    actions.push(scheduler_due_plan_item(
        "approvals",
        "approval_expiration_and_escalation",
        "auto",
        approval_due_count,
        pending_approvals.len().saturating_sub(approval_due_count),
        pending_approvals.len(),
        if approval_due_count > 0 {
            "expire overdue approvals and escalate pending approvals whose rules are due"
        } else {
            "no pending approval is expired or due for escalation"
        },
    ));

    let pending_releases = state.list_pending_agent_releases().await?;
    let release_due_count = pending_releases
        .iter()
        .filter(|release| {
            release_automation_is_expired(release, generated_at)
                || matches!(
                    release_automation_due_decision(release, generated_at),
                    ReleaseAutomationDecision::Promote
                )
        })
        .count();
    actions.push(scheduler_due_plan_item(
        "agent_releases",
        "release_promotion_automation",
        "auto",
        release_due_count,
        pending_releases.len().saturating_sub(release_due_count),
        pending_releases.len(),
        if release_due_count > 0 {
            "promote auto-approved releases or reject expired pending releases"
        } else {
            "no pending release is due for automated decision"
        },
    ));

    let mut team_count = 0usize;
    let mut mcp_server_count = 0usize;
    let mut mcp_health_due_count = 0usize;
    let mut mcp_rollout_due_count = 0usize;
    let mut mcp_rollout_skipped_count = 0usize;
    for organization in state
        .list_organizations()
        .await?
        .into_iter()
        .filter(|organization| organization.archived_at.is_none())
    {
        for team in state
            .list_teams(organization.id)
            .await?
            .into_iter()
            .filter(|team| team.archived_at.is_none())
        {
            team_count += 1;
            let servers = state.list_mcp_servers(team.id).await?;
            mcp_server_count += servers.len();
            for server in servers {
                if mcp_server_health_check_is_due(&server, generated_at) {
                    mcp_health_due_count += 1;
                }
                match mcp_pending_rollout(&server) {
                    Some(rollout)
                        if mcp_rollout_is_due(rollout, generated_at)
                            || mcp_rollout_is_expired(rollout, generated_at) =>
                    {
                        mcp_rollout_due_count += 1;
                    }
                    Some(_) => mcp_rollout_skipped_count += 1,
                    None => {}
                }
            }
        }
    }
    actions.push(scheduler_due_plan_item(
        "mcp",
        "mcp_scheduled_health_checks",
        "auto",
        mcp_health_due_count,
        mcp_server_count.saturating_sub(mcp_health_due_count),
        mcp_server_count,
        if mcp_health_due_count > 0 {
            "run scheduled MCP health checks for due connectors"
        } else {
            "no active MCP connector health check is due"
        },
    ));
    actions.push(scheduler_due_plan_item(
        "mcp",
        "mcp_connector_rollouts",
        "auto",
        mcp_rollout_due_count,
        mcp_rollout_skipped_count,
        mcp_rollout_due_count + mcp_rollout_skipped_count,
        if mcp_rollout_due_count > 0 {
            "apply due MCP connector rollouts and expire overdue rollout windows"
        } else {
            "no pending MCP connector rollout is due"
        },
    ));

    let codex_runs = state.list_codex_app_server_runs().await?;
    let codex_stale_candidates = select_stale_codex_app_server_runs(
        &codex_runs,
        generated_at,
        default_codex_stale_after_seconds(),
    )
    .len();
    actions.push(scheduler_due_plan_item(
        "codex_app_server",
        "stale_turn_polling",
        "auto",
        codex_stale_candidates,
        codex_runs.len().saturating_sub(codex_stale_candidates),
        codex_runs.len(),
        if codex_stale_candidates > 0 {
            "poll stale non-terminal Codex App Server turns"
        } else {
            "no stale non-terminal Codex App Server turn is due"
        },
    ));

    let mut workflow_scheduled_total = 0usize;
    let mut workflow_scheduled_due_count = 0usize;
    for run in state.list_workflow_runs().await? {
        if workflow_step_status_terminal(&run.status) {
            continue;
        }
        let scheduled_steps = state
            .list_workflow_step_runs(run.id)
            .await?
            .into_iter()
            .filter(|step| step.status == "scheduled")
            .collect::<Vec<_>>();
        if scheduled_steps.is_empty() {
            continue;
        }
        workflow_scheduled_total += scheduled_steps.len();
        workflow_scheduled_due_count += scheduled_steps
            .iter()
            .filter(|step| {
                step.scheduled_at
                    .is_some_and(|scheduled_at| scheduled_at <= generated_at)
            })
            .count();
    }
    actions.push(scheduler_due_plan_item(
        "workflows",
        "workflow_scheduled_step_activation",
        "auto",
        workflow_scheduled_due_count,
        workflow_scheduled_total.saturating_sub(workflow_scheduled_due_count),
        workflow_scheduled_total,
        if workflow_scheduled_due_count > 0 {
            "activate scheduled workflow retry/delay steps whose due time has passed"
        } else if workflow_scheduled_total > 0 {
            "scheduled workflow steps exist but none are due yet"
        } else {
            "no scheduled workflow steps are pending"
        },
    ));
    if let Some(item) = actions.last_mut() {
        if workflow_scheduled_due_count == 0 && workflow_scheduled_total > 0 {
            item.status = "waiting".to_string();
            item.severity = "info".to_string();
            item.skipped_count = workflow_scheduled_total;
        }
    }

    let (
        semantic_synthesis_scheduled_count,
        semantic_synthesis_due_count,
        semantic_synthesis_skipped_count,
    ) = build_semantic_synthesis_schedule_due_counts(state, generated_at).await?;
    actions.push(scheduler_due_plan_item(
        "memory",
        "semantic_synthesis_schedule_run",
        "auto",
        semantic_synthesis_due_count,
        semantic_synthesis_skipped_count,
        semantic_synthesis_scheduled_count,
        if semantic_synthesis_due_count > 0 {
            "create due reflection/dreaming artifacts and review-gated memory writeback candidates"
        } else if semantic_synthesis_scheduled_count > 0 {
            "semantic synthesis schedules exist but none are due"
        } else {
            "no semantic synthesis schedules are registered"
        },
    ));
    let (semantic_aging_policy_count, semantic_aging_due_count, semantic_aging_skipped_count) =
        build_scheduled_runtime_object_due_counts(
            state,
            generated_at,
            "semantic_aging_policy",
            "semantic_aging.policy_run",
        )
        .await?;
    actions.push(scheduler_due_plan_item(
        "memory",
        "semantic_aging_policy_run",
        "auto",
        semantic_aging_due_count,
        semantic_aging_skipped_count,
        semantic_aging_policy_count,
        if semantic_aging_due_count > 0 {
            "archive or flag stale semantic memory according to due aging policies"
        } else if semantic_aging_policy_count > 0 {
            "semantic aging policies exist but none are due"
        } else {
            "no semantic aging policies are registered"
        },
    ));

    let stale_remote_computer_attachments = state.list_stale_remote_computer_attachments().await?;
    let remote_computer_leases = state.list_remote_computer_leases().await?;
    let expired_remote_computer_leases = remote_computer_leases
        .iter()
        .filter(|lease| {
            lease.status == "leased"
                && lease
                    .lease_expires_at
                    .is_some_and(|lease_expires_at| lease_expires_at <= generated_at)
        })
        .count();
    let remote_computer_due_count =
        stale_remote_computer_attachments.len() + expired_remote_computer_leases;
    actions.push(scheduler_due_plan_item(
        "remote_computers",
        "remote_computer_stale_reclaim",
        "auto",
        remote_computer_due_count,
        remote_computer_leases
            .len()
            .saturating_sub(expired_remote_computer_leases),
        remote_computer_leases.len() + stale_remote_computer_attachments.len(),
        if remote_computer_due_count > 0 {
            "reclaim stale Remote Computer attachments and expired leases"
        } else {
            "no stale Remote Computer attachment or expired lease is due"
        },
    ));
    let remote_computer_readiness = build_remote_computer_readiness(state).await?;
    let sidecar_supervision = remote_computer_readiness.sidecar_supervision;
    let unhealthy_sidecar_count =
        sidecar_supervision.missing_heartbeat_count + sidecar_supervision.stale_heartbeat_count;
    actions.push(scheduler_due_plan_item(
        "remote_computers",
        "remote_computer_sidecar_supervision",
        "auto",
        unhealthy_sidecar_count,
        sidecar_supervision
            .active_remote_computer_count
            .saturating_sub(unhealthy_sidecar_count),
        sidecar_supervision.active_remote_computer_count,
        if unhealthy_sidecar_count > 0 {
            "record missing or stale Remote Computer artifact-discovery sidecar supervision evidence"
        } else if sidecar_supervision.active_remote_computer_count == 0 {
            "no active Remote Computer sidecar needs supervision"
        } else {
            "Remote Computer sidecar heartbeats are within the configured threshold"
        },
    ));

    let usage_export_enabled = usage_finance_export_schedule_enabled();
    let usage_export_ready = usage_finance_export_webhook_url().is_some();
    let usage_export_due_count = usize::from(usage_export_enabled);
    let mut usage_item = scheduler_due_plan_item(
        "usage",
        "usage_finance_export_delivery",
        "auto",
        usage_export_due_count,
        usize::from(!usage_export_enabled),
        1,
        if usage_export_enabled && usage_export_ready {
            "deliver the scheduled usage finance export to the configured webhook"
        } else if usage_export_enabled {
            "scheduled usage finance export is enabled but no target webhook is configured"
        } else {
            "scheduled usage finance export is disabled"
        },
    );
    if !usage_export_enabled {
        usage_item.status = "disabled".to_string();
        usage_item.severity = "info".to_string();
    } else if !usage_export_ready {
        usage_item.status = "blocked".to_string();
        usage_item.severity = "warning".to_string();
    }
    actions.push(usage_item);

    let usage = build_usage_summary(state).await?;
    let cost_alerts = build_cost_alerts(&usage.provider_budgets, generated_at);
    let alert_routes = state.list_cost_alert_routes().await?;
    let active_alert_route_count = alert_routes
        .iter()
        .filter(|route| route.status == "active")
        .count();
    let alert_delivery_ready =
        active_alert_route_count > 0 || state.cost_alert_webhook_url.is_some();
    let mut alert_delivery_item = scheduler_due_plan_item(
        "usage",
        "usage_cost_alert_delivery",
        "auto",
        usize::from(!cost_alerts.is_empty()),
        usize::from(cost_alerts.is_empty()),
        cost_alerts.len().max(1),
        if !cost_alerts.is_empty() && alert_delivery_ready {
            "deliver current provider budget alerts through active alert routes or fallback webhook"
        } else if !cost_alerts.is_empty() {
            "current provider budget alerts exist but no active alert route or fallback webhook is configured"
        } else {
            "no current provider budget alert requires delivery"
        },
    );
    if cost_alerts.is_empty() {
        alert_delivery_item.status = "idle".to_string();
        alert_delivery_item.severity = "info".to_string();
    } else if !alert_delivery_ready {
        alert_delivery_item.status = "blocked".to_string();
        alert_delivery_item.severity = "critical".to_string();
    }
    actions.push(alert_delivery_item);

    let actionable_count = actions
        .iter()
        .filter(|item| item.due_count > 0 && item.status != "blocked")
        .count();
    let item_count = actions.len();
    let status = if actions.iter().any(|item| item.status == "blocked") {
        "blocked"
    } else if actionable_count > 0 {
        "ready"
    } else {
        "idle"
    }
    .to_string();
    Ok(SchedulerDuePlan {
        status,
        generated_at,
        team_count,
        item_count,
        actionable_count,
        actions,
    })
}

fn scheduler_due_plan_item(
    area: &str,
    action: &str,
    mode: &str,
    due_count: usize,
    skipped_count: usize,
    target_count: usize,
    reason: &str,
) -> SchedulerDuePlanItem {
    SchedulerDuePlanItem {
        area: area.to_string(),
        action: action.to_string(),
        mode: mode.to_string(),
        status: if due_count > 0 { "due" } else { "idle" }.to_string(),
        due_count,
        skipped_count,
        target_count,
        severity: if due_count > 0 { "warning" } else { "info" }.to_string(),
        reason: reason.to_string(),
    }
}

async fn execute_scheduler_due_tasks(
    state: &AppState,
    input: Option<SchedulerRunDueRequest>,
) -> Result<SchedulerDueRun, AppError> {
    let checked_at = Utc::now();
    let request = normalize_scheduler_run_due_request(input, checked_at)?;
    if let Some(existing_run) =
        scheduler_replay_due_run(state, request.idempotency_key.as_deref()).await?
    {
        return Ok(existing_run);
    }
    let providers = state.list_providers().await?;
    let audit_logs = state.list_audit_logs(None).await?;
    let provider_policy_gate = if provider_policy_gate_is_due(&providers, &audit_logs, checked_at) {
        Some(
            execute_provider_policy_gate(state, Some("system".to_string()), "system")
                .await?
                .run,
        )
    } else {
        None
    };
    let policy_rollout = execute_due_policy_rollouts(state, "scheduler", "system").await?;
    let approval_escalations = execute_due_approval_escalations(state).await?;
    let agent_releases = execute_due_agent_release_promotions(state).await?;
    let codex_app_server_stale_polls = execute_stale_codex_app_server_polls(
        state,
        CodexAppServerStalePollRequest::default(),
        "system",
        "system",
    )
    .await?;
    let workflow_scheduled_steps = execute_due_workflow_scheduled_steps(state, checked_at).await?;
    let semantic_synthesis_schedules =
        execute_due_semantic_synthesis_schedules(state, checked_at).await?;
    let semantic_aging_policies = execute_due_semantic_aging_policies(state, checked_at).await?;
    let usage = build_usage_summary(state).await?;
    let cost_alerts = build_cost_alerts(&usage.provider_budgets, checked_at);
    let active_alert_route_count = state
        .list_cost_alert_routes()
        .await?
        .iter()
        .filter(|route| route.status == "active")
        .count();
    let cost_alert_delivery = if !cost_alerts.is_empty()
        && (active_alert_route_count > 0 || state.cost_alert_webhook_url.is_some())
    {
        Some(execute_cost_alert_delivery(state, checked_at).await?)
    } else {
        None
    };
    let usage_finance_export =
        execute_usage_finance_export_delivery(state, true, "system", Some("system")).await?;
    let remote_computer_sidecar_supervision =
        execute_remote_computer_sidecar_supervision(state).await?;
    let remote_computer_reclaim = execute_remote_computer_stale_reclaim(state).await?;
    let mut mcp_health_runs = Vec::new();
    let mut mcp_rollout_runs = Vec::new();
    let mut team_count = 0usize;
    for organization in state
        .list_organizations()
        .await?
        .into_iter()
        .filter(|organization| organization.archived_at.is_none())
    {
        for team in state
            .list_teams(organization.id)
            .await?
            .into_iter()
            .filter(|team| team.archived_at.is_none())
        {
            team_count += 1;
            mcp_health_runs.push(execute_due_mcp_server_health_checks(state, team.id).await?);
            mcp_rollout_runs.push(execute_due_mcp_server_rollouts(state, team.id).await?);
        }
    }
    let mut actions = Vec::new();
    if policy_rollout.status == "activated" {
        actions.push("policy_rollout_activated".to_string());
    }
    if provider_policy_gate.is_some() {
        actions.push("provider_policy_gate_processed".to_string());
    }
    if approval_escalations.expired_count > 0 || approval_escalations.escalated_count > 0 {
        actions.push("approval_escalations_processed".to_string());
    }
    if agent_releases.promoted_count > 0 || agent_releases.rejected_count > 0 {
        actions.push("agent_release_automation_processed".to_string());
    }
    if mcp_health_runs.iter().any(|run| run.due_count > 0) {
        actions.push("mcp_health_checks_processed".to_string());
    }
    if mcp_rollout_runs
        .iter()
        .any(|run| run.applied_count > 0 || run.expired_count > 0 || run.failed_count > 0)
    {
        actions.push("mcp_rollouts_processed".to_string());
    }
    if codex_app_server_stale_polls.polled_count > 0
        || codex_app_server_stale_polls.failed_count > 0
    {
        actions.push("codex_app_server_stale_polls_processed".to_string());
    }
    if workflow_scheduled_steps.activated_count > 0 {
        actions.push("workflow_scheduled_steps_activated".to_string());
    }
    if semantic_synthesis_schedules.created_count > 0
        || semantic_synthesis_schedules.failed_count > 0
    {
        actions.push("semantic_synthesis_schedules_processed".to_string());
    }
    if semantic_aging_policies.archived_count > 0 || semantic_aging_policies.failed_count > 0 {
        actions.push("semantic_aging_policies_processed".to_string());
    }
    if cost_alert_delivery.is_some() {
        actions.push("usage_cost_alert_delivery_processed".to_string());
    }
    if usage_finance_export.status != "disabled" {
        actions.push("usage_finance_export_processed".to_string());
    }
    if remote_computer_reclaim.reclaimed_attachment_count > 0
        || remote_computer_reclaim.reclaimed_lease_count > 0
    {
        actions.push("remote_computer_reclaim_processed".to_string());
    }
    if remote_computer_sidecar_supervision.missing_heartbeat_count > 0
        || remote_computer_sidecar_supervision.stale_heartbeat_count > 0
    {
        actions.push("remote_computer_sidecar_supervision_processed".to_string());
    }
    let status = if actions.is_empty() {
        "noop"
    } else {
        "completed"
    }
    .to_string();
    let run = SchedulerDueRun {
        run_id: Uuid::new_v4(),
        idempotency_key: request.idempotency_key.clone(),
        owner: request.owner.clone().expect("normalized owner"),
        run_window_start: request
            .run_window_start
            .expect("normalized run window start"),
        run_window_end: request.run_window_end.expect("normalized run window end"),
        retry_policy: request
            .retry_policy
            .clone()
            .expect("normalized retry policy"),
        replayed: false,
        status,
        checked_at,
        team_count,
        actions,
        provider_policy_gate,
        policy_rollout,
        approval_escalations,
        agent_releases,
        workflow_scheduled_steps: Some(workflow_scheduled_steps),
        semantic_synthesis_schedules: Some(semantic_synthesis_schedules),
        semantic_aging_policies: Some(semantic_aging_policies),
        mcp_health_runs,
        mcp_rollout_runs,
        codex_app_server_stale_polls,
        cost_alert_delivery,
        usage_finance_export,
        remote_computer_reclaim,
        remote_computer_sidecar_supervision,
    };
    let run_value = serde_json::to_value(&run)?;
    state
        .append_audit_log(new_audit_log(
            None,
            "system",
            None,
            "scheduler.run_due",
            "scheduler",
            None,
            json!({
                "status": run.status,
                "run_id": run.run_id,
                "idempotency_key": run.idempotency_key,
                "owner": run.owner,
                "run_window_start": run.run_window_start,
                "run_window_end": run.run_window_end,
                "retry_policy": run.retry_policy,
                "team_count": run.team_count,
                "actions": run.actions,
                "provider_policy_gate_status": run.provider_policy_gate.as_ref().map(|gate| gate.status.clone()),
                "workflow_scheduled_step_status": run.workflow_scheduled_steps.as_ref().map(|workflow| workflow.status.clone()),
                "workflow_scheduled_step_activated_count": run.workflow_scheduled_steps.as_ref().map(|workflow| workflow.activated_count).unwrap_or(0),
                "semantic_synthesis_schedule_status": run.semantic_synthesis_schedules.as_ref().map(|semantic| semantic.status.clone()),
                "semantic_synthesis_schedule_created_count": run.semantic_synthesis_schedules.as_ref().map(|semantic| semantic.created_count).unwrap_or(0),
                "semantic_synthesis_schedule_failed_count": run.semantic_synthesis_schedules.as_ref().map(|semantic| semantic.failed_count).unwrap_or(0),
                "semantic_aging_policy_status": run.semantic_aging_policies.as_ref().map(|semantic| semantic.status.clone()),
                "semantic_aging_policy_archived_count": run.semantic_aging_policies.as_ref().map(|semantic| semantic.archived_count).unwrap_or(0),
                "cost_alert_delivery_status": run.cost_alert_delivery.as_ref().map(|delivery| delivery.status.clone()),
                "remote_computer_sidecar_supervision_status": run.remote_computer_sidecar_supervision.status,
                "remote_computer_sidecar_missing_heartbeat_count": run.remote_computer_sidecar_supervision.missing_heartbeat_count,
                "remote_computer_sidecar_stale_heartbeat_count": run.remote_computer_sidecar_supervision.stale_heartbeat_count,
                "checked_at": run.checked_at,
                "run": run_value,
            }),
        ))
        .await?;
    Ok(run)
}

fn normalize_scheduler_run_due_request(
    input: Option<SchedulerRunDueRequest>,
    checked_at: DateTime<Utc>,
) -> Result<SchedulerRunDueRequest, AppError> {
    let input = input.unwrap_or(SchedulerRunDueRequest {
        idempotency_key: None,
        owner: None,
        run_window_start: None,
        run_window_end: None,
        retry_policy: None,
    });
    let idempotency_key = input
        .idempotency_key
        .map(|value| validate_scheduler_slug("idempotency_key", &value))
        .transpose()?;
    let owner = input
        .owner
        .map(|value| validate_scheduler_slug("owner", &value))
        .transpose()?
        .unwrap_or_else(|| "manual".to_string());
    let run_window_start = input.run_window_start.unwrap_or(checked_at);
    let run_window_end = input
        .run_window_end
        .unwrap_or_else(|| checked_at + ChronoDuration::minutes(5));
    if run_window_end <= run_window_start {
        return Err(AppError::bad_request(
            "scheduler run_window_end must be after run_window_start",
        ));
    }
    let retry_policy = input.retry_policy.unwrap_or(SchedulerRetryPolicy {
        max_attempts: 1,
        backoff_seconds: 0,
    });
    if retry_policy.max_attempts == 0 || retry_policy.max_attempts > 10 {
        return Err(AppError::bad_request(
            "scheduler retry_policy.max_attempts must be between 1 and 10",
        ));
    }
    if retry_policy.backoff_seconds > 3600 {
        return Err(AppError::bad_request(
            "scheduler retry_policy.backoff_seconds must be 3600 or less",
        ));
    }
    Ok(SchedulerRunDueRequest {
        idempotency_key,
        owner: Some(owner),
        run_window_start: Some(run_window_start),
        run_window_end: Some(run_window_end),
        retry_policy: Some(retry_policy),
    })
}

async fn scheduler_replay_due_run(
    state: &AppState,
    idempotency_key: Option<&str>,
) -> Result<Option<SchedulerDueRun>, AppError> {
    let Some(idempotency_key) = idempotency_key else {
        return Ok(None);
    };
    let audit_logs = state.list_audit_logs(None).await?;
    let Some(log) = audit_logs
        .into_iter()
        .filter(|log| log.action == "scheduler.run_due")
        .find(|log| log.details["idempotency_key"].as_str() == Some(idempotency_key))
    else {
        return Ok(None);
    };
    let mut run: SchedulerDueRun = serde_json::from_value(log.details["run"].clone())
        .map_err(|error| AppError::bad_request(error.to_string()))?;
    run.replayed = true;
    Ok(Some(run))
}

fn validate_scheduler_slug(field: &str, value: &str) -> Result<String, AppError> {
    let trimmed = value.trim();
    if trimmed.is_empty()
        || trimmed.len() > 128
        || !trimmed
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | ':'))
    {
        return Err(AppError::bad_request(format!(
            "scheduler {field} must be non-empty token text"
        )));
    }
    Ok(trimmed.to_string())
}

async fn execute_remote_computer_sidecar_supervision(
    state: &AppState,
) -> Result<RemoteComputerSidecarSupervisionRun, AppError> {
    let checked_at = Utc::now();
    let readiness = build_remote_computer_readiness(state).await?;
    let supervision = readiness.sidecar_supervision;
    let mut actions = Vec::new();
    if supervision.missing_heartbeat_count > 0 {
        actions.push("flag_missing_artifact_discovery_sidecar_heartbeats".to_string());
    }
    if supervision.stale_heartbeat_count > 0 {
        actions.push("flag_stale_artifact_discovery_sidecar_heartbeats".to_string());
    }
    if !actions.is_empty() {
        actions
            .push("keep_remote_computer_pods_out_of_production_until_sidecars_recover".to_string());
    }
    let status = if actions.is_empty() {
        "ok"
    } else {
        "attention"
    }
    .to_string();
    let run = RemoteComputerSidecarSupervisionRun {
        status,
        checked_at,
        active_remote_computer_count: supervision.active_remote_computer_count,
        heartbeat_count: supervision.heartbeat_count,
        missing_heartbeat_count: supervision.missing_heartbeat_count,
        stale_heartbeat_count: supervision.stale_heartbeat_count,
        stale_after_seconds: supervision.stale_after_seconds,
        actions,
    };
    state
        .append_audit_log(new_audit_log(
            None,
            "system",
            None,
            "remote_computer.sidecar_supervision_run",
            "remote_computer_sidecar",
            None,
            json!({
                "status": run.status,
                "actions": run.actions,
                "active_remote_computer_count": run.active_remote_computer_count,
                "heartbeat_count": run.heartbeat_count,
                "missing_heartbeat_count": run.missing_heartbeat_count,
                "stale_heartbeat_count": run.stale_heartbeat_count,
                "stale_after_seconds": run.stale_after_seconds,
                "checked_at": run.checked_at,
            }),
        ))
        .await?;
    Ok(run)
}

