async fn execute_observability_remediation_controller<F>(
    lookup: &F,
    before: &ObservabilityBackpressure,
    after: &ObservabilityBackpressure,
    actions: &[String],
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_OBSERVABILITY_REMEDIATION_CONTROLLER_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request("MANDOFORGE_OBSERVABILITY_REMEDIATION_CONTROLLER_URL is required")
        })?;
    let timeout_seconds = lookup("MANDOFORGE_OBSERVABILITY_REMEDIATION_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_OBSERVABILITY_REMEDIATION_CONTROLLER_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let payload = json!({
        "type": "mandoforge.observability_remediation",
        "actions": actions,
        "before": before,
        "after": after,
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "observability remediation controller failed with status {http_status}"
        )));
    }
    let controller_status = body
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("remediated");
    let remediated = matches!(
        controller_status,
        "remediated" | "success" | "ok" | "validated"
    );
    Ok(json!({
        "attempted": true,
        "status": if remediated { "remediated" } else { "failed" },
        "http_status": http_status.as_u16(),
        "provider_status": controller_status,
        "remediation_id": body.get("remediation_id").and_then(Value::as_str),
        "message": body.get("message").and_then(Value::as_str),
        "steps": body.get("steps").cloned().unwrap_or_else(|| json!([])),
    }))
}

pub(crate) async fn build_observability_collector_readiness(
    state: &AppState,
) -> ObservabilityCollectorReadiness {
    let generated_at = Utc::now();
    let config = &state.observability_config;
    let endpoint = config
        .otlp_endpoint
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.trim_end_matches('/').to_string());
    let endpoint_configured = endpoint.is_some();
    let mut attention_items = Vec::new();
    if !config.is_enabled() {
        attention_items.push(ObservabilityCollectorAttentionItem {
            kind: "otlp_disabled".to_string(),
            severity: "warning".to_string(),
            message: "OTLP export is disabled; collector readiness cannot be proven".to_string(),
        });
    }
    if config.is_enabled() && !endpoint_configured {
        attention_items.push(ObservabilityCollectorAttentionItem {
            kind: "otlp_endpoint_missing".to_string(),
            severity: "critical".to_string(),
            message: "OTLP export is enabled without a collector endpoint".to_string(),
        });
    }
    if config.sample_ratio <= 0.0 {
        attention_items.push(ObservabilityCollectorAttentionItem {
            kind: "telemetry_sampling_zero".to_string(),
            severity: "warning".to_string(),
            message: "telemetry sample ratio is zero; runtime events will not be exported"
                .to_string(),
        });
    }
    let health_check = if config.is_enabled() && endpoint_configured {
        match state.telemetry_exporter.health_check(config).await {
            Ok(()) => ObservabilityCollectorHealthCheck {
                status: "healthy".to_string(),
                checked: true,
                message: "collector health check succeeded".to_string(),
            },
            Err(error) => {
                attention_items.push(ObservabilityCollectorAttentionItem {
                    kind: "collector_health_failed".to_string(),
                    severity: "critical".to_string(),
                    message: error.message.clone(),
                });
                ObservabilityCollectorHealthCheck {
                    status: "failed".to_string(),
                    checked: true,
                    message: error.message,
                }
            }
        }
    } else {
        ObservabilityCollectorHealthCheck {
            status: "skipped".to_string(),
            checked: false,
            message: "collector health check skipped because OTLP endpoint is not configured"
                .to_string(),
        }
    };
    let signal_paths = ["logs", "traces", "metrics"]
        .into_iter()
        .map(|signal| ObservabilityCollectorSignalPath {
            signal: signal.to_string(),
            url: endpoint.as_ref().map(|endpoint| match signal {
                "logs" => format!("{endpoint}/v1/logs"),
                "traces" => format!("{endpoint}/v1/traces"),
                "metrics" => format!("{endpoint}/v1/metrics"),
                _ => endpoint.clone(),
            }),
            status: if endpoint_configured {
                "configured".to_string()
            } else {
                "missing".to_string()
            },
        })
        .collect::<Vec<_>>();
    let production_ops = build_observability_collector_production_ops(
        config.is_enabled(),
        endpoint_configured,
        config.sample_ratio,
        &health_check,
        &signal_paths,
    );
    let audit_logs = state.list_audit_logs(None).await.unwrap_or_default();
    let deployment_readiness = build_observability_collector_deployment_readiness(
        config.is_enabled(),
        endpoint_configured,
        observability_collector_deployment_controller_required(&|key| std::env::var(key).ok()),
        observability_collector_deployment_controller_configured(&|key| std::env::var(key).ok()),
        &audit_logs,
        generated_at,
    );
    let cluster_rollout = build_observability_collector_cluster_rollout_readiness(
        &deployment_readiness,
        &audit_logs,
        generated_at,
        observability_collector_cluster_controller_required(&|key| std::env::var(key).ok()),
        observability_collector_cluster_controller_configured(&|key| std::env::var(key).ok()),
    );
    let remediation_supervision = build_observability_remediation_supervision_readiness(
        observability_remediation_controller_required(&|key| std::env::var(key).ok()),
        observability_remediation_controller_configured(&|key| std::env::var(key).ok()),
        &audit_logs,
        generated_at,
    );
    if production_ops.production_blocked {
        attention_items.push(ObservabilityCollectorAttentionItem {
            kind: "collector_production_ops_blocked".to_string(),
            severity: if production_ops.status == "blocked" {
                "critical".to_string()
            } else {
                "warning".to_string()
            },
            message: production_ops.message.clone(),
        });
    }
    if deployment_readiness.production_blocked {
        attention_items.push(ObservabilityCollectorAttentionItem {
            kind: "collector_deployment_validation_blocked".to_string(),
            severity: if deployment_readiness.status == "blocked" {
                "critical".to_string()
            } else {
                "warning".to_string()
            },
            message: deployment_readiness.message.clone(),
        });
    }
    if remediation_supervision.production_blocked {
        attention_items.push(ObservabilityCollectorAttentionItem {
            kind: "observability_remediation_supervision_blocked".to_string(),
            severity: "critical".to_string(),
            message: remediation_supervision.message.clone(),
        });
    }
    if cluster_rollout.production_blocked {
        attention_items.push(ObservabilityCollectorAttentionItem {
            kind: "collector_cluster_rollout_blocked".to_string(),
            severity: "critical".to_string(),
            message: cluster_rollout.message.clone(),
        });
    }
    let status = if attention_items
        .iter()
        .any(|item| item.severity == "critical")
    {
        "failed"
    } else if attention_items.is_empty() {
        "ready"
    } else {
        "warning"
    }
    .to_string();
    ObservabilityCollectorReadiness {
        generated_at,
        status,
        service_name: config.service_name.clone(),
        otlp_enabled: config.is_enabled(),
        endpoint_configured,
        endpoint,
        sample_ratio: config.sample_ratio,
        health_check,
        signal_paths,
        production_ops,
        deployment_readiness,
        cluster_rollout,
        remediation_supervision,
        attention_items,
    }
}

fn observability_remediation_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_OBSERVABILITY_REMEDIATION_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        })
        .unwrap_or(false)
}

fn build_observability_collector_production_ops(
    otlp_enabled: bool,
    endpoint_configured: bool,
    sample_ratio: f64,
    health_check: &ObservabilityCollectorHealthCheck,
    signal_paths: &[ObservabilityCollectorSignalPath],
) -> ObservabilityCollectorProductionOpsReadiness {
    let signal_path_count = signal_paths.len();
    let configured_signal_path_count = signal_paths
        .iter()
        .filter(|path| path.status == "configured" && path.url.is_some())
        .count();
    let (status, production_blocked, message) = if !otlp_enabled {
        (
            "blocked",
            true,
            "Observability production ops are blocked until OTLP export is enabled".to_string(),
        )
    } else if !endpoint_configured {
        (
            "blocked",
            true,
            "Observability production ops are blocked until an OTLP collector endpoint is configured"
                .to_string(),
        )
    } else if configured_signal_path_count < 3 {
        (
            "blocked",
            true,
            "Observability production ops are blocked until logs, traces, and metrics paths are configured"
                .to_string(),
        )
    } else if sample_ratio <= 0.0 {
        (
            "blocked",
            true,
            "Observability production ops are blocked because telemetry sampling is disabled"
                .to_string(),
        )
    } else if !health_check.checked {
        (
            "blocked",
            true,
            "Observability production ops are blocked until collector health is checked"
                .to_string(),
        )
    } else if health_check.status != "healthy" {
        (
            "blocked",
            true,
            "Observability production ops are blocked by a failed collector health check"
                .to_string(),
        )
    } else {
        (
            "ready",
            false,
            "Observability collector is healthy and logs, traces, and metrics paths are configured"
                .to_string(),
        )
    };
    ObservabilityCollectorProductionOpsReadiness {
        status: status.to_string(),
        production_blocked,
        signal_path_count,
        configured_signal_path_count,
        health_checked: health_check.checked,
        health_status: health_check.status.clone(),
        message,
    }
}

fn build_observability_collector_deployment_readiness(
    otlp_enabled: bool,
    endpoint_configured: bool,
    controller_required: bool,
    controller_configured: bool,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
) -> ObservabilityCollectorDeploymentReadiness {
    let latest_validation = audit_logs
        .iter()
        .filter(|log| log.action == "observability.collector_deployment_validation")
        .max_by_key(|log| log.created_at);
    let latest_validation_at = latest_validation.map(|log| log.created_at);
    let latest_validation_age_hours =
        latest_validation_at.map(|created_at| (generated_at - created_at).num_hours());
    let latest_validation_status = latest_validation
        .and_then(|log| log.details.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_validation_healthy = latest_validation
        .and_then(|log| log.details.get("healthy"))
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let latest_controller_status = latest_validation
        .and_then(|log| log.details["controller_execution"]["status"].as_str())
        .map(str::to_string);
    let latest_controller_age_hours = latest_validation
        .filter(|_| latest_controller_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let latest_controller_validated = latest_controller_status
        .as_deref()
        .map(|status| status == "validated")
        .unwrap_or(false);
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let mut blocking_reasons = Vec::new();

    if !otlp_enabled {
        blocking_reasons.push("OTLP export is disabled".to_string());
    }
    if !endpoint_configured {
        blocking_reasons.push("collector endpoint is not configured".to_string());
    }
    if latest_validation.is_none() {
        blocking_reasons.push("collector deployment validation has not run".to_string());
    }
    if latest_validation.is_some() && !latest_validation_healthy {
        blocking_reasons.push("latest collector deployment validation was not healthy".to_string());
    }
    if latest_validation_age_hours.is_some_and(|hours| hours >= 24) {
        blocking_reasons.push("collector deployment validation evidence is stale".to_string());
    }
    if controller_required && !controller_configured {
        blocking_reasons
            .push("collector deployment controller is required but not configured".to_string());
    }
    if controller_required && latest_validation.is_some() && !latest_controller_validated {
        blocking_reasons
            .push("latest collector deployment controller execution was not validated".to_string());
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons.push("collector deployment controller evidence is stale".to_string());
    }

    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Observability collector deployment validation is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "Observability collector deployment has a recent healthy validation run".to_string()
    };

    ObservabilityCollectorDeploymentReadiness {
        status,
        production_blocked,
        otlp_enabled,
        endpoint_configured,
        controller_required,
        controller_configured,
        deployment_validated: latest_validation_healthy && !production_blocked,
        latest_validation_at,
        latest_validation_age_hours,
        latest_validation_status,
        latest_validation_healthy,
        latest_controller_status,
        latest_controller_age_hours,
        latest_controller_validated,
        controller_evidence_fresh,
        blocking_reasons,
        message,
    }
}

fn build_observability_collector_cluster_rollout_readiness(
    deployment_readiness: &ObservabilityCollectorDeploymentReadiness,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
    controller_required: bool,
    controller_configured: bool,
) -> ObservabilityCollectorClusterRolloutReadiness {
    let latest_rollout = audit_logs
        .iter()
        .filter(|log| log.action == "observability.collector_cluster_rollout_validation")
        .max_by_key(|log| log.created_at);
    let latest_rollout_at = latest_rollout.map(|log| log.created_at);
    let latest_rollout_status = latest_rollout
        .and_then(|log| log.details.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_status = latest_rollout
        .and_then(|log| log.details.get("controller_execution"))
        .and_then(|execution| execution.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_age_hours = latest_rollout
        .filter(|_| latest_controller_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let latest_controller_validated = latest_controller_status.as_deref() == Some("validated");
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let mut blocking_reasons = Vec::new();
    if !deployment_readiness.deployment_validated {
        blocking_reasons.push("collector deployment validation is not ready".to_string());
    }
    if latest_rollout.is_none() {
        blocking_reasons.push("collector cluster rollout validation has not run".to_string());
    }
    if latest_rollout_at.is_some_and(|created_at| (generated_at - created_at).num_hours() >= 24) {
        blocking_reasons.push("collector cluster rollout validation evidence is stale".to_string());
    }
    if latest_rollout_status.as_deref() != Some("validated") {
        blocking_reasons
            .push("latest collector cluster rollout validation was not validated".to_string());
    }
    if controller_required && !controller_configured {
        blocking_reasons.push(
            "collector cluster rollout controller is required but not configured".to_string(),
        );
    }
    if controller_required && controller_configured && !latest_controller_validated {
        blocking_reasons.push(
            "collector cluster rollout controller evidence is missing or not validated".to_string(),
        );
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons.push("collector cluster rollout controller evidence is stale".to_string());
    }
    let production_blocked = controller_required && !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else if blocking_reasons.is_empty() {
        "ready"
    } else {
        "optional"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Observability collector cluster rollout is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else if blocking_reasons.is_empty() && controller_required {
        "Observability collector cluster rollout has validated deployment and recent cluster-controller evidence".to_string()
    } else if blocking_reasons.is_empty() {
        "Observability collector cluster rollout has recent validation evidence".to_string()
    } else {
        format!(
            "Observability collector cluster rollout is optional until required: {}",
            blocking_reasons.join("; ")
        )
    };
    ObservabilityCollectorClusterRolloutReadiness {
        status,
        production_blocked,
        controller_required,
        controller_configured,
        latest_rollout_at,
        latest_rollout_status,
        latest_controller_status,
        latest_controller_age_hours,
        latest_controller_validated,
        controller_evidence_fresh,
        deployment_validated: deployment_readiness.deployment_validated,
        blocking_reasons,
        message,
    }
}

fn build_observability_remediation_supervision_readiness(
    required: bool,
    controller_configured: bool,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
) -> ObservabilityRemediationSupervisionReadiness {
    let latest_controller_run = audit_logs
        .iter()
        .filter(|log| {
            log.action == "observability.remediation_run"
                && log.details["controller_execution"]["attempted"] == true
        })
        .max_by_key(|log| log.created_at);
    let latest_controller_run_at = latest_controller_run.map(|log| log.created_at);
    let latest_controller_run_age_hours =
        latest_controller_run_at.map(|created_at| (generated_at - created_at).num_hours());
    let latest_controller_status = latest_controller_run
        .and_then(|log| log.details["controller_execution"]["status"].as_str())
        .map(str::to_string);
    let latest_controller_remediated = latest_controller_status
        .as_deref()
        .map(|status| status == "remediated")
        .unwrap_or(false);
    let mut blocking_reasons = Vec::new();

    if required && !controller_configured {
        blocking_reasons.push("remediation controller is required but not configured".to_string());
    }
    if required && latest_controller_run.is_none() {
        blocking_reasons
            .push("remediation controller has no audited execution evidence".to_string());
    }
    if required && latest_controller_run.is_some() && !latest_controller_remediated {
        blocking_reasons
            .push("latest remediation controller execution did not remediate".to_string());
    }
    if required && latest_controller_run_age_hours.is_some_and(|hours| hours >= 24) {
        blocking_reasons.push("remediation controller execution evidence is stale".to_string());
    }

    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else if required {
        "ready"
    } else if controller_configured {
        "configured"
    } else {
        "optional"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Observability remediation supervision is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else if required {
        "Observability remediation controller has recent audited remediation evidence".to_string()
    } else if controller_configured {
        "Observability remediation controller is configured but not required for this runtime"
            .to_string()
    } else {
        "Observability remediation controller is optional for this runtime".to_string()
    };

    ObservabilityRemediationSupervisionReadiness {
        status,
        production_blocked,
        required,
        controller_configured,
        latest_controller_run_at,
        latest_controller_run_age_hours,
        latest_controller_status,
        latest_controller_remediated,
        blocking_reasons,
        message,
    }
}

pub(crate) async fn execute_cost_alert_delivery(
    state: &AppState,
    delivered_at: DateTime<Utc>,
) -> Result<CostAlertDelivery, AppError> {
    let summary = build_usage_summary(state).await?;
    let alerts = build_cost_alerts(&summary.provider_budgets, delivered_at);
    if alerts.is_empty() {
        let delivery = CostAlertDelivery {
            status: "no_alerts".to_string(),
            delivered: false,
            channel: "webhook".to_string(),
            webhook_configured: state.cost_alert_webhook_url.is_some(),
            alerts,
            route_deliveries: vec![],
            delivered_at,
        };
        audit_cost_alert_delivery(state, &delivery).await?;
        return Ok(delivery);
    }
    let routes: Vec<_> = state
        .list_cost_alert_routes()
        .await?
        .into_iter()
        .filter(|route| route.status == "active")
        .collect();
    if !routes.is_empty() {
        let mut route_deliveries = Vec::new();
        for route in routes {
            route_deliveries
                .push(deliver_cost_alert_route(state, &route, &alerts, delivered_at).await?);
        }
        let delivered = route_deliveries.iter().any(|delivery| delivery.delivered);
        let delivery = CostAlertDelivery {
            status: if delivered { "delivered" } else { "reserved" }.to_string(),
            delivered,
            channel: "routes".to_string(),
            webhook_configured: state.cost_alert_webhook_url.is_some(),
            alerts,
            route_deliveries,
            delivered_at,
        };
        audit_cost_alert_delivery(state, &delivery).await?;
        return Ok(delivery);
    }
    let Some(webhook_url) = state.cost_alert_webhook_url.as_ref() else {
        let delivery = CostAlertDelivery {
            status: "reserved".to_string(),
            delivered: false,
            channel: "webhook".to_string(),
            webhook_configured: false,
            alerts,
            route_deliveries: vec![],
            delivered_at,
        };
        audit_cost_alert_delivery(state, &delivery).await?;
        return Ok(delivery);
    };
    let response = tokio::time::timeout(
        Duration::from_secs(10),
        reqwest::Client::new()
            .post(webhook_url)
            .json(&json!({
                "type": "mandoforge.cost_alerts",
                "alerts": alerts,
                "delivered_at": delivered_at,
            }))
            .send(),
    )
    .await??;
    if !response.status().is_success() {
        return Err(AppError::bad_request(format!(
            "cost alert webhook returned status {}",
            response.status()
        )));
    }
    let alert_count = alerts.len();
    let delivery = CostAlertDelivery {
        status: "delivered".to_string(),
        delivered: true,
        channel: "webhook".to_string(),
        webhook_configured: true,
        alerts,
        route_deliveries: vec![CostAlertRouteDelivery {
            route_id: None,
            route_name: "default-webhook".to_string(),
            channel: "webhook".to_string(),
            status: "delivered".to_string(),
            delivered: true,
            matched_alert_count: alert_count,
            target: Some(webhook_url.clone()),
        }],
        delivered_at,
    };
    audit_cost_alert_delivery(state, &delivery).await?;
    Ok(delivery)
}

async fn audit_cost_alert_delivery(
    state: &AppState,
    delivery: &CostAlertDelivery,
) -> Result<(), AppError> {
    state
        .append_audit_log(new_audit_log(
            None,
            "user",
            None,
            "usage.cost_alerts_delivered",
            "usage_alert",
            None,
            json!({
                "status": delivery.status,
                "delivered": delivery.delivered,
                "channel": delivery.channel,
                "webhook_configured": delivery.webhook_configured,
                "alert_count": delivery.alerts.len(),
                "route_delivery_count": delivery.route_deliveries.len(),
                "delivered_at": delivery.delivered_at,
            }),
        ))
        .await?;
    Ok(())
}

async fn deliver_cost_alert_route(
    state: &AppState,
    route: &CostAlertRoute,
    alerts: &[CostAlert],
    delivered_at: DateTime<Utc>,
) -> Result<CostAlertRouteDelivery, AppError> {
    let matched_alerts: Vec<_> = alerts
        .iter()
        .filter(|alert| severity_rank(&alert.severity) >= severity_rank(&route.severity_filter))
        .collect();
    if matched_alerts.is_empty() {
        return Ok(CostAlertRouteDelivery {
            route_id: Some(route.id),
            route_name: route.name.clone(),
            channel: route.channel.clone(),
            status: "no_matching_alerts".to_string(),
            delivered: false,
            matched_alert_count: 0,
            target: route.target.clone(),
        });
    }
    if route.channel == "email" && state.cost_alert_email_relay_url.is_none() {
        let Some(smtp_config) = state.cost_alert_smtp_config.as_ref() else {
            return Ok(CostAlertRouteDelivery {
                route_id: Some(route.id),
                route_name: route.name.clone(),
                channel: route.channel.clone(),
                status: "reserved".to_string(),
                delivered: false,
                matched_alert_count: matched_alerts.len(),
                target: route.target.clone(),
            });
        };
        deliver_cost_alert_email_smtp(smtp_config, route, &matched_alerts, delivered_at).await?;
        return Ok(CostAlertRouteDelivery {
            route_id: Some(route.id),
            route_name: route.name.clone(),
            channel: route.channel.clone(),
            status: "delivered".to_string(),
            delivered: true,
            matched_alert_count: matched_alerts.len(),
            target: route.target.clone(),
        });
    }
    let webhook_url = match route.channel.as_str() {
        "webhook" => route
            .target
            .as_ref()
            .or(state.cost_alert_webhook_url.as_ref())
            .ok_or_else(|| AppError::bad_request("webhook cost alert route requires a target"))?,
        "slack" => route
            .target
            .as_ref()
            .ok_or_else(|| AppError::bad_request("slack cost alert route requires a target"))?,
        "email" => {
            let Some(relay_url) = state.cost_alert_email_relay_url.as_ref() else {
                return Ok(CostAlertRouteDelivery {
                    route_id: Some(route.id),
                    route_name: route.name.clone(),
                    channel: route.channel.clone(),
                    status: "reserved".to_string(),
                    delivered: false,
                    matched_alert_count: matched_alerts.len(),
                    target: route.target.clone(),
                });
            };
            relay_url
        }
        other => {
            return Ok(CostAlertRouteDelivery {
                route_id: Some(route.id),
                route_name: route.name.clone(),
                channel: other.to_string(),
                status: "reserved".to_string(),
                delivered: false,
                matched_alert_count: matched_alerts.len(),
                target: route.target.clone(),
            });
        }
    };
    let payload = match route.channel.as_str() {
        "slack" => slack_cost_alert_payload(route, &matched_alerts, delivered_at),
        "email" => email_cost_alert_payload(route, &matched_alerts, delivered_at)?,
        _ => json!({
            "type": "mandoforge.cost_alerts",
            "route_id": route.id,
            "route_name": route.name,
            "alerts": matched_alerts,
            "delivered_at": delivered_at,
        }),
    };
    let response = tokio::time::timeout(
        Duration::from_secs(10),
        reqwest::Client::new()
            .post(webhook_url)
            .json(&payload)
            .send(),
    )
    .await??;
    if !response.status().is_success() {
        return Err(AppError::bad_request(format!(
            "cost alert route {} returned status {}",
            route.name,
            response.status()
        )));
    }
    Ok(CostAlertRouteDelivery {
        route_id: Some(route.id),
        route_name: route.name.clone(),
        channel: route.channel.clone(),
        status: "delivered".to_string(),
        delivered: true,
        matched_alert_count: matched_alerts.len(),
        target: Some(webhook_url.clone()),
    })
}

fn slack_cost_alert_payload(
    route: &CostAlertRoute,
    alerts: &[&CostAlert],
    delivered_at: DateTime<Utc>,
) -> Value {
    let title = format!(
        "MandoForge cost alert: {} matching {} route",
        alerts.len(),
        route.severity_filter
    );
    let lines: Vec<_> = alerts
        .iter()
        .map(|alert| {
            format!(
                "*{}* `{}`: {}",
                alert.severity, alert.provider_name, alert.message
            )
        })
        .collect();
    json!({
        "text": format!("{title}\n{}", lines.join("\n")),
        "blocks": [
            {
                "type": "section",
                "text": {
                    "type": "mrkdwn",
                    "text": format!("*{}*\n{}", title, lines.join("\n"))
                }
            },
            {
                "type": "context",
                "elements": [
                    {
                        "type": "mrkdwn",
                        "text": format!("route `{}` · delivered {}", route.name, delivered_at)
                    }
                ]
            }
        ]
    })
}

async fn deliver_cost_alert_email_smtp(
    config: &CostAlertSmtpConfig,
    route: &CostAlertRoute,
    alerts: &[&CostAlert],
    delivered_at: DateTime<Utc>,
) -> Result<(), AppError> {
    let email = cost_alert_email_message(config, route, alerts, delivered_at)?;
    let mut stream =
        tokio::time::timeout(Duration::from_secs(10), TcpStream::connect(&config.addr)).await??;
    smtp_expect(&mut stream, 220).await?;
    smtp_command(
        &mut stream,
        format!("EHLO {}\r\n", smtp_sanitize_header(&config.helo_domain)),
        250,
    )
    .await?;
    smtp_command(
        &mut stream,
        format!("MAIL FROM:<{}>\r\n", smtp_sanitize_addr(&config.from)?),
        250,
    )
    .await?;
    smtp_command(
        &mut stream,
        format!("RCPT TO:<{}>\r\n", smtp_sanitize_addr(&email.to)?),
        250,
    )
    .await?;
    smtp_command(&mut stream, "DATA\r\n".to_string(), 354).await?;
    tokio::time::timeout(
        Duration::from_secs(10),
        stream.write_all(email.raw.as_bytes()),
    )
    .await??;
    smtp_expect(&mut stream, 250).await?;
    let _ = smtp_command(&mut stream, "QUIT\r\n".to_string(), 221).await;
    Ok(())
}

struct CostAlertEmailMessage {
    to: String,
    raw: String,
}

fn cost_alert_email_message(
    config: &CostAlertSmtpConfig,
    route: &CostAlertRoute,
    alerts: &[&CostAlert],
    delivered_at: DateTime<Utc>,
) -> Result<CostAlertEmailMessage, AppError> {
    let (to, subject, body) = cost_alert_email_parts(route, alerts)?;
    let from = smtp_sanitize_addr(&config.from)?;
    let to_addr = smtp_sanitize_addr(&to)?;
    let subject = smtp_sanitize_header(&subject);
    let body = smtp_escape_body(&body);
    Ok(CostAlertEmailMessage {
        to,
        raw: format!(
            "From: <{from}>\r\nTo: <{to_addr}>\r\nSubject: {subject}\r\nDate: {delivered_at}\r\nContent-Type: text/plain; charset=utf-8\r\n\r\n{body}\r\n.\r\n"
        ),
    })
}

async fn smtp_command(
    stream: &mut TcpStream,
    command: String,
    expected_code: u16,
) -> Result<(), AppError> {
    tokio::time::timeout(
        Duration::from_secs(10),
        stream.write_all(command.as_bytes()),
    )
    .await??;
    smtp_expect(stream, expected_code).await
}

async fn smtp_expect(stream: &mut TcpStream, expected_code: u16) -> Result<(), AppError> {
    let mut reader = BufReader::new(stream);
    loop {
        let mut line = String::new();
        let read =
            tokio::time::timeout(Duration::from_secs(10), reader.read_line(&mut line)).await??;
        if read == 0 {
            return Err(AppError::bad_request("SMTP server closed connection"));
        }
        if line.len() < 4 {
            return Err(AppError::bad_request(format!(
                "SMTP server returned malformed response: {}",
                line.trim_end()
            )));
        }
        let code: u16 = line[0..3].parse().map_err(|_| {
            AppError::bad_request(format!(
                "SMTP server returned non-numeric response: {}",
                line.trim_end()
            ))
        })?;
        if code != expected_code {
            return Err(AppError::bad_request(format!(
                "SMTP server returned {}, expected {}: {}",
                code,
                expected_code,
                line.trim_end()
            )));
        }
        if line.as_bytes().get(3) != Some(&b'-') {
            return Ok(());
        }
    }
}

fn smtp_sanitize_addr(value: &str) -> Result<String, AppError> {
    let value = value.trim();
    if value.is_empty()
        || value.contains(['\r', '\n', '<', '>'])
        || value.contains(' ')
        || !value.contains('@')
    {
        return Err(AppError::bad_request("SMTP email address is invalid"));
    }
    Ok(value.to_string())
}

fn smtp_sanitize_header(value: &str) -> String {
    value.replace(['\r', '\n'], " ").trim().to_string()
}

fn smtp_escape_body(value: &str) -> String {
    value
        .replace("\r\n", "\n")
        .replace('\r', "\n")
        .lines()
        .map(|line| {
            if line.starts_with('.') {
                format!(".{line}")
            } else {
                line.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\r\n")
}

fn email_cost_alert_payload(
    route: &CostAlertRoute,
    alerts: &[&CostAlert],
    delivered_at: DateTime<Utc>,
) -> Result<Value, AppError> {
    let (to, subject, body) = cost_alert_email_parts(route, alerts)?;
    Ok(json!({
        "type": "mandoforge.cost_alert_email",
        "to": to,
        "subject": subject,
        "text": body,
        "route_id": route.id,
        "route_name": route.name,
        "severity_filter": route.severity_filter,
        "delivered_at": delivered_at,
    }))
}

fn cost_alert_email_parts(
    route: &CostAlertRoute,
    alerts: &[&CostAlert],
) -> Result<(String, String, String), AppError> {
    let Some(to) = route.target.as_ref() else {
        return Err(AppError::bad_request(
            "email cost alert route requires a recipient target",
        ));
    };
    let subject = format!(
        "MandoForge cost alert: {} {} alerts",
        alerts.len(),
        route.severity_filter
    );
    let body = alerts
        .iter()
        .map(|alert| {
            format!(
                "{} [{}]: {}\n{}",
                alert.provider_name,
                alert.severity,
                alert.message,
                alert.messages.join("\n")
            )
        })
        .collect::<Vec<_>>()
        .join("\n\n");
    Ok((to.clone(), subject, body))
}

fn severity_rank(severity: &str) -> i32 {
    match severity {
        "critical" => 2,
        "warning" => 1,
        _ => 0,
    }
}

pub(crate) async fn build_observability_summary(
    state: &AppState,
) -> Result<ObservabilitySummary, AppError> {
    let sessions = state.list_sessions().await?;
    let tool_calls = state.list_tool_calls(None).await?;
    let approvals = state.list_approvals().await?;
    let execution_jobs = state.execution_queue.list().await?;
    let now = Utc::now();

    let mut sessions_by_status = HashMap::new();
    let mut event_categories = HashMap::new();
    let mut recent_error_events = Vec::new();
    for session in &sessions {
        increment_count(&mut sessions_by_status, session.status.as_str());
        for event in state.list_events(session.id).await? {
            let category = event.event_type.split('.').next().unwrap_or("event");
            increment_count(&mut event_categories, category);
            if telemetry_status_for_event(&event) == "error" {
                recent_error_events.push(ObservabilityErrorEvent {
                    session_id: event.session_id,
                    event_type: event.event_type,
                    seq: event.seq,
                    status: "error".to_string(),
                    created_at: event.created_at,
                });
            }
        }
    }
    recent_error_events.sort_by(|left, right| {
        right
            .created_at
            .cmp(&left.created_at)
            .then_with(|| right.seq.cmp(&left.seq))
    });
    recent_error_events.truncate(10);

    let mut tool_calls_by_status = HashMap::new();
    let mut failed_tool_calls = 0;
    for call in &tool_calls {
        increment_count(&mut tool_calls_by_status, &call.status);
        if matches!(call.status.as_str(), "failed" | "denied") {
            failed_tool_calls += 1;
        }
    }

    let mut approvals_by_status = HashMap::new();
    let mut pending_approvals = 0;
    for approval in &approvals {
        increment_count(&mut approvals_by_status, &approval.status);
        if approval.status == "pending" {
            pending_approvals += 1;
        }
    }

    let mut execution_jobs_by_status = HashMap::new();
    let mut queued_jobs = 0;
    let mut running_jobs = 0;
    let mut failed_jobs = 0;
    let mut retryable_jobs = 0;
    let mut oldest_queued_at = None;
    for job in &execution_jobs {
        let status = execution_job_status_label(&job.status);
        increment_count(&mut execution_jobs_by_status, status);
        match job.status {
            ExecutionJobStatus::Queued => {
                queued_jobs += 1;
                oldest_queued_at = Some(match oldest_queued_at {
                    Some(oldest) if oldest <= job.enqueued_at => oldest,
                    _ => job.enqueued_at,
                });
            }
            ExecutionJobStatus::Running => running_jobs += 1,
            ExecutionJobStatus::Failed => failed_jobs += 1,
            ExecutionJobStatus::Completed | ExecutionJobStatus::Canceled => {}
        }
        if job.attempt_count > 0
            && job.attempt_count < job.max_attempts
            && job.status != ExecutionJobStatus::Completed
            && job.status != ExecutionJobStatus::Canceled
        {
            retryable_jobs += 1;
        }
    }

    let waiting_approval_sessions = sessions
        .iter()
        .filter(|session| session.status == SessionStatus::RequiresAction)
        .count();
    let failed_sessions = sessions
        .iter()
        .filter(|session| session.status == SessionStatus::Failed)
        .count();
    let oldest_queued_job_age_seconds =
        oldest_queued_at.map(|queued_at| now.signed_duration_since(queued_at).num_seconds().max(0));
    let backpressure_status = if failed_jobs > 0 || failed_sessions > 0 || failed_tool_calls > 0 {
        "error"
    } else if queued_jobs > 0 || running_jobs > 0 || pending_approvals > 0 {
        "attention"
    } else {
        "healthy"
    }
    .to_string();

    Ok(ObservabilitySummary {
        generated_at: now,
        telemetry: ObservabilityTelemetryStatus {
            service_name: state.observability_config.service_name.clone(),
            otlp_enabled: state.observability_config.is_enabled(),
            sample_ratio: state.observability_config.sample_ratio,
            endpoint_configured: state.observability_config.otlp_endpoint.is_some(),
        },
        sessions_by_status,
        tool_calls_by_status,
        approvals_by_status,
        execution_jobs_by_status,
        event_categories,
        recent_error_events,
        backpressure: ObservabilityBackpressure {
            status: backpressure_status,
            queued_jobs,
            running_jobs,
            failed_jobs,
            retryable_jobs,
            pending_approvals,
            waiting_approval_sessions,
            failed_sessions,
            failed_tool_calls,
            oldest_queued_job_age_seconds,
        },
    })
}

fn increment_count(counts: &mut HashMap<String, usize>, key: &str) {
    *counts.entry(key.to_string()).or_default() += 1;
}

fn execution_job_status_label(status: &ExecutionJobStatus) -> &'static str {
    match status {
        ExecutionJobStatus::Queued => "queued",
        ExecutionJobStatus::Running => "running",
        ExecutionJobStatus::Completed => "completed",
        ExecutionJobStatus::Failed => "failed",
        ExecutionJobStatus::Canceled => "canceled",
    }
}

pub(crate) async fn build_usage_summary(state: &AppState) -> Result<UsageSummary, AppError> {
    let sessions = state.list_sessions().await?;
    let tool_calls = state.list_tool_calls(None).await?;
    let approvals = state.list_approvals().await?;
    let providers = state.list_providers().await?;
    let provider_request_prices: HashMap<_, _> = providers
        .iter()
        .filter_map(|provider| {
            provider
                .config
                .get("pricing")
                .and_then(|pricing| pricing.get("per_request_cents"))
                .and_then(Value::as_f64)
                .map(|price| (provider.name.clone(), price))
        })
        .collect();
    let provider_prompt_token_prices: HashMap<_, _> = providers
        .iter()
        .filter_map(|provider| {
            provider
                .config
                .get("pricing")
                .and_then(|pricing| pricing.get("per_1k_prompt_tokens_cents"))
                .and_then(Value::as_f64)
                .map(|price| (provider.name.clone(), price))
        })
        .collect();
    let provider_completion_token_prices: HashMap<_, _> = providers
        .iter()
        .filter_map(|provider| {
            provider
                .config
                .get("pricing")
                .and_then(|pricing| pricing.get("per_1k_completion_tokens_cents"))
                .and_then(Value::as_f64)
                .map(|price| (provider.name.clone(), price))
        })
        .collect();

    let mut event_count = 0;
    let mut provider_request_count = 0;
    let mut provider_response_count = 0;
    let mut prompt_tokens = 0;
    let mut completion_tokens = 0;
    let mut total_tokens = 0;
    let mut by_provider = HashMap::<String, ProviderUsageSummary>::new();
    for session in &sessions {
        for event in state.list_events(session.id).await? {
            event_count += 1;
            if event.event_type == "llm.request" || event.event_type == "llm.response" {
                let provider = event
                    .payload
                    .get("provider")
                    .and_then(Value::as_str)
                    .unwrap_or("unknown")
                    .to_string();
                let usage = by_provider.entry(provider.clone()).or_default();
                if event.event_type == "llm.request" {
                    provider_request_count += 1;
                    usage.request_count += 1;
                    usage.estimated_cost_cents += provider_request_prices
                        .get(&provider)
                        .copied()
                        .unwrap_or(0.0);
                } else {
                    provider_response_count += 1;
                    usage.response_count += 1;
                    let event_prompt_tokens = event
                        .payload
                        .get("usage")
                        .and_then(|usage| usage.get("prompt_tokens"))
                        .and_then(Value::as_i64)
                        .unwrap_or(0);
                    let event_completion_tokens = event
                        .payload
                        .get("usage")
                        .and_then(|usage| usage.get("completion_tokens"))
                        .and_then(Value::as_i64)
                        .unwrap_or(0);
                    let event_total_tokens = event
                        .payload
                        .get("usage")
                        .and_then(|usage| usage.get("total_tokens"))
                        .and_then(Value::as_i64)
                        .unwrap_or(event_prompt_tokens + event_completion_tokens);
                    usage.prompt_tokens += event_prompt_tokens;
                    usage.completion_tokens += event_completion_tokens;
                    usage.total_tokens += event_total_tokens;
                    prompt_tokens += event_prompt_tokens;
                    completion_tokens += event_completion_tokens;
                    total_tokens += event_total_tokens;
                    let token_cost = token_cost_cents(
                        event_prompt_tokens,
                        provider_prompt_token_prices.get(&provider).copied(),
                    ) + token_cost_cents(
                        event_completion_tokens,
                        provider_completion_token_prices.get(&provider).copied(),
                    );
                    usage.token_cost_cents += token_cost;
                    usage.estimated_cost_cents += token_cost;
                }
            }
        }
    }

    let mut by_tool = HashMap::<String, ToolUsageSummary>::new();
    let mut total_tool_duration_ms = 0;
    let mut tool_success_count = 0;
    let mut tool_failed_count = 0;
    for call in &tool_calls {
        let tool = by_tool.entry(call.tool_name.clone()).or_default();
        tool.call_count += 1;
        if call.status == "completed" {
            tool.success_count += 1;
            tool_success_count += 1;
        }
        if matches!(call.status.as_str(), "failed" | "denied") {
            tool.failed_count += 1;
            tool_failed_count += 1;
        }
        if let (Some(started_at), Some(completed_at)) = (call.started_at, call.completed_at) {
            let duration = completed_at
                .signed_duration_since(started_at)
                .num_milliseconds()
                .max(0);
            tool.total_duration_ms += duration;
            total_tool_duration_ms += duration;
        }
    }

    let mut estimated_provider_cost_cents: f64 = by_provider
        .values()
        .map(|usage| usage.estimated_cost_cents)
        .sum();
    if estimated_provider_cost_cents == 0.0 {
        estimated_provider_cost_cents = 0.0;
    }
    let provider_budgets = build_provider_budget_statuses(state, &providers).await?;
    Ok(UsageSummary {
        session_count: sessions.len(),
        event_count,
        provider_request_count,
        provider_response_count,
        tool_call_count: tool_calls.len(),
        tool_success_count,
        tool_failed_count,
        approval_count: approvals.len(),
        prompt_tokens,
        completion_tokens,
        total_tokens,
        total_tool_duration_ms,
        estimated_provider_cost_cents,
        by_provider,
        by_tool,
        provider_budgets,
    })
}

pub(crate) async fn build_usage_trend_summary(
    state: &AppState,
) -> Result<UsageTrendSummary, AppError> {
    let generated_at = Utc::now();
    let current = build_usage_summary(state).await?;
    let rollups = state.list_usage_rollups().await?;
    Ok(build_usage_trend_from_parts(
        current,
        &rollups,
        generated_at,
    ))
}

fn build_usage_trend_from_parts(
    current: UsageSummary,
    rollups: &[UsageRollup],
    generated_at: DateTime<Utc>,
) -> UsageTrendSummary {
    let current_period = UsageTrendPeriod {
        period_start: generated_at - chrono::Duration::hours(24),
        period_end: generated_at,
        cost_cents: current.estimated_provider_cost_cents,
        total_tokens: current.total_tokens,
        tool_calls: current.tool_call_count as i64,
    };
    let (comparison_basis, latest_period, previous_period) = match rollups {
        [latest, previous, ..] => (
            "latest_rollups".to_string(),
            Some(usage_rollup_trend_period(latest)),
            Some(usage_rollup_trend_period(previous)),
        ),
        [previous] => (
            "current_vs_latest_rollup".to_string(),
            Some(current_period.clone()),
            Some(usage_rollup_trend_period(previous)),
        ),
        [] => (
            "current_only".to_string(),
            Some(current_period.clone()),
            None,
        ),
    };
    let cost_delta_cents = latest_period
        .as_ref()
        .zip(previous_period.as_ref())
        .map(|(latest, previous)| latest.cost_cents - previous.cost_cents);
    let cost_delta_percent = latest_period
        .as_ref()
        .zip(previous_period.as_ref())
        .and_then(|(latest, previous)| percent_delta(latest.cost_cents, previous.cost_cents));
    let token_delta = latest_period
        .as_ref()
        .zip(previous_period.as_ref())
        .map(|(latest, previous)| latest.total_tokens - previous.total_tokens);
    let token_delta_percent = latest_period
        .as_ref()
        .zip(previous_period.as_ref())
        .and_then(|(latest, previous)| {
            percent_delta(latest.total_tokens as f64, previous.total_tokens as f64)
        });
    let tool_call_delta = latest_period
        .as_ref()
        .zip(previous_period.as_ref())
        .map(|(latest, previous)| latest.tool_calls - previous.tool_calls);
    let tool_call_delta_percent = latest_period
        .as_ref()
        .zip(previous_period.as_ref())
        .and_then(|(latest, previous)| {
            percent_delta(latest.tool_calls as f64, previous.tool_calls as f64)
        });
    let top_provider_by_cost = current
        .by_provider
        .iter()
        .max_by(|left, right| {
            left.1
                .estimated_cost_cents
                .total_cmp(&right.1.estimated_cost_cents)
        })
        .map(|(provider_name, usage)| UsageTrendProvider {
            provider_name: provider_name.clone(),
            estimated_cost_cents: usage.estimated_cost_cents,
            total_tokens: usage.total_tokens,
            request_count: usage.request_count,
        });
    let budget_pressure = build_usage_budget_pressure(&current.provider_budgets);
    let mut recommendations = Vec::new();
    if budget_pressure.critical_count > 0 {
        recommendations.push("critical_provider_budget_review".to_string());
    } else if budget_pressure.warning_count > 0 {
        recommendations.push("provider_budget_watch".to_string());
    }
    if cost_delta_percent.is_some_and(|percent| percent >= 25.0) {
        recommendations.push("cost_growth_investigation".to_string());
    }
    if rollups.is_empty() {
        recommendations.push("create_daily_usage_rollup".to_string());
    }
    let forecast = build_usage_forecast(&current, &current_period, generated_at);

    UsageTrendSummary {
        generated_at,
        rollup_count: rollups.len(),
        comparison_basis,
        current_cost_cents: current_period.cost_cents,
        current_total_tokens: current_period.total_tokens,
        current_tool_calls: current_period.tool_calls,
        latest_period,
        previous_period,
        cost_delta_cents,
        cost_delta_percent,
        token_delta,
        token_delta_percent,
        tool_call_delta,
        tool_call_delta_percent,
        top_provider_by_cost,
        budget_pressure,
        forecast,
        recommendations,
    }
}

fn build_usage_forecast(
    current: &UsageSummary,
    current_period: &UsageTrendPeriod,
    generated_at: DateTime<Utc>,
) -> UsageForecastSummary {
    let horizons = [7_i64, 30_i64]
        .into_iter()
        .map(|days| UsageForecastHorizon {
            days,
            projected_cost_cents: current_period.cost_cents * days as f64,
            projected_tokens: current_period.total_tokens.saturating_mul(days),
            projected_tool_calls: current_period.tool_calls.saturating_mul(days),
        })
        .collect();
    let mut provider_budget_exhaustion: Vec<_> = current
        .provider_budgets
        .iter()
        .filter_map(|budget| {
            let daily_cost_limit_cents = budget.daily_cost_limit_cents?;
            let current_daily_cost_cents = if budget.projected_daily_cost_cents > 0.0 {
                budget.projected_daily_cost_cents
            } else {
                budget.estimated_cost_cents
            };
            let projected_days_to_limit = if current_daily_cost_cents <= 0.0 {
                None
            } else {
                Some(
                    ((daily_cost_limit_cents - budget.estimated_cost_cents).max(0.0))
                        / current_daily_cost_cents,
                )
            };
            let projected_exhaustion_at = projected_days_to_limit.map(|days| {
                generated_at + chrono::Duration::seconds((days * 86_400.0).round() as i64)
            });
            Some(ProviderBudgetExhaustionForecast {
                provider_name: budget.provider_name.clone(),
                status: budget.status.clone(),
                current_daily_cost_cents,
                daily_cost_limit_cents,
                projected_days_to_limit,
                projected_exhaustion_at,
            })
        })
        .collect();
    provider_budget_exhaustion.sort_by(|left, right| {
        match (left.projected_days_to_limit, right.projected_days_to_limit) {
            (Some(left_days), Some(right_days)) => left_days.total_cmp(&right_days),
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (None, None) => left.provider_name.cmp(&right.provider_name),
        }
    });
    UsageForecastSummary {
        basis: "current_24h_run_rate".to_string(),
        horizons,
        provider_budget_exhaustion,
    }
}

fn usage_rollup_trend_period(rollup: &UsageRollup) -> UsageTrendPeriod {
    UsageTrendPeriod {
        period_start: rollup.period_start,
        period_end: rollup.period_end,
        cost_cents: json_f64(&rollup.summary, "estimated_provider_cost_cents"),
        total_tokens: json_i64(&rollup.summary, "total_tokens"),
        tool_calls: json_i64(&rollup.summary, "tool_call_count"),
    }
}

fn build_usage_budget_pressure(budgets: &[ProviderBudgetStatus]) -> UsageBudgetPressure {
    let critical_count = budgets
        .iter()
        .filter(|budget| budget.status == "critical")
        .count();
    let warning_count = budgets
        .iter()
        .filter(|budget| budget.status == "warning")
        .count();
    let highest_status = if critical_count > 0 {
        "critical"
    } else if warning_count > 0 {
        "warning"
    } else {
        "ok"
    }
    .to_string();
    let highest_used_percent = budgets
        .iter()
        .flat_map(|budget| {
            [
                budget.request_budget_used_percent,
                budget.cost_budget_used_percent,
            ]
        })
        .flatten()
        .max_by(f64::total_cmp);
    UsageBudgetPressure {
        total_budgeted_providers: budgets.len(),
        pressure_count: critical_count + warning_count,
        warning_count,
        critical_count,
        highest_status,
        highest_used_percent,
    }
}

fn json_f64(value: &Value, key: &str) -> f64 {
    value.get(key).and_then(Value::as_f64).unwrap_or_default()
}

fn json_i64(value: &Value, key: &str) -> i64 {
    value
        .get(key)
        .and_then(|value| {
            value
                .as_i64()
                .or_else(|| value.as_u64().map(|value| value as i64))
        })
        .unwrap_or_default()
}

fn percent_delta(current: f64, previous: f64) -> Option<f64> {
    if previous.abs() < f64::EPSILON {
        return None;
    }
    Some(((current - previous) / previous) * 100.0)
}

pub(crate) fn build_usage_finance_csv(summary: &UsageSummary, trend: &UsageTrendSummary) -> String {
    let mut csv = String::new();
    push_csv_row(
        &mut csv,
        vec![
            "section".to_string(),
            "name".to_string(),
            "status".to_string(),
            "requests".to_string(),
            "responses".to_string(),
            "tokens".to_string(),
            "tool_calls".to_string(),
            "cost_cents".to_string(),
            "percent".to_string(),
            "notes".to_string(),
        ],
    );
    push_csv_row(
        &mut csv,
        vec![
            "summary".to_string(),
            "current_24h".to_string(),
            "current".to_string(),
            summary.provider_request_count.to_string(),
            summary.provider_response_count.to_string(),
            summary.total_tokens.to_string(),
            summary.tool_call_count.to_string(),
            format_csv_float(summary.estimated_provider_cost_cents),
            optional_csv_float(trend.budget_pressure.highest_used_percent),
            format!(
                "sessions={};events={};approvals={}",
                summary.session_count, summary.event_count, summary.approval_count
            ),
        ],
    );
    if let Some(latest) = &trend.latest_period {
        push_usage_trend_period_csv_row(&mut csv, "trend", "latest", latest);
    }
    if let Some(previous) = &trend.previous_period {
        push_usage_trend_period_csv_row(&mut csv, "trend", "previous", previous);
    }
    push_csv_row(
        &mut csv,
        vec![
            "trend".to_string(),
            "delta".to_string(),
            trend.comparison_basis.clone(),
            String::new(),
            String::new(),
            trend
                .token_delta
                .map(|value| value.to_string())
                .unwrap_or_default(),
            trend
                .tool_call_delta
                .map(|value| value.to_string())
                .unwrap_or_default(),
            optional_csv_float(trend.cost_delta_cents),
            optional_csv_float(trend.cost_delta_percent),
            "percent_column_contains_cost_delta_percent_for_delta_row".to_string(),
        ],
    );

    let mut provider_entries: Vec<_> = summary.by_provider.iter().collect();
    provider_entries.sort_by(|left, right| {
        right
            .1
            .estimated_cost_cents
            .total_cmp(&left.1.estimated_cost_cents)
            .then_with(|| left.0.cmp(right.0))
    });
    for (provider_name, usage) in provider_entries {
        push_csv_row(
            &mut csv,
            vec![
                "provider".to_string(),
                provider_name.clone(),
                "usage".to_string(),
                usage.request_count.to_string(),
                usage.response_count.to_string(),
                usage.total_tokens.to_string(),
                String::new(),
                format_csv_float(usage.estimated_cost_cents),
                String::new(),
                format!(
                    "prompt_tokens={};completion_tokens={};token_cost_cents={}",
                    usage.prompt_tokens,
                    usage.completion_tokens,
                    format_csv_float(usage.token_cost_cents)
                ),
            ],
        );
    }
    for horizon in &trend.forecast.horizons {
        push_csv_row(
            &mut csv,
            vec![
                "forecast".to_string(),
                format!("{}d", horizon.days),
                trend.forecast.basis.clone(),
                String::new(),
                String::new(),
                horizon.projected_tokens.to_string(),
                horizon.projected_tool_calls.to_string(),
                format_csv_float(horizon.projected_cost_cents),
                String::new(),
                "projected_from_current_24h_run_rate".to_string(),
            ],
        );
    }
    for budget in &summary.provider_budgets {
        push_csv_row(
            &mut csv,
            vec![
                "budget".to_string(),
                budget.provider_name.clone(),
                budget.status.clone(),
                budget.request_count.to_string(),
                String::new(),
                String::new(),
                String::new(),
                format_csv_float(budget.estimated_cost_cents),
                optional_csv_float(budget_peak_percent(budget)),
                budget.messages.join(" | "),
            ],
        );
    }
    for forecast in &trend.forecast.provider_budget_exhaustion {
        push_csv_row(
            &mut csv,
            vec![
                "budget_forecast".to_string(),
                forecast.provider_name.clone(),
                forecast.status.clone(),
                String::new(),
                String::new(),
                String::new(),
                String::new(),
                format_csv_float(forecast.current_daily_cost_cents),
                optional_csv_float(forecast.projected_days_to_limit),
                format!(
                    "daily_limit_cents={};projected_exhaustion_at={}",
                    format_csv_float(forecast.daily_cost_limit_cents),
                    forecast
                        .projected_exhaustion_at
                        .map(|value| value.to_rfc3339())
                        .unwrap_or_else(|| "unknown".to_string())
                ),
            ],
        );
    }
    for recommendation in &trend.recommendations {
        push_csv_row(
            &mut csv,
            vec![
                "recommendation".to_string(),
                recommendation.clone(),
                "open".to_string(),
                String::new(),
                String::new(),
                String::new(),
                String::new(),
                String::new(),
                String::new(),
                "operator_action".to_string(),
            ],
        );
    }
    csv
}

fn push_usage_trend_period_csv_row(
    csv: &mut String,
    section: &str,
    name: &str,
    period: &UsageTrendPeriod,
) {
    push_csv_row(
        csv,
        vec![
            section.to_string(),
            name.to_string(),
            "window".to_string(),
            String::new(),
            String::new(),
            period.total_tokens.to_string(),
            period.tool_calls.to_string(),
            format_csv_float(period.cost_cents),
            String::new(),
            format!("{} to {}", period.period_start, period.period_end),
        ],
    );
}

fn budget_peak_percent(budget: &ProviderBudgetStatus) -> Option<f64> {
    [
        budget.request_budget_used_percent,
        budget.cost_budget_used_percent,
    ]
    .into_iter()
    .flatten()
    .max_by(f64::total_cmp)
}

fn format_csv_float(value: f64) -> String {
    format!("{value:.6}")
}

fn optional_csv_float(value: Option<f64>) -> String {
    value.map(format_csv_float).unwrap_or_default()
}

fn push_csv_row(csv: &mut String, cells: Vec<String>) {
    let row = cells
        .into_iter()
        .map(csv_escape_cell)
        .collect::<Vec<_>>()
        .join(",");
    csv.push_str(&row);
    csv.push('\n');
}

fn csv_escape_cell(cell: String) -> String {
    if cell.contains([',', '"', '\n', '\r']) {
        format!("\"{}\"", cell.replace('"', "\"\""))
    } else {
        cell
    }
}

async fn build_provider_budget_statuses(
    state: &AppState,
    providers: &[ProviderRecord],
) -> Result<Vec<ProviderBudgetStatus>, AppError> {
    let since = Utc::now() - chrono::Duration::hours(24);
    let mut statuses = Vec::new();
    for provider in providers {
        let daily_request_limit = provider_daily_request_limit(provider);
        let daily_cost_limit_cents = provider_daily_cost_limit_cents(provider);
        if daily_request_limit.is_none() && daily_cost_limit_cents.is_none() {
            continue;
        }
        let request_count = state
            .provider_request_count_since(&provider.name, since)
            .await?;
        let estimated_cost_cents =
            provider_estimated_cost_cents_since(state, provider, since).await?;
        let request_budget_used_percent =
            daily_request_limit.map(|limit| percent_used(request_count as f64, limit as f64));
        let cost_budget_used_percent =
            daily_cost_limit_cents.map(|limit| percent_used(estimated_cost_cents, limit));
        let max_used_percent = request_budget_used_percent
            .into_iter()
            .chain(cost_budget_used_percent)
            .fold(0.0, f64::max);
        let status = if max_used_percent >= 100.0 {
            "critical"
        } else if max_used_percent >= 80.0 {
            "warning"
        } else {
            "ok"
        }
        .to_string();
        let mut messages = Vec::new();
        if let (Some(limit), Some(percent)) = (daily_request_limit, request_budget_used_percent) {
            messages.push(format!(
                "{request_count} of {limit} daily requests used ({percent:.1}%)"
            ));
        }
        if let (Some(limit), Some(percent)) = (daily_cost_limit_cents, cost_budget_used_percent) {
            messages.push(format!(
                "{estimated_cost_cents:.2} of {limit:.2} daily cost cents used ({percent:.1}%)"
            ));
        }
        statuses.push(ProviderBudgetStatus {
            provider_name: provider.name.clone(),
            status,
            window_hours: 24,
            request_count,
            daily_request_limit,
            request_budget_used_percent,
            estimated_cost_cents,
            projected_daily_cost_cents: estimated_cost_cents,
            daily_cost_limit_cents,
            cost_budget_used_percent,
            messages,
        });
    }
    statuses.sort_by(|left, right| {
        budget_rank(&right.status)
            .cmp(&budget_rank(&left.status))
            .then_with(|| {
                right
                    .projected_daily_cost_cents
                    .total_cmp(&left.projected_daily_cost_cents)
            })
            .then_with(|| left.provider_name.cmp(&right.provider_name))
    });
    Ok(statuses)
}

fn percent_used(used: f64, limit: f64) -> f64 {
    if limit <= 0.0 {
        if used > 0.0 { 100.0 } else { 0.0 }
    } else {
        (used / limit) * 100.0
    }
}

pub(crate) fn build_cost_alerts(
    budgets: &[ProviderBudgetStatus],
    created_at: DateTime<Utc>,
) -> Vec<CostAlert> {
    budgets
        .iter()
        .filter(|budget| budget_rank(&budget.status) >= budget_rank("warning"))
        .map(|budget| CostAlert {
            provider_name: budget.provider_name.clone(),
            severity: budget.status.clone(),
            message: format!(
                "provider {} budget status is {}",
                budget.provider_name, budget.status
            ),
            messages: budget.messages.clone(),
            window_hours: budget.window_hours,
            request_budget_used_percent: budget.request_budget_used_percent,
            cost_budget_used_percent: budget.cost_budget_used_percent,
            estimated_cost_cents: budget.estimated_cost_cents,
            created_at,
        })
        .collect()
}

fn budget_rank(status: &str) -> i32 {
    match status {
        "critical" => 3,
        "warning" => 2,
        _ => 1,
    }
}

fn token_cost_cents(tokens: i64, price_per_1k_cents: Option<f64>) -> f64 {
    let Some(price) = price_per_1k_cents else {
        return 0.0;
    };
    (tokens.max(0) as f64 / 1000.0) * price
}

fn approval_expires_at(
    created_at: DateTime<Utc>,
    expires_in_seconds: Option<&Value>,
) -> Option<DateTime<Utc>> {
    let seconds = expires_in_seconds
        .and_then(Value::as_i64)
        .filter(|seconds| *seconds > 0)
        .unwrap_or(86_400);
    Some(created_at + chrono::Duration::seconds(seconds))
}

pub(crate) fn validate_approval_group_input(
    mut input: CreateApprovalGroup,
) -> Result<CreateApprovalGroup, AppError> {
    input.name = input.name.trim().to_string();
    if input.name.is_empty() {
        return Err(AppError::bad_request("approval group name is required"));
    }
    input.subjects = input
        .subjects
        .into_iter()
        .map(|subject| subject.trim().to_string())
        .filter(|subject| !subject.is_empty())
        .collect();
    input.subjects.sort();
    input.subjects.dedup();
    if input.subjects.is_empty() {
        return Err(AppError::bad_request(
            "approval group requires at least one subject",
        ));
    }
    Ok(input)
}

pub(crate) fn validate_approval_escalation_rule_input(
    mut input: CreateApprovalEscalationRule,
) -> Result<CreateApprovalEscalationRule, AppError> {
    input.name = input.name.trim().to_string();
    input.risk_level = input.risk_level.trim().to_string();
    if input.name.is_empty() {
        return Err(AppError::bad_request(
            "approval escalation rule name is required",
        ));
    }
    if input.risk_level.is_empty() {
        return Err(AppError::bad_request(
            "approval escalation rule risk_level is required",
        ));
    }
    input.order_index = input.order_index.max(0);
    input.after_seconds = input.after_seconds.max(0);
    Ok(input)
}

fn default_approval_notification_risk_filter() -> String {
    "all".to_string()
}

fn default_approval_notification_max_attempts() -> i32 {
    1
}

pub(crate) fn validate_approval_notification_channel_policy_input(
    mut input: CreateApprovalNotificationChannelPolicy,
) -> Result<CreateApprovalNotificationChannelPolicy, AppError> {
    input.name = input.name.trim().to_string();
    input.channel = input.channel.trim().to_string();
    input.target_env = input.target_env.and_then(|target_env| {
        let trimmed = target_env.trim();
        (!trimmed.is_empty()).then(|| trimmed.to_string())
    });
    input.risk_filter = input.risk_filter.trim().to_string();
    if input.name.is_empty() {
        return Err(AppError::bad_request(
            "approval notification channel policy name is required",
        ));
    }
    if !matches!(input.channel.as_str(), "webhook" | "slack" | "email_relay") {
        return Err(AppError::bad_request(
            "approval notification channel policy channel must be webhook, slack, or email_relay",
        ));
    }
    if !matches!(
        input.risk_filter.as_str(),
        "all" | "low" | "medium" | "high" | "critical"
    ) {
        return Err(AppError::bad_request(
            "approval notification channel policy risk_filter must be all, low, medium, high, or critical",
        ));
    }
    input.max_attempts = input.max_attempts.clamp(1, 5);
    input.backoff_seconds = input.backoff_seconds.clamp(0, 60);
    Ok(input)
}

pub(crate) fn validate_cost_alert_route_input(
    mut input: CreateCostAlertRoute,
) -> Result<CreateCostAlertRoute, AppError> {
    input.name = input.name.trim().to_string();
    input.channel = input.channel.trim().to_string();
    input.target = input.target.and_then(|target| {
        let trimmed = target.trim();
        (!trimmed.is_empty()).then(|| trimmed.to_string())
    });
    input.severity_filter = input.severity_filter.trim().to_string();
    if input.name.is_empty() {
        return Err(AppError::bad_request("cost alert route name is required"));
    }
    if !matches!(input.channel.as_str(), "webhook" | "slack" | "email") {
        return Err(AppError::bad_request(
            "cost alert route channel must be webhook, slack, or email",
        ));
    }
    if !matches!(input.severity_filter.as_str(), "warning" | "critical") {
        return Err(AppError::bad_request(
            "cost alert route severity_filter must be warning or critical",
        ));
    }
    Ok(input)
}

pub(crate) fn required_trimmed(value: &str, field_name: &str) -> Result<String, AppError> {
    let value = value.trim();
    if value.is_empty() {
        return Err(AppError::bad_request(format!("{field_name} is required")));
    }
    Ok(value.to_string())
}

pub(crate) fn optional_trimmed(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn merge_approval_evidence(target: &mut Value, patch: Value) {
    if !target.is_object() {
        *target = json!({"details": target.clone()});
    }
    let Some(target_map) = target.as_object_mut() else {
        return;
    };
    if let Value::Object(patch_map) = patch {
        for (key, value) in patch_map {
            target_map.insert(key, value);
        }
    }
}

pub(crate) async fn execute_due_approval_escalations(
    state: &AppState,
) -> Result<ApprovalEscalationDueRun, AppError> {
    let checked_at = Utc::now();
    let mut expired_count = 0;
    let mut escalated_count = 0;
    let mut skipped_count = 0;
    let mut notification_deliveries = Vec::new();
    let rules = state.list_approval_escalation_rules().await?;
    for approval in state
        .list_approvals()
        .await?
        .into_iter()
        .filter(|approval| approval.status == "pending")
    {
        if approval_is_expired_at(&approval, checked_at) {
            expire_approval_record(state, approval.id).await?;
            expired_count += 1;
            continue;
        }
        let Some(rule) = next_due_escalation_rule(&approval, &rules, checked_at) else {
            skipped_count += 1;
            continue;
        };
        let group = state.get_approval_group(rule.group_id).await?;
        if group.status != "active" {
            skipped_count += 1;
            continue;
        }
        let updated = escalate_approval_record(
            state,
            &approval,
            &group,
            Some(rule.id),
            format!("Scheduled escalation after {} seconds", rule.after_seconds),
            "system".to_string(),
            "system",
            None,
        )
        .await?;
        escalated_count += 1;
        notification_deliveries
            .push(deliver_approval_notification(state, &updated, checked_at).await?);
    }
    let run = ApprovalEscalationDueRun {
        status: "completed".to_string(),
        checked_at,
        expired_count,
        escalated_count,
        skipped_count,
        notification_deliveries,
    };
    state
        .append_audit_log(new_audit_log(
            None,
            "system",
            None,
            "approval.escalation_due_run",
            "approval_escalation_rules",
            None,
            serde_json::to_value(&run)?,
        ))
        .await?;
    Ok(run)
}

pub(crate) async fn escalate_approval_record(
    state: &AppState,
    approval: &Approval,
    group: &ApprovalGroup,
    rule_id: Option<Uuid>,
    reason: String,
    escalated_by: String,
    actor_type: &str,
    actor_id: Option<Uuid>,
) -> Result<Approval, AppError> {
    let escalated_at = Utc::now();
    let mut evidence = approval.evidence.clone();
    merge_approval_evidence(
        &mut evidence,
        json!({
            "approver_group_id": group.id,
            "approver_group_name": group.name,
            "escalation": {
                "rule_id": rule_id,
                "group_id": group.id,
                "reason": reason,
                "escalated_by": escalated_by,
                "escalated_at": escalated_at
            }
        }),
    );
    let updated = state
        .update_approval_evidence(approval.id, evidence)
        .await?;
    state
        .append_event(
            actor_type,
            actor_id,
            updated.session_id,
            "approval.escalated",
            json!({
                "approval_id": approval.id,
                "group_id": group.id,
                "group_name": group.name,
                "rule_id": rule_id,
                "escalated_at": escalated_at
            }),
        )
        .await?;
    state
        .append_audit_log(new_audit_log(
            Some(updated.session_id),
            actor_type,
            actor_id,
            "approval.escalated",
            "approval",
            Some(approval.id),
            json!({
                "group_id": group.id,
                "group_name": group.name,
                "rule_id": rule_id,
                "subject_count": group.subjects.len()
            }),
        ))
        .await?;
    Ok(updated)
}

pub(crate) async fn execute_approval_notification_delivery_run(
    state: &AppState,
    subject: Option<String>,
    ran_at: DateTime<Utc>,
    max_deliveries: usize,
) -> Result<ApprovalNotificationDeliveryRun, AppError> {
    let approvals = state.list_approvals().await?;
    let audit_logs = state.list_audit_logs(None).await?;
    let recently_notified = recently_notified_approval_ids(&audit_logs, ran_at);
    let candidates = approvals
        .into_iter()
        .filter(|approval| approval.status == "pending")
        .collect::<Vec<_>>();
    let candidate_count = candidates.len();
    let mut deliveries = Vec::new();
    let mut failures = Vec::new();
    let mut delivered_count = 0usize;
    let mut reserved_count = 0usize;
    let mut skipped_count = candidate_count.saturating_sub(max_deliveries);

    for approval in candidates.into_iter().take(max_deliveries) {
        if approval_is_expired_at(&approval, ran_at) {
            expire_approval_record(state, approval.id).await?;
            skipped_count += 1;
            continue;
        }
        if recently_notified.contains(&approval.id) {
            skipped_count += 1;
            continue;
        }
        match deliver_approval_notification(state, &approval, ran_at).await {
            Ok(delivery) => {
                if delivery.delivered {
                    delivered_count += 1;
                } else {
                    reserved_count += 1;
                }
                deliveries.push(delivery);
            }
            Err(error) => failures.push(ApprovalNotificationDeliveryFailure {
                approval_id: approval.id,
                error: error.message,
            }),
        }
    }
    let failed_count = failures.len();
    let status = if failed_count > 0 && delivered_count > 0 {
        "partial_failure"
    } else if failed_count > 0 {
        "failed"
    } else if delivered_count > 0 {
        "delivered"
    } else if reserved_count > 0 {
        "reserved"
    } else {
        "no_pending"
    }
    .to_string();
    let run = ApprovalNotificationDeliveryRun {
        status,
        subject,
        candidate_count,
        delivered_count,
        reserved_count,
        failed_count,
        skipped_count,
        deliveries,
        failures,
        ran_at,
    };
    state
        .append_audit_log(new_audit_log(
            None,
            "user",
            None,
            "approval.notification_delivery_run",
            "approval_notifications",
            None,
            serde_json::to_value(&run)?,
        ))
        .await?;
    Ok(run)
}

fn recently_notified_approval_ids(audit_logs: &[AuditLog], now: DateTime<Utc>) -> HashSet<Uuid> {
    let cutoff = now - chrono::Duration::hours(24);
    audit_logs
        .iter()
        .filter(|log| log.action == "approval.notification_delivered" && log.created_at >= cutoff)
        .filter_map(|log| log.resource_id)
        .collect()
}

pub(crate) fn build_approval_notification_delivery_run_summary(
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
    routing: &ApprovalNotificationRoutingSummary,
) -> ApprovalNotificationDeliveryRunSummary {
    let mut recent_runs: Vec<_> = audit_logs
        .iter()
        .filter_map(approval_notification_delivery_run_from_audit_log)
        .collect();
    recent_runs.sort_by(|left, right| right.ran_at.cmp(&left.ran_at));
    let run_count = recent_runs.len();
    let delivered_run_count = recent_runs
        .iter()
        .filter(|run| run.delivered_count > 0 && run.failed_count == 0)
        .count();
    let reserved_run_count = recent_runs
        .iter()
        .filter(|run| run.status == "reserved")
        .count();
    let failed_run_count = recent_runs
        .iter()
        .filter(|run| run.failed_count > 0 || run.status == "failed")
        .count();
    let latest_run = recent_runs.first().cloned();
    let mut attention_items = Vec::new();
    match latest_run.as_ref() {
        Some(run) if run.failed_count > 0 => {
            attention_items.push(ApprovalNotificationDeliveryRunAttentionItem {
                kind: "latest_delivery_failed".to_string(),
                severity: "critical".to_string(),
                message: format!(
                    "latest approval notification run failed for {} approval(s)",
                    run.failed_count
                ),
            });
        }
        Some(run) if run.status == "reserved" => {
            attention_items.push(ApprovalNotificationDeliveryRunAttentionItem {
                kind: "latest_delivery_reserved".to_string(),
                severity: "warning".to_string(),
                message:
                    "latest approval notification run found pending approvals but no delivery channel or target was ready".to_string(),
            });
        }
        Some(run) if (generated_at - run.ran_at).num_hours() >= 24 => {
            attention_items.push(ApprovalNotificationDeliveryRunAttentionItem {
                kind: "stale_delivery_run".to_string(),
                severity: "warning".to_string(),
                message: "approval notifications have not been run in the last 24 hours"
                    .to_string(),
            });
        }
        None => {
            attention_items.push(ApprovalNotificationDeliveryRunAttentionItem {
                kind: "missing_delivery_run".to_string(),
                severity: "warning".to_string(),
                message: "approval notification delivery has not been run yet".to_string(),
            });
        }
        _ => {}
    }
    let production_ops = build_approval_notification_production_ops_readiness(
        latest_run.as_ref(),
        routing,
        audit_logs,
        generated_at,
        approval_notification_ops_controller_required(&|key| std::env::var(key).ok()),
        approval_notification_ops_controller_configured(&|key| std::env::var(key).ok()),
    );
    if production_ops.production_blocked {
        attention_items.push(ApprovalNotificationDeliveryRunAttentionItem {
            kind: "approval_notification_production_blocked".to_string(),
            severity: if production_ops.status == "blocked" {
                "critical".to_string()
            } else {
                "warning".to_string()
            },
            message: production_ops.message.clone(),
        });
    }
    let lookup = |key: &str| std::env::var(key).ok();
    let deployment_readiness = build_approval_notification_deployment_readiness(
        audit_logs,
        routing,
        generated_at,
        approval_notification_deployment_controller_required(&lookup),
        approval_notification_deployment_controller_configured(&lookup),
    );
    if deployment_readiness.production_blocked {
        attention_items.push(ApprovalNotificationDeliveryRunAttentionItem {
            kind: "approval_notification_deployment_validation_blocked".to_string(),
            severity: if deployment_readiness.status == "blocked" {
                "critical".to_string()
            } else {
                "warning".to_string()
            },
            message: deployment_readiness.message.clone(),
        });
    }
    recent_runs.truncate(10);
    ApprovalNotificationDeliveryRunSummary {
        generated_at,
        run_count,
        delivered_run_count,
        reserved_run_count,
        failed_run_count,
        latest_run,
        recent_runs,
        production_ops,
        deployment_readiness,
        attention_items,
    }
}

fn build_approval_notification_production_ops_readiness(
    latest_run: Option<&ApprovalNotificationDeliveryRunRecord>,
    routing: &ApprovalNotificationRoutingSummary,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
    controller_required: bool,
    controller_configured: bool,
) -> ApprovalNotificationProductionOpsReadiness {
    let latest_run_age_hours = latest_run.map(|run| (generated_at - run.ran_at).num_hours());
    let latest_run_status = latest_run.map(|run| run.status.clone());
    let latest_controller_log = audit_logs
        .iter()
        .filter(|log| log.action == "approval.notification_ops_validation_run")
        .max_by_key(|log| log.created_at);
    let latest_controller_status = latest_controller_log
        .and_then(|log| {
            log.details["controller_execution"]["status"]
                .as_str()
                .or_else(|| log.details["status"].as_str())
        })
        .map(str::to_string);
    let latest_controller_age_hours =
        latest_controller_log.map(|log| (generated_at - log.created_at).num_hours());
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_controller_validated = latest_controller_status.as_deref() == Some("validated");
    let mut blocking_reasons = Vec::new();
    if routing.channel_count == 0 {
        blocking_reasons.push("no delivery channel is configured".to_string());
    }
    if routing.unroutable_pending_count > 0 {
        blocking_reasons.push("pending approvals are unroutable".to_string());
    }
    match latest_run {
        None => blocking_reasons.push("delivery run has not been recorded".to_string()),
        Some(run) if run.failed_count > 0 || run.status == "failed" => {
            blocking_reasons.push("latest delivery run failed".to_string());
        }
        Some(run) if run.status == "reserved" => {
            blocking_reasons.push("latest delivery run was reserved".to_string());
        }
        Some(run) if (generated_at - run.ran_at).num_hours() >= 24 => {
            blocking_reasons.push("latest delivery run is stale".to_string());
        }
        Some(_) => {}
    }
    if controller_required && !controller_configured {
        blocking_reasons.push(
            "approval notification ops controller is required but not configured".to_string(),
        );
    }
    if controller_required && !latest_controller_validated {
        blocking_reasons.push(
            "approval notification ops controller evidence is missing or not validated".to_string(),
        );
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons.push("approval notification ops controller evidence is stale".to_string());
    }
    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    };
    let message = if production_blocked {
        format!(
            "approval notification production ops are blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "approval notification routing, latest delivery run, and required ops controller evidence are ready".to_string()
    };
    ApprovalNotificationProductionOpsReadiness {
        status: status.to_string(),
        production_blocked,
        latest_run_status,
        latest_run_age_hours,
        routing_status: routing.status.clone(),
        channel_count: routing.channel_count,
        unroutable_pending_count: routing.unroutable_pending_count,
        controller_required,
        controller_configured,
        latest_controller_status,
        latest_controller_age_hours,
        controller_evidence_fresh,
        latest_controller_validated,
        message,
        blocking_reasons,
    }
}

fn build_approval_notification_deployment_readiness(
    audit_logs: &[AuditLog],
    routing: &ApprovalNotificationRoutingSummary,
    generated_at: DateTime<Utc>,
    controller_required: bool,
    controller_configured: bool,
) -> ApprovalNotificationDeploymentReadiness {
    let latest_validation = audit_logs
        .iter()
        .filter(|log| log.action == "approval.notification_deployment_validation_run")
        .max_by_key(|log| log.created_at);
    let controller_validation_logs = audit_logs
        .iter()
        .filter(|log| {
            log.action == "approval.notification_deployment_validation_run"
                && log
                    .details
                    .get("controller_execution")
                    .and_then(|execution| execution.get("attempted"))
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
        })
        .collect::<Vec<_>>();
    let controller_execution_count = controller_validation_logs.len();
    let controller_failed_count = controller_validation_logs
        .iter()
        .filter(|log| {
            log.details
                .get("controller_execution")
                .and_then(|execution| execution.get("status"))
                .and_then(Value::as_str)
                .is_some_and(|status| status != "validated")
        })
        .count();
    let latest_validation_at = latest_validation.map(|log| log.created_at);
    let latest_validation_age_hours =
        latest_validation_at.map(|created_at| (generated_at - created_at).num_hours());
    let latest_validation_status = latest_validation
        .and_then(|log| log.details.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let pending_approval_count = latest_validation
        .map(|log| json_usize(&log.details, "pending_approval_count"))
        .unwrap_or(routing.pending_approval_count);
    let routable_pending_count = latest_validation
        .map(|log| json_usize(&log.details, "routable_pending_count"))
        .unwrap_or(routing.routable_pending_count);
    let unroutable_pending_count = latest_validation
        .map(|log| json_usize(&log.details, "unroutable_pending_count"))
        .unwrap_or(routing.unroutable_pending_count);
    let channel_count = latest_validation
        .map(|log| json_usize(&log.details, "channel_count"))
        .unwrap_or(routing.channel_count);
    let persisted_policy_count = latest_validation
        .map(|log| json_usize(&log.details, "persisted_policy_count"))
        .unwrap_or(routing.persisted_policy_count);
    let active_policy_count = latest_validation
        .map(|log| json_usize(&log.details, "active_policy_count"))
        .unwrap_or(routing.active_policy_count);
    let latest_controller_status = latest_validation
        .and_then(|log| log.details.get("controller_execution"))
        .and_then(|execution| execution.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_age_hours = latest_validation
        .filter(|_| latest_controller_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_controller_validated = latest_controller_status.as_deref() == Some("validated");
    let mut blocking_reasons = Vec::new();

    if latest_validation.is_none() {
        blocking_reasons
            .push("approval notification deployment validation has not run".to_string());
    }
    if channel_count == 0 {
        blocking_reasons.push(
            "approval notification deployment validation found no delivery channels".to_string(),
        );
    }
    if active_policy_count == 0 {
        blocking_reasons.push(
            "approval notification deployment validation found no active channel policies"
                .to_string(),
        );
    }
    if unroutable_pending_count > 0 {
        blocking_reasons.push(
            "approval notification deployment validation found unroutable pending approvals"
                .to_string(),
        );
    }
    if latest_validation_status
        .as_deref()
        .is_some_and(|status| status != "healthy")
    {
        blocking_reasons
            .push("latest approval notification deployment validation was not healthy".to_string());
    }
    if latest_validation_age_hours.is_some_and(|hours| hours >= 24) {
        blocking_reasons
            .push("approval notification deployment validation evidence is stale".to_string());
    }
    if controller_required && !controller_configured {
        blocking_reasons.push(
            "approval notification deployment controller is required but not configured"
                .to_string(),
        );
    }
    if controller_required && controller_configured && !latest_controller_validated {
        blocking_reasons.push(
            "approval notification deployment controller evidence is missing or not validated"
                .to_string(),
        );
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons
            .push("approval notification deployment controller evidence is stale".to_string());
    }

    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Approval notification deployment validation is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "Approval notification deployment has a recent healthy validation run".to_string()
    };

    ApprovalNotificationDeploymentReadiness {
        status,
        production_blocked,
        latest_validation_at,
        latest_validation_age_hours,
        latest_validation_status,
        pending_approval_count,
        routable_pending_count,
        unroutable_pending_count,
        channel_count,
        persisted_policy_count,
        active_policy_count,
        controller_required,
        controller_configured,
        latest_controller_status,
        latest_controller_age_hours,
        controller_evidence_fresh,
        latest_controller_validated,
        controller_execution_count,
        controller_failed_count,
        deployment_validated: !production_blocked,
        blocking_reasons,
        message,
    }
}

pub(crate) fn approval_notification_deployment_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_APPROVAL_NOTIFICATION_DEPLOYMENT_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        })
        .unwrap_or(false)
}

pub(crate) fn approval_notification_deployment_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_APPROVAL_NOTIFICATION_DEPLOYMENT_CONTROLLER_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

