    #[test]
    fn finance_close_controller_can_bootstrap_its_required_evidence() {
        let generated_at = Utc::now();
        let dashboard = UsageFinanceDashboardSummary {
            generated_at,
            current_cost_cents: 0.0,
            current_total_tokens: 0,
            current_tool_calls: 0,
            comparison_basis: "current".to_string(),
            budget_pressure_status: "normal".to_string(),
            budget_pressure_count: 0,
            critical_budget_count: 0,
            warning_budget_count: 0,
            alert_count: 0,
            critical_alert_count: 0,
            warning_alert_count: 0,
            alert_route_count: 1,
            active_alert_route_count: 1,
            rollup_count: 1,
            latest_rollup_at: Some(generated_at),
            latest_rollup_age_hours: Some(0),
            finance_export_target_configured: true,
            finance_export_schedule_enabled: true,
            forecast_7d_cost_cents: Some(0.0),
            forecast_30d_cost_cents: Some(0.0),
            top_provider_by_cost: None,
            recommendations: vec![],
            attention_items: vec![],
        };
        let export = UsageFinanceOperationAudit {
            action: "usage.finance_export_delivered".to_string(),
            status: "delivered".to_string(),
            subject: Some("admin-1".to_string()),
            created_at: generated_at,
        };
        let delivery = UsageFinanceOperationAudit {
            action: "usage.cost_alerts_delivered".to_string(),
            status: "delivered".to_string(),
            subject: Some("admin-1".to_string()),
            created_at: generated_at,
        };

        let bootstrap_ready = build_usage_finance_production_close_readiness(
            &dashboard,
            &[],
            &[],
            "fresh",
            "no_alerts",
            Some(&export),
            Some(&delivery),
            generated_at,
            true,
            true,
            true,
            true,
        );
        assert_eq!(bootstrap_ready.status, "blocked");
        assert!(
            bootstrap_ready.blocking_reasons.iter().any(|reason| {
                reason == "finance close controller has no recent closed evidence"
            })
        );
        assert!(bootstrap_ready.blocking_reasons.iter().any(|reason| {
            reason == "finance reconciliation controller has no recent reconciled evidence"
        }));
        assert!(finance_close_controller_prerequisites_ready(
            &bootstrap_ready
        ));

        let export_blocked = build_usage_finance_production_close_readiness(
            &dashboard,
            &[],
            &[],
            "fresh",
            "no_alerts",
            None,
            Some(&delivery),
            generated_at,
            true,
            true,
            true,
            true,
        );
        assert!(
            export_blocked.blocking_reasons.iter().any(|reason| {
                reason == "finance export has no recent delivered audit evidence"
            })
        );
        assert!(!finance_close_controller_prerequisites_ready(
            &export_blocked
        ));
    }

    #[tokio::test]
    async fn observability_remediation_controller_executes_external_boundary() {
        let payloads = Arc::new(tokio::sync::Mutex::new(Vec::new()));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("observability remediation listener");
        let controller_addr = listener
            .local_addr()
            .expect("observability remediation addr");
        let controller = Router::new()
            .route(
                "/observability-remediation",
                post(mock_observability_remediation_controller),
            )
            .with_state(payloads.clone());
        let controller_server = tokio::spawn(async move {
            axum::serve(listener, controller)
                .await
                .expect("mock observability remediation controller");
        });
        let before = ObservabilityBackpressure {
            status: "attention".to_string(),
            queued_jobs: 2,
            running_jobs: 1,
            failed_jobs: 0,
            retryable_jobs: 1,
            pending_approvals: 3,
            waiting_approval_sessions: 1,
            failed_sessions: 0,
            failed_tool_calls: 0,
            oldest_queued_job_age_seconds: Some(420),
        };
        let after = ObservabilityBackpressure {
            status: "healthy".to_string(),
            queued_jobs: 0,
            running_jobs: 1,
            failed_jobs: 0,
            retryable_jobs: 0,
            pending_approvals: 0,
            waiting_approval_sessions: 0,
            failed_sessions: 0,
            failed_tool_calls: 0,
            oldest_queued_job_age_seconds: None,
        };
        let actions = vec![
            "approval_escalation_due_run".to_string(),
            "worker_drain_required".to_string(),
        ];
        let lookup = |key: &str| match key {
            "MANDOFORGE_OBSERVABILITY_REMEDIATION_CONTROLLER_URL" => Some(format!(
                "http://{controller_addr}/observability-remediation"
            )),
            "MANDOFORGE_OBSERVABILITY_REMEDIATION_CONTROLLER_TOKEN" => {
                Some("remediation-token".to_string())
            }
            _ => None,
        };

        let execution =
            execute_observability_remediation_controller(&lookup, &before, &after, &actions)
                .await
                .expect("observability remediation controller");

        assert_eq!(execution["status"], "remediated");
        assert_eq!(execution["remediation_id"], "observability-remediation-1");
        assert_eq!(execution["steps"].as_array().expect("steps").len(), 2);
        let payloads = payloads.lock().await;
        assert_eq!(payloads.len(), 1);
        assert_eq!(payloads[0]["type"], "mandoforge.observability_remediation");
        assert_eq!(payloads[0]["actions"][0], "approval_escalation_due_run");
        assert_eq!(payloads[0]["actions"][1], "worker_drain_required");
        assert_eq!(payloads[0]["before"]["pending_approvals"], 3);
        assert_eq!(payloads[0]["after"]["pending_approvals"], 0);

        controller_server.abort();
    }

