    #[test]
    fn truncates_execution_output_on_utf8_boundary() {
        let output = truncate_output("abc你好", 4);
        assert_eq!(output.text, "abc");
        assert_eq!(output.original_bytes, 9);
        assert!(output.truncated);

        let unchanged = truncate_output("short", 64);
        assert_eq!(unchanged.text, "short");
        assert_eq!(unchanged.original_bytes, 5);
        assert!(!unchanged.truncated);
    }

    #[tokio::test]
    async fn execution_queue_tracks_job_lifecycle() {
        let queue = ExecutionQueue::default();
        let environment_id = Uuid::new_v4();
        let request = ExecutionJobRequest {
            session_id: Uuid::new_v4(),
            environment_id: Some(environment_id),
            approval_id: Uuid::new_v4(),
            tool_call_id: Uuid::new_v4(),
            tool_name: "codex.exec".to_string(),
            max_attempts: None,
        };

        let queued = queue.enqueue(request).await.expect("queue job");
        assert_eq!(queued.status, ExecutionJobStatus::Queued);
        assert_eq!(queued.environment_id, Some(environment_id));
        assert_eq!(queue.list().await.expect("list jobs").len(), 1);

        let running = queue
            .start(queued.id, "test-worker")
            .await
            .expect("start job");
        assert_eq!(running.status, ExecutionJobStatus::Running);
        assert!(running.started_at.is_some());
        assert_eq!(running.worker_id.as_deref(), Some("test-worker"));
        assert!(running.lease_expires_at.is_some());

        let completed = queue.complete(queued.id).await.expect("complete job");
        assert_eq!(completed.status, ExecutionJobStatus::Completed);
        assert!(completed.completed_at.is_some());

        let fenced = queue
            .enqueue(ExecutionJobRequest {
                session_id: Uuid::new_v4(),
                environment_id: None,
                approval_id: Uuid::new_v4(),
                tool_call_id: Uuid::new_v4(),
                tool_name: "shell.exec".to_string(),
                max_attempts: None,
            })
            .await
            .expect("queue fenced job");
        queue
            .start(fenced.id, "worker-a")
            .await
            .expect("start fenced job");
        let stale_complete = queue
            .complete_started(fenced.id, "worker-b")
            .await
            .expect_err("stale worker cannot complete running job");
        assert_eq!(stale_complete.status, StatusCode::NOT_FOUND);
        let fenced_requeued = queue
            .retry_or_fail_started(fenced.id, "worker-a", "transient")
            .await
            .expect("owning worker can retry running job");
        assert_eq!(fenced_requeued.status, ExecutionJobStatus::Queued);
        let fenced_restart = queue
            .start(fenced.id, "worker-b")
            .await
            .expect("restart fenced job");
        assert_eq!(fenced_restart.worker_id.as_deref(), Some("worker-b"));
        let stale_retry = queue
            .retry_or_fail_started(fenced.id, "worker-a", "late failure")
            .await
            .expect_err("stale worker cannot retry another worker's job");
        assert_eq!(stale_retry.status, StatusCode::NOT_FOUND);
        let fenced_completed = queue
            .complete_started(fenced.id, "worker-b")
            .await
            .expect("owning worker completes running job");
        assert_eq!(fenced_completed.status, ExecutionJobStatus::Completed);

        let retryable = queue
            .enqueue(ExecutionJobRequest {
                session_id: Uuid::new_v4(),
                environment_id: None,
                approval_id: Uuid::new_v4(),
                tool_call_id: Uuid::new_v4(),
                tool_name: "codex.exec".to_string(),
                max_attempts: Some(2),
            })
            .await
            .expect("queue retryable job");
        let first_attempt = queue
            .start(retryable.id, "worker-a")
            .await
            .expect("start retryable job");
        assert_eq!(first_attempt.attempt_count, 1);
        let requeued = queue
            .retry_or_fail(retryable.id, "transient app server status")
            .await
            .expect("retry job");
        assert_eq!(requeued.status, ExecutionJobStatus::Queued);
        assert_eq!(requeued.attempt_count, 1);
        assert_eq!(requeued.max_attempts, 2);
        assert_eq!(
            requeued.last_error.as_deref(),
            Some("transient app server status")
        );
        assert!(requeued.worker_id.is_none());
        assert!(requeued.lease_expires_at.is_none());

        let second_attempt = queue
            .start(retryable.id, "worker-b")
            .await
            .expect("restart retryable job");
        assert_eq!(second_attempt.attempt_count, 2);
        let failed = queue
            .retry_or_fail(retryable.id, "still failing")
            .await
            .expect("fail after max attempts");
        assert_eq!(failed.status, ExecutionJobStatus::Failed);
        assert_eq!(failed.attempt_count, 2);
        assert_eq!(failed.last_error.as_deref(), Some("still failing"));
        assert!(failed.completed_at.is_some());

        let cancelable = queue
            .enqueue(ExecutionJobRequest {
                session_id: Uuid::new_v4(),
                environment_id: None,
                approval_id: Uuid::new_v4(),
                tool_call_id: Uuid::new_v4(),
                tool_name: "shell.exec".to_string(),
                max_attempts: None,
            })
            .await
            .expect("queue cancelable job");
        let canceled = queue.cancel(cancelable.id).await.expect("cancel job");
        assert_eq!(canceled.status, ExecutionJobStatus::Canceled);
        assert!(canceled.completed_at.is_some());
        assert!(canceled.lease_expires_at.is_none());
    }

    #[tokio::test]
    async fn broker_execution_queue_is_reserved_until_implemented() {
        for kind in [BrokerQueueKind::Redis, BrokerQueueKind::Nats] {
            let queue = BrokerExecutionQueue::new(kind);
            let request = ExecutionJobRequest {
                session_id: Uuid::new_v4(),
                environment_id: None,
                approval_id: Uuid::new_v4(),
                tool_call_id: Uuid::new_v4(),
                tool_name: "file.write".to_string(),
                max_attempts: None,
            };

            assert!(queue.enqueue(request).await.is_err());
            assert!(queue.start(Uuid::new_v4(), "worker").await.is_err());
            assert!(queue.complete(Uuid::new_v4()).await.is_err());
            assert!(queue.fail(Uuid::new_v4()).await.is_err());
            assert!(queue.cancel(Uuid::new_v4()).await.is_err());
            assert!(queue.retry_or_fail(Uuid::new_v4(), "error").await.is_err());
            assert!(queue.list().await.is_err());
            assert!(queue.get(Uuid::new_v4()).await.is_err());
        }
    }

    #[tokio::test]
    async fn execution_job_cancel_route_marks_job_canceled_and_audits() {
        let app = test_app_with_worker(Arc::new(QueueBackedExecutionWorker)).await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");
        let session: Session = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/sessions",
                json!({"agent_id": agent.id, "title": "cancel execution job"}),
            ),
        )
        .await;
        let approval_result: Value = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/tools/file.write/execute",
                json!({
                    "session_id": session.id,
                    "args": {"path": "cancel.md", "content": "cancel me"}
                }),
            ),
        )
        .await;
        let approval_id = approval_result["approval_id"]
            .as_str()
            .expect("approval id");
        let approved: Approval = request_json(
            app.clone(),
            approve_request(format!("/api/approvals/{approval_id}/approve")),
        )
        .await;
        let job = request_json::<Vec<execution_queue::ExecutionJob>>(
            app.clone(),
            Request::builder()
                .uri("/api/execution-jobs")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await
        .into_iter()
        .find(|job| job.approval_id == approved.id)
        .expect("execution job queued");

        let canceled: execution_queue::ExecutionJob = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!("/api/execution-jobs/{}/cancel", job.id))
                .header("x-mandoforge-subject", "operator-1")
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(canceled.status, ExecutionJobStatus::Canceled);
        assert!(canceled.completed_at.is_some());

        let events: Vec<SessionEvent> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/events", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(events.iter().any(|event| {
            event.event_type == "execution.canceled"
                && event.payload["execution_job_id"] == json!(job.id)
        }));

        let audit_logs: Vec<AuditLog> = request_json(
            app,
            Request::builder()
                .uri("/api/audit-logs")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(
            audit_logs.iter().any(|log| {
                log.action == "execution.canceled" && log.resource_id == Some(job.id)
            })
        );
    }

