    #[tokio::test]
    async fn semantic_kernel_persists_sources_objects_links_and_audit() {
        let app = test_app().await;
        let source: SemanticSource = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/semantic-sources",
                json!({
                    "source_type": "repo_doc",
                    "source_uri": "repo://docs/mandoforge-roadmap-v2.md",
                    "display_name": "MandoForge Roadmap v2",
                    "owner_type": "repo",
                    "metadata": {"path": "docs/mandoforge-roadmap-v2.md"},
                    "provenance": {"ingested_by": "stage-5.1-test"},
                    "freshness": {"state": "workspace_current"}
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        assert_eq!(source.source_type, "repo_doc");
        assert_eq!(source.status, "active");
        assert_eq!(source.metadata["path"], "docs/mandoforge-roadmap-v2.md");

        let object: SemanticObject = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/semantic-objects",
                json!({
                    "source_id": source.id,
                    "object_type": "decision",
                    "object_key": "decision:agent-os-first",
                    "title": "Agent OS before domain packs",
                    "summary": "MandoForge builds the Agent OS substrate before Legal/Coding/Sales workflow packs.",
                    "content": {
                        "decision": "workflow packs run on the Agent OS and are not the OS itself"
                    },
                    "semantic_scopes": {
                        "project_scope": "mandoforge",
                        "repo_scope": "mandoforge",
                        "service_scope": "agent-os",
                        "workflow_scope": "roadmap",
                        "policy_scope": "governed-runtime",
                        "memory_scope": "strategy"
                    },
                    "provenance": {"source_ref": "docs/mandoforge-roadmap-v2.md"},
                    "trust_level": "human_verified",
                    "freshness": "current"
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        assert_eq!(object.source_id, Some(source.id));
        assert_eq!(object.object_type, "decision");
        assert_eq!(object.trust_level, "human_verified");
        assert_eq!(
            object.source_uri.as_deref(),
            Some("repo://docs/mandoforge-roadmap-v2.md")
        );
        assert_eq!(object.semantic_scopes["workflow_scope"], json!("roadmap"));

        let link: SemanticLink = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/semantic-links",
                json!({
                    "from_entity_type": "semantic_object",
                    "from_entity_id": object.id.to_string(),
                    "relation_type": "defines_scope_for",
                    "to_entity_type": "workflow",
                    "to_entity_id": "workflow-packs",
                    "metadata": {"stage": "5.1"},
                    "provenance": {"source_id": source.id},
                    "confidence": 0.9
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        assert_eq!(link.from_entity_type, "semantic_object");
        assert_eq!(link.relation_type, "defines_scope_for");
        assert_eq!(link.confidence, 0.9);

        let source_objects: Vec<SemanticObject> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/semantic-sources/{}/objects", source.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(source_objects.len(), 1);
        assert_eq!(source_objects[0].id, object.id);

        let updated_object: SemanticObject = request_json(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/semantic-objects/{}", object.id),
                json!({
                    "freshness": "stale",
                    "content": {
                        "decision": "workflow packs run on the Agent OS and are not the OS itself",
                        "review": "needs periodic roadmap refresh"
                    }
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        assert_eq!(updated_object.freshness, "stale");
        assert_eq!(
            updated_object.content["review"],
            "needs periodic roadmap refresh"
        );

        let audit_logs: Vec<AuditLog> = request_json(
            app,
            Request::builder()
                .uri("/api/audit-logs")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        for expected in [
            "semantic_source.created",
            "semantic_object.created",
            "semantic_link.created",
            "semantic_object.updated",
        ] {
            assert!(
                audit_logs.iter().any(|log| log.action == expected),
                "missing audit action {expected}"
            );
        }
        assert!(audit_logs.iter().any(|log| {
            log.action == "semantic_object.created"
                && log.resource_id == Some(object.id)
                && log.details["trust_level"] == "human_verified"
                && log.details["semantic_scopes"]["project_scope"] == "mandoforge"
        }));
    }

    #[tokio::test]
    async fn ontology_registry_exposes_core_objects_and_allowed_relations() {
        let app = test_app().await;

        let registry: Value = request_json(
            app,
            Request::builder()
                .uri("/api/ontology/registry")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;

        assert_eq!(registry["version"], "core-v0.1");
        assert!(
            registry["object_types"]
                .as_array()
                .unwrap()
                .iter()
                .any(|object| { object["name"] == "memory" && object["memory_level"] == "L0-L4" })
        );
        assert!(
            registry["relation_types"]
                .as_array()
                .unwrap()
                .iter()
                .any(|relation| {
                    relation["name"] == "derived_from"
                        && relation["from_entity_type"] == "semantic_object"
                        && relation["to_entity_type"] == "artifact"
                })
        );
        assert!(
            registry["relation_types"]
                .as_array()
                .unwrap()
                .iter()
                .any(|relation| {
                    relation["name"] == "defines_scope_for"
                        && relation["from_entity_type"] == "semantic_object"
                        && relation["to_entity_type"] == "workflow"
                })
        );
    }

    #[tokio::test]
    async fn ontology_engine_readiness_reports_release_lifecycle_blockers() {
        let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
        let readiness = build_ontology_engine_readiness(&state)
            .await
            .expect("readiness");

        assert_eq!(readiness.status, "blocked");
        assert!(readiness.completion_blocked);
        assert_eq!(readiness.required_evidence_class, "customer_grade");
        assert_eq!(readiness.registry_version, "core-v0.1");
        assert!(readiness.object_type_count >= 20);
        assert!(readiness.relation_type_count >= 10);
        assert_eq!(readiness.check_count, 8);
        assert_eq!(readiness.ready_check_count, 4);
        assert_eq!(readiness.pilot_ready_check_count, 1);
        assert_eq!(readiness.blocked_check_count, 3);

        for ready_check in [
            "core-registry",
            "relation-constraints",
            "builder-review-proposals",
            "context-packet-rendering",
        ] {
            let check = readiness
                .checks
                .iter()
                .find(|check| check.id == ready_check)
                .unwrap_or_else(|| panic!("missing {ready_check} ontology readiness check"));
            assert_eq!(check.status, "ready");
            assert_eq!(check.required_evidence_class, "customer_grade");
        }

        let lifecycle = readiness
            .checks
            .iter()
            .find(|check| check.id == "domain-ontology-lifecycle")
            .expect("domain lifecycle check");
        assert_eq!(lifecycle.status, "blocked");
        assert!(
            lifecycle
                .blockers
                .iter()
                .any(|blocker| { blocker.contains("promoted, rolled back, or migrated") })
        );

        let release = readiness
            .checks
            .iter()
            .find(|check| check.id == "approved-release-materialization")
            .expect("release materialization check");
        assert_eq!(release.status, "blocked");
        assert!(
            release
                .next_actions
                .iter()
                .any(|action| action.contains("immutable ontology versions"))
        );
    }

    #[tokio::test]
    async fn ontology_engine_readiness_uses_promoted_release_evidence() {
        let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
        let release = ontology_release_candidate_for_test(&state, "commerce-vtest-readiness").await;
        gate_ontology_release_with_actor(&state, release.id, "test")
            .await
            .expect("gate release");
        promote_ontology_release_with_actor(&state, release.id, "test")
            .await
            .expect("promote release");

        let readiness = build_ontology_engine_readiness(&state)
            .await
            .expect("readiness");

        assert_eq!(readiness.status, "blocked");
        assert!(readiness.completion_blocked);
        assert_eq!(readiness.check_count, 8);
        assert_eq!(readiness.ready_check_count, 7);
        assert_eq!(readiness.pilot_ready_check_count, 1);
        assert_eq!(readiness.blocked_check_count, 0);
        assert_eq!(
            ontology_readiness_check_status(&readiness, "domain-ontology-lifecycle"),
            "ready"
        );
        assert_eq!(
            ontology_readiness_check_status(&readiness, "approved-release-materialization"),
            "ready"
        );
        assert_eq!(
            ontology_readiness_check_status(&readiness, "migration-policy"),
            "ready"
        );
        assert_eq!(
            ontology_readiness_check_status(&readiness, "conflict-trust-runtime-gates"),
            "pilot_ready"
        );
        let migration = readiness
            .checks
            .iter()
            .find(|check| check.id == "migration-policy")
            .expect("migration check");
        assert!(migration.blockers.is_empty());
        assert!(migration.evidence.iter().any(|evidence| {
            evidence.contains("active_release")
                && evidence.contains("version=commerce-vtest-readiness")
        }));
        assert!(migration.evidence.iter().any(|evidence| {
            evidence.contains("migration_policy_rollback=previous_active_release")
        }));
    }

    fn ontology_readiness_check_status<'a>(
        readiness: &'a OntologyEngineReadiness,
        id: &str,
    ) -> &'a str {
        readiness
            .checks
            .iter()
            .find(|check| check.id == id)
            .unwrap_or_else(|| panic!("missing {id} ontology readiness check"))
            .status
            .as_str()
    }

