    #[tokio::test]
    async fn semantic_synthesis_run_creates_reflection_artifact_and_review_candidates() {
        let app = test_app().await;
        let agent: Agent = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/agents",
                json!({
                    "name": "semantic-reflection-agent",
                    "kind": "manager",
                    "agent_role": "manager",
                    "provider": "openai-compatible",
                    "model": "gpt-5.4-mini",
                    "tools": ["artifact.create"],
                    "semantic_scopes": {
                        "domain_scope": "platform",
                        "workflow_scope": "semantic-reflection",
                        "memory_scope": "engineering",
                        "share_policy": "isolated"
                    },
                    "release_state": "draft"
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        let session: Session = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/sessions",
                json!({
                    "agent_id": agent.id,
                    "title": "semantic reflection session",
                    "message": "Collect evidence before proposing durable memory."
                }),
            ),
        )
        .await;
        let _: Vec<SessionEvent> = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                &format!("/api/sessions/{}/events", session.id),
                json!({
                    "events": [
                        {
                            "type": "session.goal.completed",
                            "payload": {
                                "objective": "Collect evidence before proposing durable memory."
                            }
                        }
                    ]
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;

        let result: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                &format!("/api/sessions/{}/semantic-synthesis-runs", session.id),
                json!({
                    "synthesis_type": "post_run_reflection",
                    "goal_attempted": "Prove reflection creates reviewable memory instead of direct org memory.",
                    "context_used": ["session_events", "context_packets"],
                    "worked": ["checkpoint was replayable"],
                    "failed_or_corrected": ["none"],
                    "unsafe_assumptions": ["do not promote self-reflection automatically"],
                    "durable_memory_candidates": [
                        {
                            "proposed_object_key": "memory:semantic-reflection:review-required",
                            "title": "Reflection memory requires review",
                            "summary": "Reflection output must enter the writeback review queue before becoming durable memory.",
                            "content": {"rule": "candidate-first"},
                            "trust_level": "source_attested",
                            "freshness": "current"
                        }
                    ]
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;

        assert_eq!(result["status"], "created");
        assert_eq!(result["synthesis_type"], "post_run_reflection");
        assert_eq!(
            result["artifact"]["artifact_type"],
            "semantic_reflection_report"
        );
        assert_eq!(
            result["artifact"]["content"]["goal_attempted"],
            "Prove reflection creates reviewable memory instead of direct org memory."
        );
        assert!(
            result["artifact"]["content"]["evidence_counts"]["event_count"]
                .as_u64()
                .unwrap_or_default()
                > 0
        );
        assert_eq!(result["candidates"].as_array().unwrap().len(), 1);
        assert_eq!(
            result["candidates"][0]["candidate_type"],
            "session_reflection"
        );
        assert_eq!(result["candidates"][0]["status"], "pending");
        assert_eq!(
            result["candidates"][0]["semantic_scopes"]["workflow_scope"],
            "semantic-reflection"
        );

        let artifacts: Vec<Artifact> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/artifacts", session.id))
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(artifacts.iter().any(|artifact| {
            artifact.artifact_type == "semantic_reflection_report"
                && artifact.name == "semantic-reflection-report.json"
        }));

        let semantic_objects: Vec<SemanticObject> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/semantic-objects")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(
            !semantic_objects
                .iter()
                .any(|object| object.object_key == "memory:semantic-reflection:review-required"),
            "reflection must not bypass memory writeback review"
        );

        let audit_logs: Vec<AuditLog> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/audit-logs")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(audit_logs.iter().any(|log| {
            log.action == "semantic_synthesis.run_created"
                && log.resource_type == "artifact"
                && log.details["candidate_count"] == json!(1)
        }));

        let events: Vec<SessionEvent> = request_json(
            app,
            Request::builder()
                .uri(format!("/api/sessions/{}/events", session.id))
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(events.iter().any(|event| {
            event.event_type == "semantic_synthesis.run_created"
                && event.payload["candidate_count"] == json!(1)
        }));
    }

    #[tokio::test]
    async fn semantic_synthesis_run_requires_idle_or_completed_checkpoint() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");
        let session: Session = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/sessions",
                json!({
                    "agent_id": agent.id,
                    "title": "unfinished semantic reflection"
                }),
            ),
        )
        .await;

        let (status, body) = request_value(
            app.clone(),
            json_request_with_headers(
                "POST",
                &format!("/api/sessions/{}/semantic-synthesis-runs", session.id),
                json!({
                    "synthesis_type": "post_run_reflection",
                    "goal_attempted": "should be rejected before checkpoint",
                    "durable_memory_candidates": []
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;

        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert!(
            body["error"].as_str().unwrap_or_default().contains(
                "semantic synthesis requires a completed session or idle managed-session checkpoint"
            ),
            "unexpected error body: {body}"
        );
        let artifacts: Vec<Artifact> = request_json(
            app,
            Request::builder()
                .uri(format!("/api/sessions/{}/artifacts", session.id))
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(
            artifacts.is_empty(),
            "rejected synthesis must not write artifacts"
        );
    }

    #[test]
    fn memory_governance_summary_includes_pending_partitions_and_escaped_keys() {
        let now = Utc::now();
        let visible_session_id = Uuid::new_v4();
        let pending_candidate = MemoryWritebackCandidate {
            id: Uuid::new_v4(),
            session_id: visible_session_id,
            candidate_type: "session_summary".to_string(),
            source_event_id: None,
            source_artifact_id: None,
            source_approval_id: None,
            source_handoff_id: None,
            proposed_object_type: "memory".to_string(),
            proposed_object_key: "memory:pending-only".to_string(),
            title: "Pending memory".to_string(),
            summary: "Pending writeback should still form a governance partition".to_string(),
            content: empty_json_object(),
            semantic_scopes: json!({
                "domain_scope": "legal|shared",
                "workflow_scope": "contract=review",
                "memory_scope": "org%memory",
                "share_policy": "isolated"
            }),
            source_refs: empty_json_object(),
            provenance: empty_json_object(),
            trust_level: "unverified".to_string(),
            freshness: "current".to_string(),
            status: "pending".to_string(),
            reviewer_subject: None,
            review_reason: None,
            semantic_object_id: None,
            audit_trace_id: None,
            created_at: now,
            updated_at: now,
            decided_at: None,
        };

        let summary = build_memory_governance_summary(&[], &[pending_candidate], now);
        let expected_partition_key =
            "domain=legal%7Cshared|workflow=contract%3Dreview|memory=org%25memory";

        assert_eq!(summary.partition_count, 1);
        assert_eq!(summary.writeback.pending_count, 1);
        assert!(summary.partitions.iter().any(|partition| {
            partition.partition_key == expected_partition_key && partition.object_count == 0
        }));
        assert!(summary.attention_items.iter().any(|item| {
            item.kind == "pending_memory_writeback_review"
                && item.partition_key.as_deref() == Some(expected_partition_key)
        }));
        assert_ne!(
            memory_governance_partition_key("a|workflow=b", "c", "d"),
            memory_governance_partition_key("a", "b|workflow=c", "d")
        );
    }

    #[tokio::test]
    async fn memory_governance_summary_partitions_memory_by_scope_and_flags_risks() {
        let app = test_app().await;
        let source: SemanticSource = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/semantic-sources",
                json!({
                    "source_type": "memory",
                    "source_uri": "memory://governance-test",
                    "display_name": "Memory governance test",
                    "metadata": {"purpose": "partition summary"}
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;

        for (object_key, domain_scope, workflow_scope, memory_scope, trust_level, freshness) in [
            (
                "memory:social:brand:voice",
                "social-media",
                "content",
                "brand-voice",
                "human_verified",
                "current",
            ),
            (
                "memory:social:brand:old",
                "social-media",
                "content",
                "brand-voice",
                "human_verified",
                "stale",
            ),
            (
                "memory:ecommerce:ads:unverified",
                "ecommerce",
                "ads",
                "ad-ops",
                "unverified",
                "current",
            ),
        ] {
            let _: SemanticObject = request_json(
                app.clone(),
                json_request_with_headers(
                    "POST",
                    "/api/semantic-objects",
                    json!({
                        "source_id": source.id,
                        "object_type": "memory",
                        "object_key": object_key,
                        "title": object_key,
                        "summary": "governance summary fixture",
                        "content": {"note": object_key},
                        "semantic_scopes": {
                            "domain_scope": domain_scope,
                            "workflow_scope": workflow_scope,
                            "memory_scope": memory_scope,
                            "share_policy": "isolated"
                        },
                        "trust_level": trust_level,
                        "freshness": freshness
                    }),
                    &[("x-mandoforge-roles", "admin")],
                ),
            )
            .await;
        }

        let summary: Value = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/memory-governance/summary")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(
            summary["isolation_policy"],
            json!("domain_scope + workflow_scope + memory_scope")
        );
        assert_eq!(summary["memory_object_count"], json!(3));
        assert!(summary["partitions"].as_array().is_some_and(|partitions| {
            partitions.iter().any(|partition| {
                partition["partition_key"]
                    == json!("domain=social-media|workflow=content|memory=brand-voice")
                    && partition["object_count"] == json!(2)
                    && partition["stale_count"] == json!(1)
                    && partition["shared"] == json!(false)
            })
        }));
        assert!(summary["attention_items"].as_array().is_some_and(|items| {
            items
                .iter()
                .any(|item| item["kind"] == json!("stale_memory_objects"))
                && items
                    .iter()
                    .any(|item| item["kind"] == json!("unverified_memory_objects"))
        }));

        let detail: Value = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/memory-governance/partitions?partition_key=domain%3Dsocial-media%7Cworkflow%3Dcontent%7Cmemory%3Dbrand-voice")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(detail["partition"]["object_count"], json!(2));
        assert_eq!(detail["access_policy"], json!("isolated_partition"));
        assert_eq!(detail["object_count"], json!(2));
        assert!(detail["risk_items"].as_array().is_some_and(|items| {
            items
                .iter()
                .any(|item| item["kind"] == json!("stale_memory_objects"))
        }));

        let writebacks: Value = request_json(
            app,
            Request::builder()
                .uri("/api/memory-governance/writebacks?status=pending")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(writebacks["status_filter"], json!("pending"));
        assert_eq!(writebacks["candidate_count"], json!(0));
    }

