    #[test]
    fn provider_deployment_readiness_requires_controller_when_configured() {
        let generated_at = Utc::now();
        let missing = build_provider_deployment_readiness(&[], generated_at, true, false);
        assert_eq!(missing.status, "blocked");
        assert!(missing.production_blocked);
        assert!(missing.controller_required);
        assert!(!missing.controller_configured);
        assert!(missing.blocking_reasons.iter().any(|reason| {
            reason == "provider deployment controller is required but not configured"
        }));

        let without_controller = build_provider_deployment_readiness(
            &[new_audit_log(
                None,
                "user",
                None,
                "provider.deployment_validation_run",
                "providers",
                None,
                json!({
                    "status": "healthy",
                    "provider_count": 1,
                    "healthy_count": 1,
                    "unhealthy_count": 0,
                    "controller_required": true,
                    "controller_configured": true,
                    "controller_execution": {
                        "attempted": false,
                        "status": "skipped",
                        "reason": "controller_not_configured"
                    }
                }),
            )],
            generated_at,
            true,
            true,
        );
        assert_eq!(without_controller.status, "blocked");
        assert!(without_controller.production_blocked);
        assert!(!without_controller.latest_controller_validated);

        let mut controller_audit = new_audit_log(
            None,
            "user",
            None,
            "provider.deployment_validation_run",
            "providers",
            None,
            json!({
                "status": "healthy",
                "provider_count": 1,
                "healthy_count": 1,
                "unhealthy_count": 0,
                "controller_required": true,
                "controller_configured": true,
                "controller_execution": {
                    "attempted": true,
                    "status": "validated",
                    "deployment_id": "provider-deployment-1"
                }
            }),
        );
        controller_audit.created_at = generated_at;
        let ready = build_provider_deployment_readiness(
            &[controller_audit.clone()],
            generated_at,
            true,
            true,
        );
        assert_eq!(ready.status, "ready");
        assert!(!ready.production_blocked);
        assert_eq!(ready.latest_controller_status.as_deref(), Some("validated"));
        assert!(ready.latest_controller_validated);
        assert!(ready.controller_evidence_fresh);
        assert_eq!(ready.latest_controller_age_hours, Some(0));
        assert_eq!(ready.controller_execution_count, 1);
        assert_eq!(ready.controller_failed_count, 0);

        let mut stale_controller_audit = controller_audit;
        stale_controller_audit.created_at = generated_at - chrono::Duration::hours(25);
        let stale = build_provider_deployment_readiness(
            &[stale_controller_audit],
            generated_at,
            true,
            true,
        );
        assert_eq!(stale.status, "blocked");
        assert!(stale.production_blocked);
        assert!(stale.latest_controller_validated);
        assert!(!stale.controller_evidence_fresh);
        assert_eq!(stale.latest_controller_age_hours, Some(25));
        assert!(
            stale
                .blocking_reasons
                .iter()
                .any(|reason| { reason == "provider deployment controller evidence is stale" })
        );
    }

    #[tokio::test]
    async fn provider_production_rollout_requires_fresh_passing_gate() {
        let app = test_app().await;

        let provider: ProviderRecord = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/providers")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "provider_type": "mock",
                        "name": "production-rollout-mock",
                        "default_model": "gpt-5.4-mini",
                        "config": {"budget": {"daily_request_limit": 10}}
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;

        let blocked_without_gate: ProviderProductionRolloutRun = request_json(
            app.clone(),
            Request::builder()
                .method(Method::POST)
                .uri("/api/providers/production-rollout/run")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "environment": "production",
                        "reason": "first rollout should fail closed before a gate run",
                        "provider_ids": [provider.id]
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        assert_eq!(blocked_without_gate.status, "blocked");
        assert!(blocked_without_gate.enforcement.production_blocked);
        assert_eq!(blocked_without_gate.enforcement.status, "blocked");

        let gate_run: ProviderPolicyGateRunResponse = request_json(
            app.clone(),
            Request::builder()
                .method(Method::POST)
                .uri("/api/providers/policy-gate/run")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(gate_run.run.status, "passed");

        let blocked_without_controller: ProviderProductionRolloutRun = request_json(
            app.clone(),
            Request::builder()
                .method(Method::POST)
                .uri("/api/providers/production-rollout/run")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "environment": "production",
                        "reason": "gate is fresh and passing",
                        "provider_ids": [provider.id]
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        assert_eq!(blocked_without_controller.status, "blocked");
        assert_eq!(blocked_without_controller.provider_count, 1);
        assert!(!blocked_without_controller.enforcement.production_blocked);
        assert!(!blocked_without_controller.controller_configured);
        assert_eq!(
            blocked_without_controller.controller_execution["reason"],
            "controller_not_configured"
        );
        assert!(
            blocked_without_controller
                .message
                .contains("PROVIDER_ROLLOUT_CONTROLLER_URL")
        );

        let _: ProviderRecord = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/providers")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "provider_type": "mock",
                        "name": "post-gate-provider",
                        "default_model": "gpt-5.4-mini",
                        "config": {"budget": {"daily_request_limit": 10}}
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        let blocked_stale_coverage: ProviderProductionRolloutRun = request_json(
            app.clone(),
            Request::builder()
                .method(Method::POST)
                .uri("/api/providers/production-rollout/run")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "environment": "production",
                        "provider_ids": [provider.id]
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        assert_eq!(blocked_stale_coverage.status, "blocked");
        assert!(
            blocked_stale_coverage
                .message
                .contains("does not cover the current provider set")
        );

        let audit_logs: Vec<AuditLog> = request_json(
            app,
            Request::builder()
                .uri("/api/audit-logs")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(audit_logs.iter().any(|log| {
            log.action == "provider.production_rollout_blocked"
                && log.details["status"] == "blocked"
        }));
    }

