    #[tokio::test]
    async fn agent_release_controller_executes_external_rollout_boundary() {
        let payloads = Arc::new(tokio::sync::Mutex::new(Vec::new()));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("release controller listener");
        let controller_addr = listener.local_addr().expect("release controller addr");
        let controller = Router::new()
            .route("/agent-release", post(mock_agent_release_controller))
            .with_state(payloads.clone());
        let controller_server = tokio::spawn(async move {
            axum::serve(listener, controller)
                .await
                .expect("mock agent release controller");
        });
        let release = AgentRelease {
            id: Uuid::new_v4(),
            agent_id: Uuid::new_v4(),
            agent_version_id: Uuid::new_v4(),
            environment: "prod".to_string(),
            status: "pending_approval".to_string(),
            eval_run_id: Some(Uuid::new_v4()),
            eval_score: Some(1.0),
            min_score: 1.0,
            requested_by: Some("release-requester".to_string()),
            requested_at: Some(Utc::now()),
            request_reason: Some("controller test".to_string()),
            approver_subject: Some("system".to_string()),
            decision_by: None,
            decided_at: None,
            decision_reason: None,
            promoted_by: None,
            promoted_at: None,
            automation_policy: json!({"auto_approve": true}),
            created_at: Utc::now(),
        };
        let lookup = |key: &str| match key {
            "MANDOFORGE_AGENT_RELEASE_CONTROLLER_URL" => {
                Some(format!("http://{controller_addr}/agent-release"))
            }
            "MANDOFORGE_AGENT_RELEASE_CONTROLLER_TOKEN" => Some("release-token".to_string()),
            _ => None,
        };

        let execution = execute_agent_release_controller(&lookup, &release, Utc::now())
            .await
            .expect("agent release controller execution");

        assert_eq!(execution["status"], "promoted");
        assert_eq!(execution["deployment_id"], "agent-release-1");
        assert_eq!(execution["steps"].as_array().expect("steps").len(), 3);
        let payloads = payloads.lock().await;
        assert_eq!(payloads.len(), 1);
        assert_eq!(payloads[0]["type"], "mandoforge.agent_release_rollout");
        assert_eq!(payloads[0]["release_id"], release.id.to_string());
        assert_eq!(payloads[0]["agent_id"], release.agent_id.to_string());
        assert_eq!(payloads[0]["environment"], "prod");
        assert_eq!(payloads[0]["eval_score"], 1.0);

        controller_server.abort();
    }

    #[tokio::test]
    async fn agent_release_required_controller_skips_auto_promotion_when_missing() {
        let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
        state.seed_demo_agent().await.expect("seed demo agent");
        let agent = state
            .list_agents()
            .await
            .expect("list agents")
            .into_iter()
            .next()
            .expect("seeded agent");
        let dataset = state
            .create_eval_dataset(CreateEvalDataset {
                name: "release controller required".to_string(),
                description: None,
            })
            .await
            .expect("create dataset");
        state
            .create_eval_case(
                dataset.id,
                CreateEvalCase {
                    input: json!({"final_answer": "evidence approval audit"}),
                    expected: Some(json!({"contains": ["evidence", "approval", "audit"]})),
                    grading_policy: json!({"kind": "final_answer"}),
                },
            )
            .await
            .expect("create eval case");
        let run = state
            .create_eval_run(dataset.id, CreateEvalRun { agent_id: agent.id })
            .await
            .expect("create eval run");
        let release = state
            .request_agent_release_promotion(
                agent.id,
                CreateAgentRelease {
                    agent_version_id: None,
                    eval_run_id: run.id,
                    environment: "prod".to_string(),
                    min_score: Some(1.0),
                },
                "release-requester".to_string(),
                Some("system".to_string()),
                Some("requires external rollout controller".to_string()),
                normalize_release_automation_policy(
                    Some(true),
                    Some(
                        (Utc::now() - chrono::Duration::minutes(1))
                            .to_rfc3339()
                            .as_str(),
                    ),
                    Some(
                        (Utc::now() + chrono::Duration::minutes(10))
                            .to_rfc3339()
                            .as_str(),
                    ),
                )
                .expect("automation policy"),
            )
            .await
            .expect("request release");
        let lookup = |key: &str| match key {
            "MANDOFORGE_AGENT_RELEASE_CONTROLLER_REQUIRED" => Some("true".to_string()),
            _ => None,
        };

        let automation = execute_due_agent_release_promotions_with_lookup(&state, lookup)
            .await
            .expect("release automation");

        assert!(automation.controller_required);
        assert!(!automation.controller_configured);
        assert_eq!(automation.pending_count, 1);
        assert_eq!(automation.promoted_count, 0);
        assert_eq!(automation.skipped_count, 1);
        assert_eq!(
            automation.results[0]["reason"],
            "controller_required_not_configured"
        );
        let pending = state
            .list_pending_agent_releases()
            .await
            .expect("pending releases");
        assert!(pending.iter().any(|candidate| candidate.id == release.id));
    }

