            fs::set_permissions(&env_shim_path, fs::Permissions::from_mode(0o755))
                .expect("chmod environment fake CLI");
            fs::set_permissions(&agent_shim_path, fs::Permissions::from_mode(0o755))
                .expect("chmod agent fake CLI");
