    #[tokio::test]
    async fn request_tenant_header_must_match_runtime_tenant() {
        let app = test_app().await;

        let (status, error) = request_value(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .header(
                    "x-mandoforge-tenant-id",
                    "00000000-0000-4000-8000-000000000099",
                )
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(status, StatusCode::FORBIDDEN);
        assert!(
            error["error"]
                .as_str()
                .unwrap_or_default()
                .contains("does not match this runtime tenant")
        );

        let (status, _) = request_value(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .header(
                    "x-mandoforge-tenant-id",
                    "00000000-0000-4000-8000-000000000001",
                )
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(status, StatusCode::OK);

        let readiness: TenantIsolationReadinessReport = request_json(
            app,
            Request::builder()
                .uri("/api/tenant-isolation/readiness")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(readiness.status, "critical");
        assert_eq!(readiness.runtime_tenant_mode, "single_runtime_tenant");
        assert!(readiness.header_fail_closed);
        assert!(readiness.membership_scope_enforced);
        assert_eq!(readiness.production_routing.status, "blocked");
        assert!(readiness.production_routing.production_blocked);
        assert!(!readiness.production_routing.cross_tenant_routing_supported);
        assert!(readiness.production_routing.header_fail_closed);
        assert!(readiness.production_routing.membership_scope_enforced);
        assert!(!readiness.production_routing.rls_ready);
        assert_eq!(readiness.rls.status, "migration_ready");
        assert!(!readiness.rls.enabled);
        assert!(!readiness.rls.forced);
        assert!(readiness.rls.migration_asset_present);
        assert!(!readiness.rls.tenant_context_configured);
        assert!(
            readiness
                .table_coverage
                .iter()
                .any(|table| table.table == "agents" && table.store_filters_tenant)
        );
        assert!(
            readiness
                .attention_items
                .iter()
                .any(|item| item.kind == "postgres_rls_incomplete")
        );
        assert!(readiness.attention_items.iter().any(|item| {
            item.kind == "tenant_production_routing_blocked" && item.severity == "critical"
        }));
    }

    #[tokio::test]
    async fn tenant_routed_mode_uses_request_tenant_context() {
        let mut state = test_state_with_worker(Arc::new(InlineExecutionWorker));
        state.tenant_runtime_mode = TenantRuntimeMode::TenantRouted;
        state.seed_demo_agent().await.expect("seed demo agent");
        let app = build_router(state);
        let alternate_tenant = "00000000-0000-4000-8000-000000000099";

        let default_agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(default_agents.len(), 1);

        let alternate_agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .header("x-mandoforge-tenant-id", alternate_tenant)
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(alternate_agents.len(), 1);

        let readiness: TenantIsolationReadinessReport = request_json(
            app,
            Request::builder()
                .uri("/api/tenant-isolation/readiness")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .header("x-mandoforge-tenant-id", alternate_tenant)
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(readiness.runtime_tenant_mode, "tenant_routed");
        assert_eq!(
            readiness.runtime_tenant_id,
            Uuid::parse_str(alternate_tenant).expect("valid tenant")
        );
        assert!(readiness.production_routing.cross_tenant_routing_supported);
        assert!(
            !readiness
                .production_routing
                .blocking_reasons
                .iter()
                .any(|reason| reason
                    == "runtime still serves one configured tenant instead of routing per tenant")
        );
        assert!(
            !readiness
                .attention_items
                .iter()
                .any(|item| item.kind == "single_runtime_tenant")
        );
    }

